  def isParent(par: Array[Int], x: Int): Boolean = {
    par(x) == x
  }

  def init(par: Array[Int]): Unit = {
    for (i <- par.indices) {
      par(i) = i
    }
  }


  def root(par: Array[Int], x: Int): Int = {
    if (par(x) == x) {
      x
    } else {
      par(x) = root(par, par(x))
      par(x)
    }
  }

  def same(par: Array[Int], x: Int, y: Int): Boolean = {
    root(par, x) == root(par, y)
  }

  def unite(par: Array[Int], x: Int, y: Int): Unit = {
    var (xx, yy) = (root(par, x), root(par, y))
    if (!(xx == yy))
      par(xx) = yy
  }
}

