ll ans(vector<vector<int>> field,int to,int end,int now){
    int mn = INF;
    int id;
    if(to==1)return now;
    rep(i,10){
        if(to==i)continue;
        if(mn>field[to][i]){
            mn = field[to][i];
            id = i;
        }
    }
    if(end==-1)end = field[to][1];
    else end = min(end,now+field[to][1]);
    now += mn;
    if(end<=now)return end;
    else return ans(field,id,end,now);
}

int main(){
    int h,w;cin>>h>>w;
    vector<vector<int>>field(10,vector<int>(10));
