    vector<int>mp(10);
    rep(i,h)rep(j,w){
        int a;cin>>a;
        if(a<0)continue;
        mp[a]++;
    }
    ll res = 0;
    rep(i,10){
        if(mp[i]<=0 || i==1)continue;
        res += ans(field,i,-1,0)*mp[i];
    }
    cout<<res<<endl;
}

