using namespace std;

const int INF = (int)1e9;
const int V = 10;

int H, W;
int cost[V][V];
int d[V];
bool used[V];
int cnt[V];

void dijkstra(int s) {
	fill(d, d + V, INF);
	fill(used, used + V, false);
	d[s] = 0;

	while (true) {
		int v = -1;
		for (int u = 0; u < V; u++) {
			if (!used[u] && (v == -1 || d[u] < d[v])) v = u;
		}
		if (v == -1) break;
		used[v] = true;
		for (int u = 0; u < V; u++) {
			d[u] = min(d[u], d[v] + cost[v][u]);
		}
	}
}

void input_data(void) {
	cin >> H >> W;
	for (int j = 0; j < V; ++j) {
		for (int i = 0; i < V; ++i) {
			cin >> cost[i][j];
			if (i == j)
				cost[i][j] = INF;
		}
	}
	fill(cnt, cnt + V, 0);
	for (int j = 0; j < H; ++j) {
		for (int i = 0; i < W; ++i) {
			int a;
			cin >> a;
			++cnt[a];
		}
	}
}

int main(void) {
	input_data();

	dijkstra(1);
	int ans = 0;
	for (int i = 0; i < V; ++i) {
		ans += cnt[i] * d[i];
	}

	cout << ans << '\n';
	return 0;
}

