vll memo(10, -1);

ll calc(vvll& c, ll i, unordered_set<ll>& seen) {
  if(memo[i] != -1) {
    return memo[i];
  }

  if(i == 1) {
    return 0;
  }

  //追加コスト最小を探す
  ll mcost = LLINF;
  rep(j, 10) {
    if(seen.find(j) == seen.end()) {
      seen.emplace(j);
      chmin(mcost, c[i][j] + calc(c, j, seen));
      seen.erase(j);
    }
  }

  return mcost;
}

signed main(void) {
  cin.tie(0); ios::sync_with_stdio(false);

  ll H, W;
