    rep(j, 10) {
      cin >> c[i][j];
    }
  }

  vvll A(H, vll(W));
  rep(i, H) {
    rep(j, W) {
      cin >> A[i][j];
    }
  }

  memo[1] = 0;

  vll mincost(10);  
  for(int i=0; i<=9; i++) {
    //if(i == 1) continue;
    unordered_set<ll> seen;
    seen.emplace(i);

    mincost[i] = calc(c, i, seen);
    memo[i] = mincost[i];
  }

  ll totalcost = 0;
  rep(i, H) {
    rep(j, W) {
      if(A[i][j] != -1) {
        totalcost += mincost[A[i][j]];
      }
    }
  }

  fin(totalcost);
}

