{
    int sum=0;
    Floyd();
    for(int i=1;i<=n;i++){
        for(int j=1;j<=m;j++){
            if(maze[i][j]!=-1){
                sum+=d[maze[i][j]][1];
            }
        }
    }
    printf("%d\n",sum);
}

