void rec(int now, int vc, bool used[]){
        ct[now]=min(ct[now], vc);
        for(int i=0;i<10;i++){
                if(now==i||used[i]){
                        continue;
                }
                else{
                        vc+=c[i][now];
                        used[i]=true;
                        rec(i, vc, used);
                        vc-=c[i][now];
                        used[i]=false;
                }
        }
}

