using namespace std;

vector<LL> dijkstra(long long S, long long N, vector<vector<long long>> edges){
    vector<LL> shortest(N, INF);
    priority_queue<pair<LL, LL>> q;
    q.push(make_pair(0, S));
    while(!q.empty()){
        auto src = q.top().second, l0 = q.top().first;
        q.pop();
        if(l0 >= shortest[src])continue;
        shortest[src] = l0;
        for(auto dst=0ll; dst<N; dst++){
            auto l1 = edges[src][dst];
            if(l1 < INF && l0+l1 < shortest[dst]){
                q.push(make_pair(l0+l1, dst));
            }

        }
    }
    return shortest;
}

void solve(long long H, long long W, std::vector<std::vector<long long>> c, std::vector<std::vector<long long>> A){
    vector<vector<LL>> edges(10, vector<LL>(10));
    for(int i=0; i<10; i++){
        for(int j=0; j<10; j++){
            edges[i][j]=c[j][i];
        }
    }

    auto shortest = dijkstra(1, 10, edges);
    LL ans=0;
    for(LL i=0; i<H; i++){
        for(LL j=0; j<W; j++){
            if(A[i][j]==-1)continue;
            ans+=shortest[A[i][j]];
        }
    }
    cout << ans << endl;
}

