// O(v^3) 負閉路にも使える
// vector<vector<ll>> dp(v, vector<ll>(v, INF)) dp[i][j]はiからjへのコスト
// https://qiita.com/ageprocpp/items/cdf67e828e1b09316f6e#%E3%83%80%E3%82%A4%E3%82%AF%E3%82%B9%E3%83%88%E3%83%A9%E6%B3%95
bool warshall_floyd(vector<vector<ll>> &dp, vector<edge> &edges, ll v) {
  ll e = edges.size();
  REP(i, e) { dp[edges[i].from][edges[i].to] = edges[i].cost; }
  REP(i, v) { dp[i][i] = 0; }

  REP(k, v) {
    REP(i, v) {
      REP(j, v) {
        if (dp[i][k] == INF || dp[k][j] == INF) continue;
        dp[i][j] = min(dp[i][j], dp[i][k] + dp[k][j]);
      }
    }
  }

  REP(i, v) {
    //負閉路を持つ
    if (dp[i][i] < 0) return false;
  }
  return true;
}

