    cin >> a;
    if (a != -1) cnt[a]++;
  }
  vector<vector<ll>> dist(v, vector<ll>(v, INF));
  warshall_floyd(dist, edges, v);
  ll ans = 0;
  REP(i, 10) {
    ans += cnt[i] * dist[i][1];
  }
  cout << ans << endl;
  return 0;
}

