void init ()
{
	for (int i = 0; i < 10; ++i) dist[i] = INF;
	dist[1] = 0;
	pq.emplace(0, 1);
}

void dijkstra ()
{
	input();
	init();

	int proc;
	while (!pq.empty())
	{
		proc = pq.top().second;
		pq.pop();

		if (visit[proc]) continue;
		visit[proc] = true;

		int temp;
		int adj;
		for (int i = 0; i < 10; ++i) {

			adj = i;
			temp = cost[proc][i] + dist[proc];

			if (temp < dist[adj]) {
				dist[adj] = temp;
				pq.emplace(temp, adj);
			}
		}
	}

	long long ans = 0;
	for (int i = 0; i < 10; ++i) {
		ans += (long long) dist[i]*freq[i];
	}

	cout << ans << "\n";

	return;
}

