void f(int cur, int cost, int st, vector<bool> check)
{
	if (pft[st] < cost) {
		return;
	}

	if (cur == 1) {
		pft[st] = cost;
		return;
	}

	for (int i = 0; i < 10; ++i) {
		if (check[i]) {
			continue;
		}
		check[i] = true;
		int newcost = cost + cg[cur][i];
		f(i, newcost, st, check);
		check[i] = false;
	}
}

