    for(int j=0;j<10;j++){
      int c;
      cin>>c;
      int jj=j,ii=i;
      if(jj==0){
        jj=1;
      }else if(jj==1){
        jj=0;
      }
      if(ii==0){
        ii=1;
      }else if(ii==1){
        ii=0;
      }

      edges[jj].emplace_back(ii,c);
    }
  }
  auto dij = Dijkstra<int>(edges,0);

  vector<int> cost;
  for (auto& i : dij) {
    cost.push_back(i);
  }

  int ans=0;
  for(int i=0;i<H;i++){
