// ワーシャルフロイド法 計算量はO(V^3) Vは頂点の数
void floyd(vi d[]){
    int V = sz(d[0]);
    rep(k,V) rep(i,V) rep(j,V){
        d[i][j] = min(d[i][j] , d[i][k] + d[k][j]);
    }
}

