struct Q {
public:
  int no;
  int cost;
  int visited;
};

template <class T> inline bool chmin(T& a, T b) {
  if(a > b) {
    a = b;
    return true;
  }
  return false;
}

int table[20][20];
int min_cost(int start) {
  queue<Q> qs;
  qs.push({start, 0, (1 << start)});

  int mc = table[start][1];

  while(!qs.empty()) {
    auto q = qs.front();
    qs.pop();
    if(q.no == 1) {
      chmin(mc, q.cost);
    }
    for(int i = 0; i < 10; ++i) {
      if(q.no == i) {
        continue;
      }
      if(q.visited & (1 << i)) {
        continue;
      }
      auto next_cost = q.cost + table[q.no][i];
      if(next_cost > mc) {
        continue;
      }
      qs.push({i, next_cost, q.visited | (1 << i)});
    }
  }
  return mc;
}

