void Warshall_Floyd (vector<vector<ll>>& distance){
    ll n = distance.size();
    for(ll i = 0; i < n; i++) distance[i][i] = 0;
    for(ll i = 0; i < n; i++){
        for(ll j = 0; j < n; j++){
            for(ll k = 0; k < n; k++){
                distance[j][k] = min(distance[j][i]+distance[i][k],distance[j][k]);
            }
        }
    }
}

