using namespace std;

vector<long long> cost(10, -1);
set<int> s;

long long dfs(int n, vector<vector<long long> > &c) {
    s.insert(n);
    long long rec = 1e9;
    if (cost[n] != -1) {
        rec = min(cost[n], rec);
        s.erase(n);
    }

    else if (n == 1) {
        rec = min(cost[1] = 0, rec);
        s.erase(n);
    }

    else  {
        for (int i = 0; i < 10; i++) {
            if (s.find(i) == s.end())
                rec = min(rec, dfs(i, c) + c[n][i]);
        }
        s.erase(n);
    }
    return rec;
}

int main() {
    int h, w;   cin >> h >> w;
    vector<vector<long long> > c(10, vector<long long>(10)), a(h, vector<long long>(w));
