int H, W;
int all;
int pre[2 * MaxN + 5], last[MaxN + 5], other[2 * MaxN + 5];
int cost[2 * MaxN + 5], dis[MaxN + 5];
bool inq[MaxN + 5];

void build(int x, int y, int w) {
	pre[++all] = last[x];
	last[x] = all;
	other[all] = y;
	cost[all] = w;
}

int SPFA(int s) {
	for(int i = 0; i <= 9; i++) dis[i] = inf;
	dis[s] = 0;
	queue <int> q;
	q.push(s);
	inq[s] = 1;
	while(!q.empty()) {
		int x = q.front();
		q.pop();
		for(int ed = last[x]; ed != -1; ed = pre[ed]) {
			int dr = other[ed];
			if(dis[x] + cost[ed] < dis[dr]) {
				dis[dr] = dis[x] + cost[ed];
				if(inq[dr] == 0) {
					inq[dr] = 1;
				}
				q.push(dr);
			}
		}
		inq[x] = 0;
	}
	return dis[1];
}

