	rep(i,10){
		rep(j,10) d[i][j] = INF;
		d[i][i] = 0;
	}
}

void warshall_floyd(int n){
	for(int k = 0; k < n; k++){
		for(int i = 0; i < n; i++){
			for(int j = 0; j < n; j++){
				if( d[i][k] == INF || d[k][j] == INF){
					// do nothing
				}else{
					d[i][j] = min(d[i][j],d[i][k] + d[k][j]);	
				}
			}
		}
	}
}


