struct Edge {
    unsigned int from, to;
    int cost;
    bool operator<(const Edge& edge) const {
        return this->cost < edge.cost;
    }
    bool operator>(const Edge& edge) const {
        return this->cost > edge.cost;
    }
};


class ShortestPath {
public:
    /**
     * start_nodeから他のすべてのnodeへの最短距離(到達できないnodeはINT_MAX)をもとめる
     * edgeに負の重みがある場合{}を返す
     * O(|V||E|)
     * @param start_node
     * @param node_size
     * @param edges
     * @return
     */
    vector<int> bellman_ford(int start_node, int node_size, vector<Edge> edges) {
        vector<int> dist_list(node_size, INT_MAX);
        dist_list[start_node] = 0;

        int i;
        for (i = 0; i < node_size; ++i) {
            bool update = false;
            for (auto e : edges) {
                unsigned int from = e.from, to = e.to;
                int cost = e.cost;
                if (dist_list.at(from) != INT_MAX && dist_list.at(to) > dist_list.at(from) + cost) {
                    dist_list.at(to) = dist_list.at(from) + cost;
                    update = true;
                }
            }
            if (!update) { break; }
        }
        if (i == node_size) {
            return{};
        }
        else {
            return dist_list;
        }
    }

    /**
     * startからすべての頂点への最小距離を求める O(|E| log |V|)
     * @param start
     * @param graph[node] = [(to1, cost1), (to2, cost2), ...]
     * @return
     */
    vector<int> dijkstra(int start, vector<vector<pair<int, int>>> graph) {
        unsigned long n = graph.size();
        priority_queue<pair<int, int>> que; //[(最短距離, node番号)]
        que.push({0, start});

        vector<int> prev_list(n, -1);
        vector<int> dist_list(n, INT_MAX);
        dist_list[start] = 0;

        while (!que.empty()) {
            int now_dist = que.top().first;
            int from = que.top().second;
            que.pop();

            if (dist_list[from] < now_dist) {
                continue;
            }
            for (pair<int, int> p : graph[from]) {
                int to = p.first;
                int dist = p.second;
                int new_dist = now_dist + dist;

                if (dist_list[to] > new_dist) {
                    prev_list[to] = from;
                    dist_list[to] = new_dist;
                    que.push({new_dist, to});
                }
            }
        }

        return prev_list;
    }


    /**
     * 全ノード間の最短距離をもとめる
     * O(|V|^3)
     * @param v[i][j]には辺e=(i,j)のコスト(辺が存在しない場合はINT_MAX)
     * @return
     */
    vector<vector<int>> warshall_floyd(vector<vector<int>> v) {
        unsigned long n = v.size();
        for (int i = 0; i < n; ++i) {
            v[i][i] = 0;
        }

        for (int m = 0; m < n; ++m) {
            for (int s = 0; s < n; ++s) {
                for (int e = 0; e < n; ++e) {
                    if (v[s][m] != INT_MAX && v[m][e] != INT_MAX) {
                        v[s][e] = min(v[s][e], v[s][m] + v[m][e]);
                    }
                }
            }
        }
        return v;
    }
};


