#define INFL 1000000000000000LL

using namespace std;

typedef long long ll;
typedef pair<ll, ll> pl;

vector<ll> dijkstra(ll s, vector< vector<pl> > e) {
    ll n = e.size();
    vector<ll> minD(n, INFL);
    minD.at(s) = 0;
    priority_queue< pl, vector<pl>, greater<pl> > q;
    q.push(pl(0, s));
    while (!q.empty()) {
        pl now = q.top();
        q.pop();
        ll c = now.first, v = now.second;
        if (minD.at(v) < c) continue;
        for (ll i = 0; i < e.at(v).size(); ++i) {
            pl p = e.at(v).at(i);
            if (minD.at(p.first) > minD.at(v) + p.second) {
                minD.at(p.first) = minD.at(v) + p.second;
                q.push(pl(minD.at(p.first), p.first));
            }
        }
    }
    return minD;
}

int main() {
    int h, w;
    ll c, a, ans = 0;
    scanf("%d%d", &h, &w);
    vector< vector<pl> > e(10, vector<pl>(9));
    for (int i = 0; i < 10; ++i) for (int j = 0; j < 10; ++j) {
        scanf("%lld", &c);
        if (i != j) e.at(i).at(j - (i < j)) = {j, c};
    }
    vector< vector<ll> > d(10, vector<ll>(10));
    for (int i = 0; i < 10; ++i) d.at(i) = dijkstra(i, e);
    for (int i = 0; i < h; ++i) for (int j = 0; j < w; ++j) {
        scanf("%lld", &a);
        if (a >= 0) ans += d.at(a).at(1);
    }
    printf("%lld\n", ans);
    return 0;
}

