// WarshallFloyd 法によりグラフにおける任意の2頂点間の最短距離を求める
// n : |V|
// dist : 距離行列

void WarshallFloyd(int n, int dist[MAXN][MAXN])
{
    for (int k = 0; k < n; ++k)
    {
        for (int i = 0; i < n; ++i)
        {
            for (int j = 0; j < n; ++j)
            {
                dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
            }
        }
    }
}

