const int INF = 10000000;
void Dijkstra(int s, int g){
  priority_queue<pair<int, int>, std::vector<P>, std::greater<P>> que ;
  for(int i = 0; i <= MAX_N; i++){
    dis[i] = INF;
  }
  que.push({0, s});
  dis[s] = 0;
  while(que.size()){
    P p = que.top();
    que.pop();
    for( int i = 0; i < Adjacency_list[p.second].size(); i++ ){
      if(Adjacency_list[p.second][i].first + dis[p.second]  < dis[Adjacency_list[p.second][i].second]){
        dis[Adjacency_list[p.second][i].second] = Adjacency_list[p.second][i].first + dis[p.second];
        que.push({dis[Adjacency_list[p.second][i].second],Adjacency_list[p.second][i].second });
      }
    }
  }
}

