long long memo[87];


long long ryuka(int n){
  long long ret;
  if(n == 0){
    return 2;
  } else if (n == 1){
    return 1;
  } else if(memo[n] != -1){
    ret = memo[n];
  } else {
    ret = ryuka(n-1) + ryuka(n-2);
    memo[n] = ret;
  }
  return ret;
}


