		return dist>r.dist;
	}bool operator<(const dii &r) const{
		return dist<r.dist;
	}
};
int d[MAX_N];			//distance
void pfs(int s){//start
	priority_queue<dii> q;
	fill(d,d+n,inf*0.9);d[s]=0;q.push({0,s});
	int cur;
	edge e;
	while(!q.empty()){
		dii p=q.top();q.pop();
		cur=p.i;
		if(d[cur]<p.dist)continue;
		rep(i,siz(g[cur])){
			e=g[cur][i];
			if(d[e.to]>d[cur]+e.cost){
				d[e.to]=d[cur]+e.cost;
				q.push({d[e.to],e.to});
			}
		}
	}
}

