void research_grid(std::vector< std::string >& grid, std::vector< std::vector< S_Edge > >& vedge)
{
  for (ll y = 0; y < H; y++) {
    for (ll x = 0; x < W; x++) {
      for (ll d = 0; d < 4; d++) {
	ll ny = y + dy[d];
	ll nx = x + dx[d];
	ll from = pos2idx( y,  x);
	ll to   = pos2idx(ny, nx);
	if (ny >= 0 && nx >= 0 && ny < H && nx < W) {
	  S_Edge edge;
	  edge.from = from;
	  edge.to   = to;
	  edge.cost = grid[ny][nx] == '#' ? INF : 1;
	  vedge[from].push_back(edge);
	}
      }
    }
  }
}

