ll get_distance_dijkstra(std::string& idx_grid, std::vector< std::vector< S_Edge > >& vedge)
{
  std::vector<ll> dist(V, INF);
  ll s = pos2idx(sy, sx);
  ll g = pos2idx(gy, gx);

  dist[s] = 0LL;
  typedef std::pair<ll, ll> P;
  std::priority_queue<P, std::vector<P>, std::greater<P> > que;
  que.push(P(dist[s], s));
  while (!que.empty()) {
    P p = que.top(); que.pop();
    ll v = p.second;
    for (auto edge : vedge[v]) {
      if (dist[edge.to] > dist[edge.from] + edge.cost) {
	dist[edge.to] = dist[edge.from] + edge.cost;
	que.push(P(dist[edge.to], edge.to));
      }
    }
  }

  return dist[g];
}

ll get_distance_warshallFloyd(std::string& idx_grid, std::vector< std::vector< ll > >& dist)
{
  ll s = pos2idx(sy, sx);
  ll g = pos2idx(gy, gx);

  for (ll k = 0; k < V; k++)
    for (ll i = 0; i < V; i++)
      for (ll j = 0; j < V; j++)
	dist[i][j] = std::min(dist[i][j], dist[i][k] + dist[k][j]);

  return dist[s][g];
}

ll get_distance_bellmanFord(std::string& idx_grid, std::vector< S_Edge >& vedge)
{
  std::vector<ll> dist(V, INF);
  ll s = pos2idx(sy, sx);
  ll g = pos2idx(gy, gx);

  dist[s] = 0LL;
  while(1) {
    bool was_updated = false;

    for (auto it = vedge.begin(); it != vedge.end(); it++) {
      if (dist[it->to] > dist[it->from] + it->cost) {
	dist[it->to] = dist[it->from] + it->cost;
	was_updated = true;
      }
    }
    if (!was_updated) {
      break;
    }
  }

  return dist[g];
}

ll get_distance_bfs(std::string& idx_grid, std::vector< std::vector< S_Edge > >& vedge)
{
  std::vector<ll> dist(V, INF);
  std::queue<ll> que;
  ll s = pos2idx(sy, sx);
  ll g = pos2idx(gy, gx);

  dist[s] = 0LL;
  que.push(s);
  while (!que.empty()) {
    ll v = que.front(); que.pop();
    for (auto edge : vedge[v]) {
      if (dist[edge.to] > dist[edge.from] + edge.cost) {
	dist[edge.to] = dist[edge.from] + edge.cost;
	que.push(edge.to);
      }
    }
  }
  return dist[g];
}

