void detcmin(int st, vector<vector<int>> &cmin, vector<vector<int>> &adj) {

  queue<int> q;
  q.push(st);
  cmin[st][st] = 0;
  while(!q.empty()) {
    int crt = q.front();
    q.pop();
    for (int i = 0; i <= 9; ++i) {
      if (cmin[st][crt] + adj[crt][i] < cmin[st][i] && adj[crt][i] != 0 && i != crt) {
        cmin[st][i] = cmin[st][crt] + adj[crt][i];
        q.push(i);
      }
    }
  }
}

