    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            cin >> A[i][j];
        }
    }
    // ダイクストラ法。グラフの方向を逆にして、各数字から1までの最短距離を求める
    priority_queue<P, vector<P>, greater<P>> pque;
    pque.push({0, 1});
    int d[10];
    for (int i = 0; i < 10; i++) d[i] = INF;
    d[1] = 0;
    while (pque.size() > 0) {
        P v = pque.top();
        pque.pop();
        if (d[v.second] < v.first) continue;
        for (int i = 0; i < 10; i++) {
            if (i != v.second && d[i] > d[v.second] + cmap[i][v.second]) {
                d[i] = d[v.second]+ cmap[i][v.second];
                pque.push({d[i], i});
            }
        }
    }
    // for (int i = 0; i < 10; i++) cout << d[i] << " ";
