vector<int> d;
void dijkstra(int s, vector<int>& d) {
    int n = 10;
    d.assign(n, INF);
    vector<bool> u(n, false);

    d[s] = 0;
    for (int i = 0; i < n; i++) {
        int v = -1;
        for (int j = 0; j < n; j++) {
            if (!u[j] && (v == -1 || d[j] < d[v])) 
                v = j;
        }

        if (d[v] == INF) break;

        u[v] = true;
        for (auto edge : conn[v]) {
            int to = edge.first;
            int len = edge.second;

            if (d[v] + len < d[to]) {
                d[to] = d[v] + len;
            }
        }
    }
}


