// Warshall–Floyd Algorithm
void WF (Vec<Vec<int> >& dp, int V) {
    FOR (i, 0, V) {
        FOR (j, 0, V) {
            FOR (k, 0, V) {
                dp[i][j] = min(dp[i][j], dp[i][k] + dp[k][j]);
            }
        }
    }
    return;
}

