unsigned min_dist(const std::vector< std::vector<unsigned> > &c, unsigned s)
{
  std::vector<unsigned> d(10, -1);
  d[s] = 0;

  std::vector<unsigned> q;
  for (unsigned i = 0; i <= 9; ++i) {
    q.push_back(i);
  }

  while (!q.empty()) {
    unsigned min = -1, min_vertex = -1, min_index = -1;
    for (unsigned i = 0; i < q.size(); ++i) {
      if (min >= d[ q[i] ]) {
        min = d[ q[i] ];
        min_vertex = q[i];
        min_index = i;
      }
    }

    unsigned t = q[min_index];

    auto itr = q.begin();
    std::advance(itr, min_index);
    q.erase(itr);

    for (unsigned i = 0; i <= 9; ++i) {
      if (d[i] > d[t] + c[t][i]) {
        d[i] = d[t] + c[t][i];
      }
    }
  }

  return d[1];
}

