using namespace std;

int min_cost(array<array<int, 10>, 10> &c, int n, int st,
             vector<vector<int>> &memo) {
  if (n == 1 || n < 0) {
    return 0;
  }

  if (memo[n][st] < 0) {
    int ans;
    bool fst = true;
    for (int i = 0; i <= 9; ++i) {
      if (i == n || (st & (1 << i))) {
        continue;
      }

      if (fst) {
        ans = min_cost(c, i, st | (1 << i), memo) + c[n][i];
        fst = false;
        continue;
      }

      ans = min(ans, min_cost(c, i, st | (1 << i), memo) + c[n][i]);
    }

    memo[n][st] = ans;
  }

  return memo[n][st];
}

int main(int argc, const char *argv[]) {
  int h, w;
  cin >> h >> w;

  array<array<int, 10>, 10> c;
  for (int i = 0; i < 10; ++i) {
    for (int j = 0; j < 10; ++j) {
      cin >> c[i][j];
    }
  }

  vector<vector<int>> va(w, vector<int>(h));
  vector<vector<int>> memo(10, vector<int>(5000, -1));
  int ans = 0;
  for (int i = 0; i < h; ++i) {
    for (int j = 0; j < w; ++j) {
      cin >> va[i][j];
      ans += min_cost(c, va[i][j], 0, memo);
    }
  }

  cout << ans << '\n';
}

