vector<long> dijkstra(vector<vector<pair<long, long>>>& w_graph, long s) {//sからの単一始点最短経路
	vector<long> res(w_graph.size(), INT_MAX);

	priority_queue<pair<long, long>, vector<pair<long, long>>, greater<pair<long, long>>> que;//距離と頂点のpair。距離をfirstに置く。
	res[s] = 0;

	que.emplace(res[s], s);

	while (!que.empty()) {

		long cost;//sからindexまでの距離
		long index;
		tie(cost, index) = que.top();
		que.pop();

		if (res[index] < cost) continue;
		for (pair<long, long> e : w_graph[index]) {

			long c, i;
			tie(i, c) = e;

			long newcost = cost + c;

			if (res[i] <= newcost) continue;
			res[i] = newcost;
			que.emplace(res[i], i);
		}

	}
	return res;
}

int main() {

	long H, W; cin >> H >> W;
	long res = 0;
	vector<vector<pair<long, long>>> w_graph(10);

	for (int i = 0; i <= 9; i++) for (int j = 0; j <= 9; j++) {// j -> i 変化を逆から走査。単一始点は1
		long c; cin >> c;
		w_graph[j].push_back(make_pair(i, c));
	}

	vector<long> Sp = dijkstra(w_graph, 1);

	for (int i = 0; i < H; i++) for (int j = 0; j < W; j++) {
		long A; cin >> A;
		if (A == -1) continue;
		res += Sp[A];
	}

	cout << res << endl;
}

