int dfs(int i, int rest){
  if (cost[i]< INF) return cost[i];
  if (rest < 0) return c[i][1];
  int ans = c[i][1];
  int m = 0;
  rep(j, 10){
    if (i == j) m = INF;
    else m = c[i][j] + dfs(j, rest - c[i][j]);
    ans = min(ans, m);
  }
  cost[i]= ans;
  return ans;
}

