using namespace std;
static const int MAX = 10;
static const int WHITE = 0;
static const int GRAY = 1;
static const int BLACK = 2;
static const int INFTY = (1 << 20);

int cost[MAX][MAX];
int d[MAX][MAX];
int wall_num_count[MAX];

// 数字numにおける1の変換コストを見つけるダイクストラ
void dijkstra(int num) {
    priority_queue<pair<int, int> > PQ;
    int color[MAX];
    for (int i = 0; i < 10; i++) {
        d[num][i] = INFTY;
        color[i] = WHITE;
    }

    d[num][num] = 0;
    PQ.push(make_pair(0, num));
    color[num] = GRAY;

    while (! PQ.empty()) {
        pair<int, int> f = PQ.top(); PQ.pop();
        int u = f.second;
        color[u] = BLACK;

        if (d[num][u] < f.first * (-1)) continue;

        for (int j = 0; j < MAX; j++) {
            int v = j;
            if (color[v] == BLACK) continue;
            if (d[num][v] > d[num][u] + cost[u][v]) {
                d[num][v] = d[num][u] + cost[u][v];
                PQ.push(make_pair(d[num][v] * (-1), v));
                color[v] = GRAY;
            }
        }
    }
}

int main() {
