    cin >> H >> W;
    for (int i = 0; i < MAX; i++) {
        for (int j = 0; j < MAX; j++) cin >> cost[i][j];
    }

    for (int i = 0; i < MAX; i++) {
        wall_num_count[i] = 0;
    }

    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            cin >> A;
            if (A != -1) wall_num_count[A]++;
        }
    }

    for (int i = 0; i < MAX; i++) {
        dijkstra(i);
    }

    for (int i = 0; i < MAX; i++) magic_count += d[i][1] * wall_num_count[i];

    cout << magic_count << endl;

    return 0;
}

