int dd[11];
void dfs(int x)
{
    ms.clear();
    for(int i=0; i<10; i++) dd[i]=1e8;
    ms.insert(mp(0, x));
    dd[x]=0;
    while(ms.size())
    {
        pair<int, int> p=*ms.begin();
        int node=p.S, w=p.F;
        ms.erase(ms.begin());
        if(w > dd[node]) continue;
        for(int i=0; i<10; i++)
        {
            int ch=i;
            if(dd[ch] > dd[node]+co[node][ch])
            {
                dd[ch]=dd[node]+co[node][ch];
                ms.insert({dd[ch], ch});
            }
        }
    }
}
