//ダイクストラ法
vll dijkstra(ll n, vector<vll> &c, ll start) {
  vll minc(n, inf);
  minc[start] = 0;

  for (ll i = 0; i < n - 1; i++) {
    priority_queue<vll, vector<vll>, greater<vll>> pq;
    for (ll j = 0; j < n; j++) {
      if (minc[j] == inf) continue;
      for (ll k = 0; k < n; k++) {
        if (minc[k] < inf) continue;
        pq.push({minc[j] + c[j][k], k});
      }
    }
    vll v = pq.top();
    minc[v[1]] = v[0];
  }

  return minc;
}

