void dfs(int step,int x)
{
	if(x==1)
	{
		ansx=min(ansx,sumx);
	//	cout<<ansx<<endl;
		return;
	}
	if(sumx>ansx)   return;
	else{
		for(int i=0;i<=9;i++)
		{
			if(i!=x)
			{
				sumx+=re[x][i];
				dfs(step+1,i);
				sumx-=re[x][i];				
			}

		}
	}
}
