int main()
{
	int H, W, r = 0;
	cin >> H >> W;
	for (int i = 0; i < 10; i++)
		for (int j = 0; j < 10; j++)
			cin >> c[i][j];
	for (int i = 0; i < H; i++)
		for (int j = 0; j < W; j++)
			cin >> A[i][j];
	for (int h = 0; h < H; h++) {
		for (int w = 0; w < W; w++) {
			if (A[h][w] < 0) continue;
			int d[10] = {};
			d[A[h][w]] = 1;
			priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> q;
			q.push(make_pair(1, A[h][w]));
			while (q.top().second != 1) {
				int u = q.top().second;
				q.pop();
				for (int i = 0; i < 10; i++) {
					int v = i;
					int l = c[u][v];
					if (d[v] && d[v] <= d[u] + l)
						continue;
					d[v] = d[u] + l;
					q.push(make_pair(d[v], v));
				}
			}
			r += d[1] - 1;
		}
	}
	cout << r << endl;
	return 0;
}

