namespace warshall_floyd {
  const int64_t INF = 1000000000;
  int64_t d[MAX_N][MAX_N];
  int n;

  void init(int m)
  {
    n = m;
    for (int i = 0; i < n; i++)
      for (int j = 0; j < n; j++)
        d[i][j] = i == j ? 0 : INF;
  }

  void add_edge(int u, int v, int64_t cost)
  {
    d[u][v] = cost;
  }

  void calc()
  {
    for (int k = 0; k < n; k++)
      for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
          d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
  }
}


