int dfs(int from, set<int> &route, int max_cost, int current_cost) {
    int ans = min(max_cost, current_cost + dp[from][1]);
    for (int i = 0; i <= 9; i++) {
        if (i == 1) continue;
        if (i == from)continue;
        if (route.find(i) != route.end()) continue;
        int next_cost = dp[from][i];
