}

#include<bits/stdc++.h>
using namespace std;
#define MOD 1000000007

int main() {

  int H,W;
  cin >> H >> W;

  vector<vector<int>> c(10,vector<int>(10)),A(H+1,vector<int>(W+1));

  for(int i = 0;i < 10;i++) {
    for(int j = 0;j < 10;j++) {
      cin >> c.at(i).at(j);
    }
  }


  for(int i = 1;i <= H;i++) {
    for(int j = 1;j <= W;j++) {
      cin >> A.at(i).at(j);
    }
  }

  int d[10],seen[10],D[10];

  D[1] = 0;

  for(int k = 0;k < 10;k++) {
    priority_queue<pair<int,int>> PQ;

    for(int i = 0;i < 10;i++) {
      d[i] = 100000000;
      seen[i] = 0;
    }

    PQ.push(make_pair(0,k));
    d[k] = 0;

    while(!PQ.empty()) {

      int u;
      pair<int,int> p = PQ.top();
      PQ.pop();
      u = p.second;

      seen[u] = 1;
      if(d[u] < p.first * (-1)) continue;

      if(seen[1]) {
        D[k] = d[1];
        break;
      }

      for(int i = 0;i < 10;i++) {
        if(!seen[i] && d[i] > d[u] + c.at(u).at(i))   {
          d[i] = d[u] + c.at(u).at(i);
          PQ.push(make_pair(d[i]*(-1),i));
        }
      }
    }
  }

  int ans = 0;
  for(int i = 1;i <= H;i++) {
    for(int j = 1;j <= W;j++) {
      if(A.at(i).at(j) != -1) ans += D[A.at(i).at(j)];
    }
  }

  cout << ans << endl;
}

