using namespace std;

struct pr{int to,cost;};

int main(){
	cin.tie(0),ios::sync_with_stdio(false);
	int h,w; cin>>h>>w;
	vector<vector<int>>c(10,vector<int>(10)); for(auto&i:c)for(auto&j:i)cin>>j;
	vector<int>mn(10); for(int i=0;i<10;++i)mn.at(i)=c.at(i).at(1);
	for(int y=0;y<10;++y){
		queue<pr>q; pr pus,rec;
		int least=mn.at(y);
		for(int x=0;x<10;++x){
			if(y!=x&&c.at(y).at(x)<least){
				pus.to=x,pus.cost=c.at(y).at(x);
				q.push(pus);
			}
		}
		while(q.size()){
			rec=q.front(); q.pop();
			if(rec.to==1)least=mn.at(y)=min(mn.at(y),rec.cost);
			else for(int x=0;x<10;++x){
				int yy=rec.to,spend=rec.cost;
				if(x==yy)continue;
				int tcost=spend+c.at(yy).at(x);
				if(tcost<least){
					pus.to=x,pus.cost=tcost;
					q.push(pus);
				}
			}
		}
	}//for(auto&i:mn)cout<<" "s<<i;cout<<"\n"s;
	int64_t ans=0;
	for(int i=0;i<h;++i){
		for(int j=0;j<w;++j){
			int a; cin>>a;
			if(a>0)ans+=mn.at(a);
		}
	}
	cout<<ans<<"\n"s;
}

