//* 最短路
struct edge {
	int from, to, cost;
};
//* ベルマンフォード法　負の経路があっても動作
//* もし負の閉路があればfalseを返す
bool bellmanFord(vector<edge>& es, vector<ll>& ds, int start) {
	for (auto& d : ds) d = INT64_MAX;
	ds[start] = 0;
	for (int n = 0; n < ds.size(); ++n) {
		for (int i = 0; i < es.size(); ++i) {
			edge e = es[i];
			if (ds[e.from] != INT64_MAX and
				ds[e.to] > ds[e.from] + e.cost) {
				ds[e.to] = ds[e.from] + e.cost;
				if (n == ds.size() - 1)
					return false;
			}
		}
	}
	return true;
}

