struct ST {
  pair<long long, long long> pos;
  long long x, cost;
  ST() {}
  ST(long long i, long long j, long long xx, long long c) {
    pos = {i, j};
    x = xx;
    cost = c;
  }
};

long long make_key (pair<long long, long long> x) {
  return x.first * 10 + x.second;
}

long long solve (long long x, vector<vector<long long>> &wall, vector<vector<long long>> &cost) {
  queue<ST> Q;
  Q.push(ST(-1, -1, x, 0));
  unordered_map<long long, bool> visited;

  long long mm = 1e9;
  while (!Q.empty()) {
    ST cur = Q.front(); Q.pop();
    visited[make_key(cur.pos)] = true;
    if (cur.x == 1) {
      mm = min(mm, cur.cost);
      continue;
    }

    for (long long k = 0; k < 10; ++k) {
      if (k == cur.x) continue;
      ST next = ST(cur.x, k, k, cur.cost + cost[cur.x][k]);
      if (visited.count(make_key(next.pos)) == 0) {
        Q.push(next);
      }
    }
  }

  return mm;
}

