int cost[10][10];
int a[202][202];
int dist[202][202];

main() {
    int h, w; scanf ("%d %d", &h, &w);
    for (int i = 0; i <= 9; i++) {
        for (int j = 0; j <= 9; j++) {
            scanf ("%d", &cost[i][j]);
            dist[i][j] = cost[i][j];
        }
    }
    for (int i = 1; i <= h; i++) {
        for (int j = 1; j <= w; j++) {
            scanf ("%d", &a[i][j]);
        }
    }
    for (int k = 0; k <= 9; k++) {
        for (int i = 0; i <= 9; i++) {
            for (int j = 0; j <= 9; j++) {
                dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
            }
        }
    }
    int ans = 0;
    for (int i = 1; i <= h; i++) {
        for (int j = 1; j <= w; j++) {
            if (a[i][j] == -1 || a[i][j] == 1) {
                continue;
            }
            ans += dist[a[i][j]][1];
        }
    }
    cout << ans;
}

