bool visited[10] ;
int cost[10][10]  , v , A[300][300] , mn[10] , ans ;

void backtrack(int u , int sum) {
    if(u == 1){
        ans = min(ans , sum) ;
        return ;
    }
    visited[u] = true ;
    for(int i = 0 ; i<10 ; i++){
        if((cost[u][i] + sum < ans) && 
                !visited[i]) {
            sum+=cost[u][i] ;
            backtrack(i , sum) ;
            sum-= cost[u][i] ;
        }
    }
    visited[u] = false ;
}

int main() {
    int h , w ;
    ll sum = 0LL ;
    scanf("%d %d" ,&h , &w) ;

