        for(int j = 0 ; j<10 ; j++) 
            scanf("%d" ,&cost[i][j]) ;
    for(int i = 0 ; i<h ; i++) 
        for(int j = 0 ; j<w ;j++) 
            scanf("%d" ,&A[i][j]) ;

    for(int i = 0 ;i<10 ; i++) {
        if(i == 1) mn[i] = 0 ;
        else {
            ans = cost[i][1] ;
            v = i ;
            backtrack(i , 0) ;
            mn[i]  = ans ;
        }
    }

    for(int i = 0 ; i<h ;i++)
        for(int j = 0 ; j<w ; j++) 
            if(A[i][j] != -1) sum+=(ll)mn[A[i][j]] ;

    printf("%lld\n" , sum) ;

    return 0 ;
}

