	que.push(mkp(0, 1));
	while(!que.empty())
	{
		int v = que.top().se, w = que.top().fi;
		que.pop();
		if (d[v] < w) continue;
		rep(i, 0, 10)
		{
			if (d[i] > c[i][v]+w)
			{
				d[i]=c[i][v]+w;
				que.push(mkp(d[i],i));
			} 
		}
	}
	LL ans = 0;
	rep(i, 0, h) rep(j, 0, w)
	{
		if (a[i][j]!=-1) 
		{
			ans += d[a[i][j]];
		}
 	}
 	printf("%lld\n",ans);
	return 0;
}

