// ＜仕様＞
// d[i][j]にはあらかじめその辺のコストを入れておく．
// ただし，辺が存在しない要素にはINFを入れ，d[i][i] = 0とする．
// 負閉路の検出には，d[i][i] < 0かどうかを見れば良い．

const ll INF = 2e9;

ll dist[505][505];

void warchall_floyd(int N){
    rep(k,N)rep(i,N){
        if(dist[i][k] == INF) continue;
        rep(j,N){
            if(dist[k][j] == INF) continue;
	        chmin(dist[i][j], dist[i][k]+dist[k][j]);
        }
    }
}

