ll ans(vector<vector<int>> field,int to,int end,int now){
    int mn = INF;
    int id;
    if(to==1)return now;
    rep(i,10){
        if(to==i)continue;
        if(mn>field[to][i]){
            mn = field[to][i];
            id = i;
        }
