	for(int i=0;i<=9;i++){
		if(i==1)continue;
		for(int j=0;j<=9;j++){
			bol[j]=0;
		}
		pq.push({0,i});
		while(!pq.empty()){
			int nowx,noww;
			noww=pq.top().first;
			nowx=pq.top().second;
			if(nowx==1){
