//----------------------------------------------------------------------

#define MAX 1000

#define INF 1<<30
#define NOT 0
#define VIS 1
#define COMP 2

ll stt[MAX];
ll w[MAX][MAX];
ll mini[MAX];

void dijkstra(ll st) {
  FOR(i, 0, n) {
	stt[i] = NOT;
	mini[i] = INF;
  }
  mini[st] = 0;

  while (1) {
	m = INF;
	FOR(i, 0, n) {
	  if (stt[i] != COMP && mini[i] < m) {
		m = mini[i];
		temp = i;
	  }
	}

	if (m == INF) {
	  break;
	}

	stt[temp] = COMP;

	FOR(i, 0, n) {
	  if (stt[i] != COMP && w[temp][i] != INF) {
		if (w[temp][i] + mini[temp] < mini[i]) {
		  mini[i] = w[temp][i] + mini[temp];
		  stt[i] = VIS;
		}
	  }
	}
  }

}

