//全点対最短経路問題(ワーシャル・フロイド法)でi -> jへ変換する最小コスト(最短経路)を求める
void warshall_floyd() {
    for(int k = 0; k < MX; ++k) 
        for(int i = 0; i < MX; ++i) 
            for(int j = 0; j < MX; ++j) 
                C[i][j] = min(C[i][j], C[i][k] + C[k][j]);
}

int main()
{
