    for(int i = 0; i < MX; ++i)
        for(int j = 0; j < MX; ++j) cin >> C[i][j];

    for(int i = 0; i < H; ++i) 
        for(int j = 0; j < W; ++j) cin >> A[i][j];

    warshall_floyd();

    ll res = 0;
    for(int i = 0; i < H; ++i) {
        for(int j = 0; j < W; ++j) {
            if(A[i][j] != -1)
                res += C[A[i][j]][1];
        }
    }

    cout << res << endl;

    return 0;
}

