namespace NyaGadget {}

namespace NyaGadget
{
	struct GT_WarshallFloyd
	{
		// 重み付きグラフは隣接行列とする
		vector<vector<long long>> g;

		/**
		@brief 初期化
		@param n 頂点数
		**/
		GT_WarshallFloyd(long long n)
		{
			g.resize(n);
			for (long long i = 0; i < n; i++)
				g[i].resize(n, LLONG_MAX);
			for (long long i = 0; i < n; i++) g[i][i] = 0;
		}

		/**
		@brief 全点対間最短路を求める
		@param res 最小距離
		@note
		 負の閉路がある場合falseを返す。
		**/
		bool Run(vector<vector<long long>>& res)
		{
			res = g;
			long long vmax = (long long)g.size();
			for (long long k = 0; k < vmax; k++)
			{
				for (long long i = 0; i < vmax; i++)
				{
					if (res[i][k] == LLONG_MAX) continue;
					for (long long j = 0; j < vmax; j++)
					{
						if (res[k][j] == LLONG_MAX) continue;
						res[i][j] = min(res[i][j], res[i][k] + res[k][j]);
					}
				}
			}
			for (long long i = 0; i < vmax; i++)
				if (res[i][i] < 0) return false;
			return true;
		}
	};
}

