void solve(int num, vector<int> vec, int cost){
    cost += c[num][vec.back()];
    vec.push_back(num);
    if(cost < m[num]){
        m[num] = cost;
    }
    for(int i=0;i<10;i++){
        bool flag = true;
        for(int j=0;j<vec.size();j++){
            if(vec.at(j) == i)
                flag = false;
        }
        if(flag)
            solve(i, vec, cost);
    }
}

