int dijkstra(int s) {
  int d[10];
  priority_queue<P, vector<P>, greater<P> > q;
  fill(d, d+10, INF);
  d[s] = 0;
  q.push(P(0, s));

  while(!q.empty()) {
    P p = q.top(); q.pop();
    int v = p.second;
    if (d[v] < p.first)
      continue;
    REP(i, 10) {
      if (d[i] > d[v] + C[v][i]) {
        d[i] = d[v] + C[v][i];
        q.push(P(d[i], i));
      }
    }
  }
  return d[1];
}

