const int INF = numeric_limits<int>::max();
vector<vector<ll>> Warshall_Floyd(int V, vector<vector<ll>>&dp) {
	for (int k = 0; k < V; k++) {
		for (int i = 0; i < V; i++) {
			for (int j = 0; j < V; j++) {
				if (dp[i][k] == INF || dp[k][j] == INF) {
					continue;
				}
				dp[i][j] = min(dp[i][j], dp[i][k] + dp[k][j]);
			}
		}
	}
	return dp;
}
