{
	int minn,v;

	for (int i = 0; i < 10; i++)
	{
		dis[i] = e[u][i];
	}

	vis[u] = 1;

	for (int i = 0; i < 9; i++)
	{
		minn = maxn;

		for (int j = 0; j <= 9; j++)
		{
			if (!vis[j] && dis[j] < minn)
			{
				v = j;
				minn = dis[j];
			}
		}

		vis[v] = 1;

		for (int k = 0; k < 10; k++)
		{
			dis[k] = min(dis[k],dis[v]+e[v][k]);
		}
	}
	return dis[1];
}

