        for(int j = 0; j < 10; ++j){
            cin >> c.at(i).at(j);
        }
    }

    vector<ll> d(10, numeric_limits<ll>::max());
    d.at(1) = 0;
    priority_queue<pair<ll, ll>> q;
    q.push(make_pair(- d.at(1), 1));
    while(!q.empty()){
        auto p = q.top();
        q.pop();
        if(- p.first > d.at(p.second)){ continue; }
        for(int j = 0; j < 10; ++j){
            if(j == p.second){ continue; }
            if(d.at(j) > - p.first + c.at(j).at(p.second)){
                d.at(j) = - p.first + c.at(j).at(p.second);
                q.push(make_pair(- d.at(j), j));
            }
        }
    }

    ll ans = 0;
    for(int i = 0; i < h; ++i){
        for(int j = 0; j < w; ++j){
            ll a;
            cin >> a;
            if(a != -1){
                ans += d.at(a);
            }
        }
    }
    cout << ans << endl;
    return 0;
}

