struct edge {
	ll ind;
	ll to;
	ll d;
};


///////////////////////////

struct dijkstra {

	ll N;
	vector<vector<edge>> g;
	ll s;

	vector<ll> ans;

	dijkstra(ll N0, ll s, vector<vector<edge>> g0) {//頂点数、始点、グラフ
		N = N0;
		g = g0;

		ans.assign(N + 1, INF);


		priority_queue<pair<ll, ll>> q;//(-キョリ、頂点)

		ans[s] = 0;
		q.push({ 0,s });

		while (!q.empty()) {
			auto x = q.top();
			q.pop();

			ll dis = -x.first;
			ll v = x.second;

			if (dis > ans[v]) { continue; }


			for (edge e : g[v]) {
				ll w = e.to;
				if (dis + e.d < ans[w]) {
					ans[w] = dis + e.d;
					q.push({ -ans[w], w });
				}
			}


		}
	}

	ll d(ll t) {//sからtまでの最短距離を出力
		return ans[t];
	}


};


