int inf = 1000000000;
int cost[10][10];
void floyd(){

    for(int k=0; k<10; k++){
        for(int i=0; i<10; i++){
            if(cost[i][k] == inf) continue;
            for(int j=0; j<10; j++){
                if(cost[k][j] == inf) continue;

                cost[i][j] = min(cost[i][j], cost[i][k]+cost[k][j]);
            }
        }
    }
}

int main(){
    int H, W; cin >> H >> W;
    vector<int> cnt(10, 0);

    for(int i=0; i<10; i++) for(int j=0; j<10; j++) cost[i][j] = inf;
    for(int i=0; i<10; i++) for(int j=0; j<10; j++) cin >> cost[i][j];

    for(int i=0; i<H; i++) for(int j=0; j<W; j++){
        int a; cin >> a;
        if(a != -1) cnt[a]++;
    }

    floyd();

    ll ans = 0;
    for(int i=0; i<10; i++){
        if(cnt[i] == 0 || i == 1) continue;
        ans += cost[i][1]*cnt[i];
    }
    cout << ans << endl;
}

