void findpath(vector<vector<int>> &c){
    vector<int> U(10);  //group in path
    U[1] = 1;
    for(int i=1;i<=9;i++){
        int mindis = 10000;
        int minindex =-1;
        for(int j=0;j<=9;j++){
            if(c[j][1] <= mindis && U[j] == 0){
                mindis = c[j][1];
                minindex = j;
            }
        }
        U[minindex] = 1;
        for(int j=0;j<=9;j++){
            if(U[j]==0){
                c[j][1] = min(c[j][1],c[j][minindex]+c[minindex][1]);
            }
        }
    }
    return;
}

