typedef pair<int, int> pii;
const int INF = 1e9;
int H, W;
int C[10][10];
int ans;
int to_1_cost[10];
void dijkstra() {
	int min_cost[10];
	priority_queue<pii, vector<pii>, greater<pii>> pq;
	for (int i = 0; i < 10; ++i) {
		fill(min_cost, min_cost + 10, INF);
		min_cost[i] = 0;
		pq.push(pii(0, i));
		while (!pq.empty()) {
			pii now = pq.top(); pq.pop();
			int cost = now.first;
			int id = now.second;
			for (int j = 0; j < 10; ++j) {
				int n_cost = C[id][j];
				if (cost + n_cost < min_cost[j]) {
					min_cost[j] = cost + n_cost;
					pq.push(pii(min_cost[j], j));
				}
			}
		}
		to_1_cost[i] = min_cost[1];
	}
}
int main(void) {
	cin >> H >> W;
	for (int i = 0; i < 10; ++i) for (int j = 0; j < 10; ++j) cin >> C[i][j];
	dijkstra();
	for (int i = 0; i < H; ++i) for (int j = 0; j < W; ++j) {
		int a; cin >> a;
		if (a >= 0) ans += to_1_cost[a];
	}
	cout << ans << endl;
}

