//Dijkstra法(c[i][j]は節点iから節点jへのコスト，startは始点番号，nは節点数)
vector<double> Dijkstra(vector<vector<double>>c, int start, int n)
{
	int i, j, min_j;

	double min;

	vector<double> dist(n, 99999); //dist[i]はstartからiへの最短コスト
	vector<bool> u(n, true); //u[i]はstartから節点iへのコストが未確定か否かを示す
	vector<int> prev(n, 0);  //prev[i]は節点iへ繋ぐ節点番号を格納


	//すべての節点へのコストを無限大とする
	for(i=0; i<n; i++){
		dist[i]=99999;
	}

	//始点のコストは0
	//u[start]=false;
	dist[start]=0;
	for(i=0; i<n; i++){
		//節点コストが確定していない点の中で，startからのコストが最小の節点min_jを求める
		min=999999;
		for(j=0; j<n; j++){
			if(min>dist[j]&&u[j]==true){
				min=dist[j]; min_j=j;
			}
		}
		//節点min_jのコストを決定する
		u[min_j]=false;
		for(j=0; j<n; j++){
			if(dist[j]>dist[min_j]+c[min_j][j]&&u[j]==true){
				dist[j]=dist[min_j]+c[min_j][j];
				prev[j]=min_j;
			}
		}
	}
	return dist;
}
int main(void)
{
