using namespace std;

int min_cost(array<array<int, 10>, 10> &c, int n, int st,
             vector<vector<int>> &memo) {
  if (n == 1) {
    return 0;
  }

  if (memo[n][st] < 0) {
    int ans;
    bool fst = true;
    for (int i = 0; i <= 9; ++i) {
      if (st & (1 << i)) {
        continue;
      }

      int cost = min_cost(c, i, st | (1 << i), memo) + c[n][i];
      if (fst || cost < ans) {
        ans = min_cost(c, i, st | (1 << i), memo) + c[n][i];
        fst = false;
      }
    }

    memo[n][st] = ans;
  }

  return memo[n][st];
}

