void bfs(int r)
{
    d[r][r] = 0;
    priority_queue< pair<int, int> > pq;

    pq.push(make_pair(0, r));
    while (!pq.empty())
    {
        pair<int, int> du = pq.top(); pq.pop();

        int u = du.second;
        int minv = -du.first;

        if (d[r][u] < -minv) continue;

        rep (i, 10)
        {
            if (i == u) continue;
            int w = c[u][i];
            if (d[r][i] > d[r][u] + w)
            {
                d[r][i]  = d[r][u] + w;
                pq.push(make_pair(-d[r][i], i));
            }
        }
    }
}

