			connect.AddDirectionalConnection(i,j,v);
		}
	}

	WarshallFloyd WF;
	WF.CalcShortestPath(connect);

	int sum = 0;
	REP(i,H){
		REP(j,W){
			int v=in();
			if(v>=0){
				sum += WF.GetDistance(v,1);
			}
		}
	}
	out(sum);
	return 0;
}

