struct edge{
    LL to;
    LL cost;
};

LL V;
vector<edge> graph[M];
LL d[M];

void dijkstra(LL s){
    priority_queue<P, vector<P>, greater<P>>    que;
    fill(d, d+V, INF);
    d[s] = 0;
    que.push(P(0, s));
    while(!que.empty()){
        P p = que.top();
        que.pop();
        LL v = p.second;
        if(d[v] < p.first)  continue;
        for(int i = 0;i < graph[v].size();i++){
            edge e = graph[v][i];
            if(d[e.to] > d[v]+e.cost){
                d[e.to] = d[v]+e.cost;
                que.push(P(d[e.to], e.to));
            }
        }
    }
}
