        while (!nodeHeap.empty()) {
            llong nowCost = nodeHeap.top().first;
            llong node = nodeHeap.top().second;
            nodeHeap.pop();

            if (minCost[node] <= nowCost) {
                continue;
            }

            minCost[node] = nowCost;

            FOR(i, 10) {
                if (i == node) {
                    continue;
                }
                llong newCost = nowCost + cost[node][i];
                nodeHeap.push(make_pair(newCost, i));
            }
        }

        return minCost[1];
    };

