int calc(int a, int arr)
{
    int b = c[a][arr];
    for (int i = 0; i < 10; i++)
    {
        if (a != i && c[a][arr] > c[a][i])
        {
            if (d[a][i] == -1)
            {
                b = min(calc(a, i) + calc(i, 1), b);
                d[a][i] = b;
            }
            else
            {
                b = min(d[a][i], b);
            }
        }
    }
    return b;
}
