bool cmpMagiMap(vector<vector<int>>& v1, vector<vector<int>>& v2) {
	bool result = true;
	for (size_t i = 0; i < v1.size(); i++) {
		for (size_t j = 0; j < v1[0].size(); j++) {
			if (v1[i][j] != v2[i][j]) {
				result = false;
				return false;
			}
		}
	}
	return true;
}

void updateMagiMap(vector<vector<int>>& magiMap) {
	for (int i = 0; i < 10; i++) {
		for (int j = 0; j < 10; j++) {
			for (int k = 0; k < 10; k++) {
				//i,j:座標 k:参照先の行を走査
				magiMap[i][k] = min(magiMap[i][k], magiMap[i][j] + magiMap[j][k]);
			}
		}
	}
}


