  vector<vector<int>> c(9-0+1, vector<int>(9-0+1));
  for(int i = 0 ; i < 9-0+1 ; i++){
    for(int j = 0 ; j < 9-0+1 ; j++){
      scanf("%d",&c[i][j]);
    }
  }
  vector<vector<int>> A(H, vector<int>(W));
  for(int i = 0 ; i < H ; i++){
    for(int j = 0 ; j < W ; j++){
      scanf("%d",&A[i][j]);
    }
  }
  #pragma GCC diagnostic pop
  solve(H, W, move(c), move(A));
  exit(EXIT_SUCCESS);
}

