class WarshallFloyd{
    public:
        vector<vector<int>> d;
        WarshallFloyd(vector<vector<int>> g) : d(g){
            int V=g.size();
            for(int i=0;i<V;i++) d[i][i]=0;

            for(int k=0;k<V;k++)
                for(int i=0;i<V;i++)
                    for(int j=0;j<V;j++)
                        d[i][j]=min(d[i][j],d[i][k]+d[k][j]);
        }

        int get(int i,int j){
            return d[i][j];
        }
};

