int K[310][310];//K[i][j]=iからjまで行く最短経路のコスト合計
int N,G[310][310]={};
//G[i][j]にはiからjへの辺が存在するならその重み、無いなら0を入れる
//負の重みがあるときにも使えるようにするため

void WarshallFloyd(){

  //初期化
  rep(i,N){
    rep(j,N){
      if(G[i][j] >= 0)K[i][j]=G[i][j];
      else K[i][j]=INF;//辺が存在しなければコストINF
    }
  }

  rep(k,N){
    rep(i,N){
      rep(j,N){
        //辺ikとkjの存在を条件に入れておかないと負の重みの辺があるときバグる
        if(K[i][j] > K[i][k]+K[k][j] && G[i][k]!=0 && G[k][j] != 0){
          K[i][j] = K[i][k]+K[k][j];
        }
      }
    }
  }

}  

