int dijkstra(const int c[N][N], int s, int t){
    vector<int> d(N);
    for(int i = 0; i < N; i++){
        d[i] = INF;
    }
    d[s] = 0;

    vector<int> q;
    for(int i = 0; i < N; i++){
        q.push_back(i);
    }

    while (q.size() != 0) {
        int v = q[0];
        for(int u : q){
            if(d[u] < d[v]){
                v = u;
            }
        }
        q.erase(remove(q.begin(), q.end(), v), q.end());

        for(int u = 0; u < N; u++){
            d[u] = min(d[u], d[v] + c[v][u]);
        }
    }

    return d[t];
}

