ll dijk(int s)
{
	priority_queue < pair <int, int> > pq;
	pq.push({0, s});

	ll dist[10];
	for(int i = 0; i < 10; i++)
		dist[i] = (1ll << 62);

	dist[s] = 0;	
	while(1)
	{
		int u = pq.top().second;
		pq.pop();

		if(u == 1)
			return dist[u];

		for(int v = 0; v <= 9; v++)
		{
			if(v == u)
				continue;

			if(dist[v] > dist[u] +c[u][v])
			{
				dist[v] = dist[u] +c[u][v];
				pq.push({-dist[v], v});
			}
		}
	}
}

