void solve(int start,int now, map<int,bool> mp , int bef , int c){
  if(c > m)
    ret;

  if(now == 1 ){
    m = min(c,m);
  }
  else{
    mp[now] = true;
    rep(i,0,10){
      if(!mp[i]){
