int m[10][10], d[10], c[10];

void dijkstra_init(){
	for(int i=0; i<10; i++){
		d[i]=INF;
		c[i]=WHITE;
	}
	return;
}

void dijkstra(int s){
	d[s]=0;
	while(1){
		int minv=INF, u=-1;
		for(int i=0; i<10; i++){
			if(minv>d[i] && c[i]!=BLACK){
				u=i;
				minv=d[i];
			}
		}
		if(u==-1) break;
		c[u]=BLACK;
		for(int v=0; v<10; v++){
			if(c[v]!=BLACK && m[u][v]!=INF){
				if(d[u]+m[v][u]<d[v]){
					d[v]=d[u]+m[v][u];
					c[v]=GRAY;
				}
			}
		}
	}
	return;
}

