#define MAX_V 10
struct edge {int to,cost;};
vector<edge> G[MAX_V];
int d[MAX_V];
void dijkstra(int start){
    priority_queue<P,vector<P>,greater<P>> Q;
    fill(d, d+MAX_V, INF);
    d[start]=0;
    Q.push(make_pair(0,start));
    while(!Q.empty()){
        P p=Q.top();
        Q.pop();
        int v=p.second;
        if(d[v]<p.first)continue;
        REPA(i,G[v]){
            edge e=G[v][i];
            if(d[e.to]>d[v]+e.cost){
                d[e.to]=d[v]+e.cost;
                Q.push(make_pair(d[e.to],e.to));
            }
        }
    }
}

int main(){
    cin.tie(0);ios::sync_with_stdio(0);cout<<fixed<<setprecision(10);
    int h,w;
    cin>>h>>w;

    REP(j,10)REP(i,10){
        int c;
        cin>>c;
        if(i!=j)G[i].push_back({j, c});
    }
    dijkstra(1);

    int ans=0;
    REP(i,h*w){
        int a;
        cin>>a;
        if(a>=0)
            ans+=d[a];
    }
    cout<<ans<<endl;

    return 0;
}

