#define FOR(i, a, b) for (LL i = (a); i < (b); ++i)
#define REP(i, n)    FOR(i, 0, n)
#define DEBUG true
#define $(x) {if (DEBUG) {cout << #x << " = " << (x) << endl;}}


inline LL calcMinCost(LL i, VVI& c) {
    VI x;
    REP(j, 10) {
        if (j != 1 && j != i) x.PB(j);
    }
    LL min_cost = c[i][1];
    do {
        FOR(j, 1, SZ(x) + 1) {
            LL cost = 0;
            LL prev = i;
            REP(k, j) {
                cost += c[prev][x[k]];
                if (cost >= min_cost) continue;
                prev = x[k];
            }
            if (cost >= min_cost) continue;
            cost += c[prev][1];
            if (cost < min_cost) min_cost = cost;
        }
    } while (next_permutation(ALL(x)));
    return min_cost;
}


