/* warshall_floyd.cpp
    ワーシャルフロイド法を用いて、全点間最短路を求める。

    初期化：dis[i][j] = iからjへの距離(辺がなければINF) (i≠j)
            dis[i][i] = 0
            prev[i][j] = i

    負閉路の検出：dis[i][i] < 0 となる i が存在するか

    verified:
        https://atcoder.jp/contests/abc143/tasks/abc143_e
*/

#include <bits/stdc++.h>
using namespace std;
const long long INF = 1e17;

// 多次元 vector 生成
template <class T>
vector<T> make_vec(size_t a) {
    return vector<T>(a);
}
template <class T, class... Ts>
auto make_vec(size_t a, Ts... ts) {
    return vector<decltype(make_vec<T>(ts...))>(a, make_vec<T>(ts...));
}

template <class T>
bool chmax(T &a, const T &b) {
    if (a < b) {
        a = b;
        return 1;
    }
    return 0;
}
template <class T>
bool chmin(T &a, const T &b) {
    if (b < a) {
        a = b;
        return 1;
    }
    return 0;
}

/* warshall_floyd(dis,prev)
    入力：初期化した dis, prev
    計算量：O(|V|^3)
    副作用：dis[i][j]にiからjへの最短路のコストを格納、prev[i][j]にiからjへの最短路でのjの1つ前の点を格納
*/
void warshall_floyd(vector<vector<long long>> &dis, vector<vector<long long>> &prev) {
    int V = dis.size();
    for (int k = 0; k < V; k++) {
        for (int i = 0; i < V; i++) {
            for (int j = 0; j < V; j++) {
                if (dis[i][k] + dis[k][j] < dis[i][j]) {
                    dis[i][j] = dis[i][k] + dis[k][j];
                    prev[i][j] = prev[k][j];
                }
            }
        }
    }
}

/* get_path(prev, s, t)
    入力：warshall_floyd で得た prev, スタート s, ゴール t
    出力：s から t への最短路のパス
*/
vector<int> get_path(const vector<vector<long long>> &prev, int s, int t) {
    vector<int> path;
    for (int cur = t; cur != s; cur = prev[s][cur]) {
        path.push_back(cur);
    }
    path.push_back(s);
    reverse(path.begin(), path.end());
    return path;
}

/* is_negative(dis)
    入力：warshall_floyd で得た dis
    出力：負の有向路を含むかどうか
*/
bool is_negative(const vector<vector<long long>> &dis) {
    int V = dis.size();
    for (int i = 0; i < V; i++) {
        if (dis[i][i] < 0) {
            return true;
        }
    }
    return false;
}

int main() {
    int H, W;
    cin >> H >> W;

    // initialization
    vector<vector<long long>> dis(10, vector<long long>(10, INF));
    vector<vector<long long>> prev(10);
    for (int i = 0; i < 10; ++i) {
        dis[i][i] = 0;
        prev[i] = vector<long long>(10, i);
    }

    // input
    for (int i = 0; i < 10; i++) {
        for (int j = 0; j < 10; j++) {
            long long c;
            cin >> c;
            dis[i][j] = c;
            // dis[t][s] = c;
        }
    }
    warshall_floyd(dis, prev);

    long long ans = 0;

    auto A = make_vec<long long>(H, W);
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            cin >> A[i][j];
            if (A[i][j] != -1) {
                ans += dis[A[i][j]][1];
            }
        }
    }

    cout << ans << endl;

    return 0;
}

