void mini(long long int X,long long  int Y) {

	if (G[X][Y] + R < r) {

		R = R + G[X][Y];
		return;
	}
	else {
		long long int y;
		long long int K = 100000000000;
		for (int i = 0; i < 10; i++) {

				if (i!=X&&G[X][i]<K) {
				K = G[X][i];
				y = i;
			}
		}
		R += K;
		if (R>=r) {
			R = 100000000000;
			return;
		}
		else {
			mini(y, Y);
		}
	}
}

void serch(long long int X,long long  int Y) {
	mini(X, Y);
}


