    for(int i = 0; i < h; i++){
        for(int j = 0; j < w; j++){
            int a; cin >> a;
            if(a == 1 || a == -1) continue;
            dijkstra(a);
            ans += d[1];
        }
    }
    cout << ans << endl;
}

