vector<vector<int>> dist(10, vector<int>(10, INT_MAX)); //distance[i]は始点(start)から頂点iへの最短距離が入る
bitset<10> used;

void Dijkstra(int start){ //start = 始点
    priority_queue<P, vector<P>, greater<P>> que;
    que.push(make_pair(0, start));
    while(!que.empty()){
        ll d, t; //d:startからの距離, t:行先
        tie(d, t) = que.top(); que.pop();
        if(used[t]) continue;   //探索済み
        used[t] = true, dist[start][t] = d;
        for(auto e : root[t]){
            if(dist[start][e.second] <= d + e.first) continue;
            que.push(make_pair(d + e.first, e.second));
        }
    }
}

