// iからjに変換する最小コスト 0=<i,j=<9
int min_r (int i, int j, vector<vector<int>> cij) {
  int a = cij.at(i).at(j);
  int cost = a;
  if (i < 0 || i > 10 || j < 0 || j > 10) {
    cout << "error" << endl;
    return -1;
  }
  else if (i == j) {
    return 0;
  }
  else {
  	for (int k=0; k<10; k++) {
      int itk = cij.at(i).at(k);
      if (cost > itk) {
        int ktj = cij.at(k).at(j);
        if (cost > itk + ktj) {
          cost = itk + ktj;
        }
        else if (cost > itk + min_r(k,j,cij)) {
          cost = itk + min_r(k,j,cij);
        }
      }
    }
  	return cost;
  }
}
