using namespace std;

#define INF 1e9;

int COST[10][10];

int status[11];
int cost[11];

void dijkstra(int s) {
	for (int i = 0; i < 10; i++) {
		status[i] = 0;
		cost[i] = INF;
	}

	cost[s] = 0;
	status[s] = 1;

	priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>>U;
	U.push(make_pair(cost[s], s));
	while (!U.empty()) {
		//探索が終わってない中でコスト最小の点
		int u = U.top().second; U.pop();

		if (status[u] == -1) continue;

		status[u] = -1;

		//コスト最少の点を探る
		for (int i = 0; i < 10; i++) {
			if (status[i] != -1) {
				if (cost[i] > cost[u] + COST[u][i]) {
					cost[i] = cost[u] + COST[u][i];
					status[i] = 1;
					U.push(make_pair(cost[i], i));
				}
			}
		}
	}
}

