void init(ll V, vvll& cost) {
  cost = vvll(V, vll(V, INF));
  rep(i, V) {
    // 自分自身へ移動するコストは0
    cost[i][i] = 0;
  }

  // edgeを引く
  // 例: iからjにコストcの辺を引く
  // d[i][j] = c
}

void warshall_floyd(ll V, vvll& cost) {
  for (int k = 0; k < V; k++) {
    for (int i = 0; i < V; i++) {
      for (int j = 0; j < V; j++) {
        cost[i][j] = min(cost[i][j], cost[i][k] + cost[k][j]);
      }
    }
  }
}

