void rec(const int table[10][10], const int &start, const int &u, const int &v, const int &end, const int &cost, int lookUpTable[10][10]) {
    int newCost = cost + table[u][v];

    if (v == end) {
        if (newCost < lookUpTable[start][end]) lookUpTable[start][end] = newCost;

        return;
    }

    if (lookUpTable[start][v] < newCost) return;

    lookUpTable[start][v] = newCost;

    int i;

    for (i = 0; i < 10; i++) {
        if (i != start && i != u && i != v) rec(table, start, v, i, end, newCost, lookUpTable);
    }
}

int getMinCost(const int table[10][10], const int &start, const int &end, int lookUpTable[10][10]) {
    int i;

    for (i = 0; i < 10; i++) if (start != i) rec(table, start, start, i, end, 0, lookUpTable);

    return lookUpTable[start][end];
}

