int solve(const int h, const int w, const vector<vector<int>> &C, const vector<vector<int>> &A) {
    vector<int> p(10); for (int i = 0; i < 10; ++i) p[i] = i;
    vector<int> dp(10); for (int i = 0; i < 10; ++i) dp[i] = INF;
    do {
        int cost = 0;
        for (int i = 0; i < 10; ++i) {
            if (p[i] == 1) break;
            cost += C[p[i]][p[i+1]];
        }
        dp[p[0]] = min(dp[p[0]], cost);
    } while (next_permutation(p.begin(), p.end()));
    int ans = 0;
    for (int i = 0; i < h; ++i) {
        for (int j = 0; j < w; ++j) {
            int x = A[i][j];
            if (x != -1) {
                ans += dp[x];
            }
        }
    }
    return ans;
}

