    for(int j = 0; j < W; j++){
      int num;
      cin >> num;
      if(num == -1) continue;
      ans += g.d[num];
      //cout << g.d[num] << ' ';
    }
    //cout << endl;
  }
  cout << ans << endl;
  return 0;
}

