template <std::uint_fast64_t Modulus> class modint {
  using u64 = std::uint_fast64_t;

public:
  u64 a;

  constexpr modint(const u64 x = 0) noexcept : a(x % Modulus) {}
  constexpr u64 &value() noexcept { return a; }
  constexpr const u64 &value() const noexcept { return a; }
  constexpr modint operator+(const modint rhs) const noexcept {
    return modint(*this) += rhs;
  }
  constexpr modint operator-(const modint rhs) const noexcept {
    return modint(*this) -= rhs;
  }
  constexpr modint operator*(const modint rhs) const noexcept {
    return modint(*this) *= rhs;
  }
  constexpr modint operator/(const modint rhs) const noexcept {
    return modint(*this) /= rhs;
  }
  constexpr modint &operator+=(const modint rhs) noexcept {
    a += rhs.a;
    if (a >= Modulus) {
      a -= Modulus;
    }
    return *this;
  }
  constexpr modint &operator-=(const modint rhs) noexcept {
    if (a < rhs.a) {
      a += Modulus;
    }
    a -= rhs.a;
    return *this;
  }
  constexpr modint &operator*=(const modint rhs) noexcept {
    a = a * rhs.a % Modulus;
    return *this;
  }
  constexpr modint &operator/=(modint rhs) noexcept {
    u64 exp = Modulus - 2;
    while (exp) {
      if (exp % 2) {
        *this *= rhs;
      }
      rhs *= rhs;
      exp /= 2;
    }
    return *this;
  }
};

struct Edge {
  ll to, cost;
  Edge(ll to, ll cost) : to(to), cost(cost) {}
};

typedef vector<vector<Edge> > AdjList; // 辺の情報
typedef vector<ll> dis_dijkstra; // 距離のvector

dis_dijkstra dijkstra(ll n ,AdjList A,ll st ,ll weigh){// 頂点数 n ,グラフ　A　,始点　st　,初期値 weigh
  dis_dijkstra DIS;
  vector<bool> chek;
  DIS = vector<ll>(n+1, LINF);
  chek = vector<bool>(n+1, 0); 
  DIS[st]=weigh;
  ll key=st;
  priority_queue <pair<ll,ll>> PQ;
  PQ.push(mp(weigh,st));
  while(!PQ.empty()){
    pair<ll,ll> f = PQ.top();
    PQ.pop();
    key=f.second;
    chek[key]=1;
    if(DIS[key] < f.first*(-1)){
      continue;
    }
    rep(j,A[key].size()){
      ll v = A[key][j].to;
      if(chek[v]==0 && DIS[v]>DIS[key]+A[key][j].cost){
        DIS[v] = DIS[key] + A[key][j].cost;
        PQ.push(mp(DIS[v]*(-1),v));
      }
    }
  }
  return DIS;
}

