	for (int i = 0; i < 10; ++i) {
		for (int j = 0; j < 10; ++j) {
			cin >> c;
			add_edge(i, j, c);
		}
	}

	vector<int> shortest_to_one(10);
	for (int i = 0; i < 10; ++i) {
		shortest_to_one[i] = shorted_path_to_one(10, i);
	}

