template<typename P, typename Q> ostream& operator << (ostream& os, pair<P, Q> p) { os << "(" << p.first << ": " << p.second << ")"; return os; }
template<typename T> ostream& operator << (ostream& os, vector<T> v) { os << "("; each (i, v) os << i << ", "; os << ")"; return os; }
template<typename K, typename V> ostream& operator << (ostream& os, map<K, V> m) { os << "{"; each (i, m) os << i << ", "; os << "}"; return os; }

typedef struct edge {
  ll to;
  ll cost;
} edge;
typedef vector<vector<edge>> G; // graph
typedef vector<Pll> GR; // graph result (cost, vertex num)

GR dijkstra(G &g, ll s) { // O(ElogV)
  priority_queue<Pll, vector<Pll>, greater<Pll>> q;
  GR res(g.size(), mkp(1e18, 0));

  res[s] = mkp(0, s);
  q.push(res[s]);

  while (!q.empty()) {
    auto p = q.top();
    q.pop();

    ll cost = p.first;
    ll pos = p.second;
    if (res[pos].first < cost) continue;

    each (j, g[pos]) {
      ll to = j.to;
      ll to_cost = j.cost + cost;
      if (to_cost >= res[to].first) continue;
      res[to].first = to_cost;
      q.push(mkp(to_cost, to));
    }
  }
  return res;
}

int main() {
  ll h, w;
  cin >> h >> w;

  G g(10);
  for (ll i = 0; i < 10; ++i) {
    for (ll j = 0; j < 10; ++j) {
      ll cost;
      cin >> cost;
      g[i].push_back(edge{.to=j, .cost=cost});
    }
  }

  ll ans = 0;
  for (ll i = 0; i < h; ++i) {
    for (ll i = 0; i < w; ++i) {
      ll n;
      cin >> n;
      if (n == -1) continue;
      if (n == 1) continue;
      auto res = dijkstra(g, n);
      ans += res[1].first;
    }
  }

  cout << ans << endl;

  return 0;
}

