// iからjに変換する最小コスト 0=<i,j=<9
int min_r (int i, int j, vector<vector<int>> cij) {
  int cost = cij.at(i).at(j);
  if (i < 0 || i > 10 || j < 0 || j > 10) {
    cout << "error" << endl;
    return -1;
  }
  else if (i == j) {
    return 0;
  }
  else {
  	for (int k=0; k<10; k++) {
      int itk = cij.at(i).at(k);
      int ktj = cij.at(k).at(j);
      if (cost > itk + ktj) {
        int b = min_r(i, k, cij) + min_r(k, j, cij);
        cost = b;
      }
    }
  	return cost;
  }
}
int main () {
  int H, W;
  cin >> H >> W;

  vector<vector<int>> cij;
  for (int i=0; i<10; i++) {
	for (int j=0; j<10; j++){
      cin >> cij.at(i).at(j);
    }
  }

  vector<vector<int>> aij;
  for (int i=0; i<H; i++) {
    for (int j=0; j<W; j++){
      cin >> aij.at(i).at(j);
    }
  }

  int power = 0;
  for (int i=0; i<H; i++) {
	for (int j=0; j<W; j++) {
      int n = aij.at(i).at(j);
      if(n > -1 && n != 1) {
        power += min_r(n, 1, cij);
      }
    }
  }

  cout << power << endl;
}

