const int maxn=100010;
typedef pair<int,int>PII;
typedef vector<PII>VII;
VII G[maxn];
int h,w;
void addedge(int from,int to,int weight)
{
    G[from].push_back(make_pair(to,weight));
}
void init(int n)
{
    for(int i=0;i<=n;i++)
    {
        G[i].clear();
    }
}
int vis[maxn],dis[maxn];
int n=10;
void dijkstra(int start)
{
    for(int i=0;i<=n;i++)
    {
        vis[i]=0;
        dis[i]=Inf;
    }
    dis[start]=0;
    priority_queue<PII,VII,greater<PII> > q;
    q.push(make_pair(dis[start],start));
    while(!q.empty())
    {
        PII p=q.top();
        int x=p.second;
        q.pop();
        if(vis[x]) continue;
        vis[x]=1;
        for(int i=0;i<G[x].size();i++)
        {
            int y=G[x][i].first;
            int d=G[x][i].second;
            if(!vis[y]&&dis[x]+d<dis[y])
            {
                dis[y]=dis[x]+d;
                q.push(make_pair(dis[y],y));
            }
        }
    }
}
int main()
{
    while(cin>>h>>w)
    {
        memset(dis,Inf,n);
        init(15);
        for(int i=0;i<10;i++)
        {
