class WarchallFloyd {
private:
    int N;
    vvii E;

    void init(int n) {
        N = n;
        E = vvii(n);
    }

public:
    WarchallFloyd() {}
    WarchallFloyd(int n) { init(n); }

    void add(int from, int to, ll dist) {
        E[from].push_back(make_pair(to, dist));
    }

    vvi solve() {
        vvi ret(N, vi(N, INF));
        REP (i, N) FORE (e, E[i]) {
            ret[i][e.first] = e.second;
        }
        REP (i, N) ret[i][i] = 0;

        REP (k, N) REP (j, N) REP (i, N) {
            ret[j][i] = min(ret[j][i], ret[j][k] + ret[k][i]);
        }
        return ret;
    }
};

