int n, m, all;
int pre[100005], last[100005], other[100005], seq[100005];
bool In[1005];
LL c[100005], dis[100005];
LL cost[20][20];


void Build(int x, int y, LL z)
{
	pre[++all] = last[x];
	last[x] = all;
	other[all] = y;
	c[all] = z;
}

void Bfs(int s)
{
	int h = 1, t = 1, now, ed, dr;
	seq[t] = s;
	for(int i = 0; i <= 9; i++) {
		if(i == s) {
			dis[i] = 0;
		}
		else dis[i] = 1ll << 60;
	}
	In[s] = 1;
	while(h <= t)
	{
		now = seq[h];
		ed = last[now];
		while(ed != -1){
			dr = other[ed];
			if(dis[now] + c[ed] < dis[dr])
			{
				dis[dr] = dis[now] + c[ed];
				if(!In[dr])
				{
					In[dr] = 1;
					seq[++t] = dr;
				}
			}
			ed = pre[ed];
		}
		In[now] = 0;
		h++;
	}
}
int main()
{
	memset(last, -1, sizeof(last));
	all = -1;
	scanf("%d%d", &n, &m);
	for(int i = 0; i <= 9; i++) {
		for(int j = 0; j <= 9; j++) {
			int x;
			scanf("%d", &x);
			Build(i, j, x);
		}
	}
	LL sum = 0;
	for(int i = 0; i <= 9; i++){
		memset(dis, 0, sizeof(dis));
		Bfs(i);
		for(int j = 0; j <= 9; j++) cost[i][j] = dis[j];
	}
	for(int i = 1; i <= n; i++) {
		for(int j = 1; j <= m; j++) {
			LL x;
			scanf("%d", &x);
			if(x != -1 && x != 1){
				sum += cost[x][1];
			}
		}
	}
	printf("%lld\n", sum);
}

