void dijksutra(int s){
    fill(done,done+10,false);
    fill(d,d+10,INF);
    d[s] = 0;
    while(true){
        int v = -1;
        for(int i = 0;i < V;i++){
            if(!done[i]){
                if(v == -1){
                    v = i;
                }
                if(!done[i]){
                    if(d[i] < d[v]){
                        v = i;
                    }
                }
            }
        }
        if(v == -1){
            break;
        }
        done[v] = 1;
        for(int i = 0;i < V;i++){
            d[i] = min(d[i],d[v] + cost[v][i]);
        }
    }
    return;
}

