int dp[2050][10];

bool isset(int mask, int i){return (mask&(1<<i));}

int solve(int mask, int cur){
    if(cur==1)return dp[mask][cur]=0;
    if(dp[mask][cur]!=-1)return dp[mask][cur];
    int cost = 1000000009;
    FREP(i,0,9){
        if(!isset(mask,i)){
            int newmask = (mask|(1<<i));
            cost = min(cost,costs[cur][i]+solve(newmask,i));
        }
    }
    return dp[mask][cur]=cost;
}

int main(){
    MSET(dp,-1);
    int h,w;
    cin>>h>>w;
    FREP(i,0,9)FREP(j,0,9)cin>>costs[i][j];
    FREP(i,1,h)FREP(j,1,w)cin>>digs[i][j];
    FREP(i,0,9)solve(0,i);
    int ss = 0;
    FREP(i,1,h){
        FREP(j,1,w){
            if(digs[i][j]==-1)continue;
            ss+=dp[0][digs[i][j]];
        }
    }
    cout<<ss<<"\n";
    return 0;
}

