class D {
	int h, w;
	static const int v{ 10 };
	int cost[v][v];
public:
	D()
	{
		cin >> h >> w;

		REP(i, v)
			REP(j, v)
			cin >> cost[i][j];
	}

	void init()
	{
		REP(a, v)
			REP(b, v)
				REP(c, v)
		{
			chmin(cost[a][c], cost[a][b] + cost[b][c]);
		}
	}

	void solve()
	{
		init();

		int ans{ 0 };
		REP(i, h * w)
		{
			int x;
			cin >> x;
			if (x != -1)
				ans += cost[x][1];
		}

		cout << ans << endl;
	}
};


