      rep(j, 10){
	if(vis[j] == 1) continue;
	dist[j] = min(dist[j], top.first + cij[top.second][j]);
	que.push({dist[j], j});
      }
    }

    cost[i] = dist[1];
  }

  ll ans = 0;
  rep(i, H){
    rep(j, W){
      if(A[i][j] != -1) ans += cost[A[i][j]];
