void solve(ll H, ll W, std::vector<std::vector<ll>> c,
           std::vector<std::vector<ll>> A) {

  vector<int> dist(10, 9);
  queue<int> que;
  dist[1] = 0;
  que.push(1);

  while (!que.empty()) {
    int v = que.front();
    que.pop();

    rep(i, 10) {
      if (v == i) {
        continue;
      }
      int d = c.at(i).at(v);
      int nd = dist[v] + d;

      if (nd < dist[i]) {
        dist[i] = nd;
        que.push(i);
      }
    }
  }

  ll result = 0;
  rep(i, H) {
    rep(j, W) {
      auto v = A.at(i).at(j);
      if (v != -1)
        result += dist.at(v);
    }
  }
  cout << result << endl;
}

