int color[MAX];

void dijkstra(){
    int minv;
    for (int i=0; i<MAX; i++){
        d[i] = INFTY;
        color[i] = WHITE;
    }

    d[1] = 0;
    color[0] = GRAY;
    while(true){
        minv = INFTY;
        int u = -1;
        for(int i=0; i<MAX; i++){
            if(minv>d[i] && color[i]!=BLACK){
                u = i;
                minv = d[i];
            }
        }
        if(u==-1) break;
        color[u] = BLACK;
        for(int v=0; v < MAX; v++){
            if(color[v]!=BLACK && c[u][v]!=INFTY){
                if(d[v]>d[u] + c[u][v]){
                    d[v] = d[u] + c[u][v];
                    color[v] = GRAY;
                }
            }
        }
    }
}
