      return false;
    dist.assign(n, vector<T>(n, numeric_limits<T>::max() / 2));
    // n回ダイクストラ
    for (int s = 0; s < n; ++s)
      dijkstra(s);
    return true;
  }
  inline T get(int s, int t) const { return dist[s][t]; }

private:
  bool bellman_ford()
  {
    // ベルマンフォードによりポテンシャルを導入
    h.assign(n, 0);
    for (int i = 0; i < n; ++i)
      for (int v = 0; v < n; ++v)
        for (Edge e : graph[v])
          if (h[e.dst] > h[v] + e.cost)
          {
            h[e.dst] = h[v] + e.cost;
            if (i == n - 1)
              return false;
          }
    return true;
  }

  void dijkstra(int s)
  {
    priority_queue<pair<T, int>, vector<pair<T, int>>, greater<pair<T, int>>> pq;
    dist[s][s] = 0;
    pq.emplace(0, s);
    while (!pq.empty())
    {
      T c = pq.top().first;
      int v = pq.top().second;
      pq.pop();
      for (Edge e : graph[v])
        if (dist[s][e.dst] > dist[s][v] + e.cost)
        {
          dist[s][e.dst] = dist[s][v] + e.cost;
          pq.emplace(dist[s][e.dst], e.dst);
        }
    }
    for (int i = 0; i < n; ++i)
      dist[s][i] += h[i] - h[s];
  }
};

int main()
{
  int H, W, c, A;
  cin >> H >> W;
  Johnson<int, true> js(10);
  for (int i = 0; i <= 9; ++i)
  {
    for (int j = 0; j <= 9; ++j)
