vector<vector<int>> dist(201, vector<int>(201, INF)); //dist[u][v]は辺(u,v)のコスト（辺が存在しない場合はINF、ただしdist[i][i] = 0

void Warshallfloyd(int n = 10){ //nは頂点数
    for(int i = 0; i < n; i++){      // 経由する頂点
        for(int j = 0; j < n; j++){    // 開始頂点
            for(int k = 0; k < n; k++){  // 終端
                dist[j][k] = min(dist[j][k], dist[j][i] + dist[i][k]);
            }
        }
    }
    return;
}

int main(void){

    scanf("%d %d", &H, &W);
    for(int i = 0; i <= 9; ++i){
