            dist[i][j] = a;
        }
    }
    for(int i = 0; i < H; ++i) for(int j = 0; j < W; ++j) scanf("%d", &A[i][j]);

    Warshallfloyd();

    int ans = 0;
    for(int i = 0; i < H; ++i){
        for(int j = 0; j < W; ++j){
            if(A[i][j] == -1 || A[i][j] == 1) continue;
            ans += dist[A[i][j]][1];
        }
    }
    printf("%d\n", ans);

    return 0;
