int cost[10];
char used[10];

void dijkstra(int g)
{
 int x, y, min;
 for(x = 0; x < 10; x++){
  cost[x] = INF;
  used[x] = 0;
 }
 cost[g] = 0;
 while(1){
  min = INF;
  for(x = 0; x < 10; x++){
   if(!used[x] && min > cost[x])
    min = cost[x];
  }
  if(min == INF) break;
  for(y = 0; y < 10; y++){
   if(cost[y] == min){
    used[y] = 1;
    for(x = 0; x < 10; x++){
     if(cost[x] > dist[x][y] + cost[y])
      cost[x] = dist[x][y] + cost[y];
    }
   }
  }
 }
}


