int least(int nw,int cost,int mn,vector<vector<int>>&c,vector<bool>psd){
	if(nw==1)return min(cost,mn);
	else if(cost>=mn) return mn;
	psd.at(nw)=true;
	for(int i=0;i<=9;++i){
		if(psd.at(i))continue;
		mn=least(i,cost+c.at(nw).at(i),mn,c,psd);
	}
	return mn;
}

