    rep(i,V) rep(j,V) cin >> cost[j][i];  // [i][j]じゃなくて[j][i]にすることで単一始点最短経路から単一終点最短経路になる
    int a[h][w];
    rep(i,h) rep(j,w) cin >> a[i][j];
    int64_t ans = 0;
    dijkstra(1);
    rep(i,h) {
        rep(j,w) {
            if (a[i][j] == -1) continue;
            ans += d[a[i][j]];
        }
    }
    cout << ans << endl;
}

