typedef long long ll;

static const int MAX = 10;
static const ll INFTY = (1LL << 32);

int n=10;
ll d[MAX][MAX];

// ワーシャルフロイド（全点対間最短経路(動的計画法)）
void floyd() {
	for (int k = 0; k < n; k++) {
		for (int i = 0; i < n; i++) {
			if (d[i][k] == INFTY) continue;
			for (int j = 0; j < n; j++) {
				if (d[k][j] == INFTY) continue;
				// 頂点 k を経由する場合としない場合の最小コストを求める
				d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
			}
		}
	}
}

int main() {
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < n; j++) {
