	for (int i = 0; i < 10; i++) {
		for (int j = 0; j < 10; j++) {
			ll c; cin >> c;
			if(i==j) continue;
			d[i][j] = min(d[i][j], c);
		}
	}
	floyd();

	vector<vector<int>> A(H);
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			int a; cin >> a;
			A[i].push_back(a);
		}
	}

	int ans=0;
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			if(A[i][j]==-1) continue;
			//cout << A[i][j] <<" "<< d[A[i][j]][1] << endl;
			ans += d[A[i][j]][1];
		}
	}

	cout << ans << endl;
}

