void dijkstra(int s)
{
	fill(d, d+V, INF);
	fill(used, used+V, false);
	d[s] = 0;

	while (true) {
		int v = -1;
		for (int u = 0; u < V; u++) {
			if (!used[u] && (v == -1 || d[u] < d[v])) v = u;
		}

		if (v == -1) break;
		used[v] = true;

		for (int u = 0; u < V; u++) {
			d[u] = min(d[u], d[v] + cost[v][u]);
		}

	}
}

int get_cost(int n) {
	if (DP[n] != -1) return DP[n];

	dijkstra(n);
	return DP[n] = d[1];
}

