#define NODE 301
long long dist[NODE][NODE];
void WF(int num)
{
	for(int k = 0; k < num; k++)
	{
		for(int i = 0; i < num; i++)
		{
			for(int j = 0; j < num; j++)
			{
				dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
			}
		}
	}
}

int main()
{
	int H, W;
	cin >> H >> W;
