	}
	vis[u] = 1;
	for(int i =0 ;i < 9;i++)//必须是小于9，不能等于，debug了好久。。。
	{
		int minn = inf ,v = -1;
		for(int j =0 ;j <= 9 ;j++)
		{
			if(!vis[j]&&dis[j]<minn)
			{
				v = j;
				minn = dis[j];
			}
		}
		vis[v] = 1;
		for(int j = 0; j <= 9 ;j++)
		{
			dis[j] = min(dis[j],dis[v]+c[v][j]);
		}
	}
	return dis[1];
}

