void dijkstra(int s, int d[]){
	priority_queue<pii, vector<pii>, greater<pii>> Q;
	Q.push(pii(0,s));
	d[s]=0;
	while(!Q.empty()){
		pii p=Q.top();Q.pop();
		for(auto q:G[p.second]){
			if(d[q.second]>d[p.second]+q.first){
				d[q.second]=d[p.second]+q.first;
				Q.push(q);
			}
		}
	}
}

