void bfs(vector<vector<int64>>& c) {
    queue<int64> q;
    for (int64 i=0; i<10; i++) {
        q.push(i);
        while(!q.empty()) {
            int64 u = q.front(); q.pop();
            for (int64 v=0; v<10; v++) {
                if (u == v) continue;
                for (int64 j=0; j<10; j++) {
                    if (u == i || v == i) continue;
                    if (c[u][v] > c[u][i] + c[i][v]) {
                        c[u][v] = c[u][i] + c[i][v];
                        q.push(v);
                    }
                }
            }
        }
    }
}

