class D {
	int h, w;
	int cost[10][10];
public:
	D()
	{
		cin >> h >> w;

		REP(i, 10)
			REP(j, 10)
			cin >> cost[i][j];
	}

	void init()
	{
		REP(a, 10)
			REP(b, 10)
				REP(c, 10)
		{
			chmin(cost[a][c], cost[a][b] + cost[b][c]);
		}
	}

	void solve()
	{
		init();

		int ans{ 0 };
		REP(i, h)
			REP(j, w)
		{
			int x;
			cin >> x;
			if (x != -1)
				ans += cost[x][1];
		}

		cout << ans << endl;
	}
};


