using namespace std;

int main() {
  int h,w;
  cin>>h>>w;
  vector<vector<int>>c(10,vector<int>(10));
  for(int i=0;i<10;i++){
    for(int j=0;j<10;j++) cin>>c[i][j];
  }
  vector<vector<int>>a(h,vector<int>(w));
  for(int i=0;i<h;i++){
    for(int j=0;j<w;j++) cin>>a[i][j];
  }
  vector<int>value(10);
  for(int i=0;i<10;i++) value[i]=0;
  vector<int>dp(10);
  for(int i=0;i<10;i++) dp[i]=100000;
  vector<pair<int,int>>one(10);
  for(int i=0;i<10;i++) {
    one[i].first=c[i][1];
    one[i].second=i;
  }
  sort(one.begin(),one.end());
  int left=1;
  int right=1;
  while(left<=9 && right<=9){
    if(one[left].first==one[right+1].first) {
      right++;
      if(right==9){
        for(int i=left;i<=right;i++){
          value[i]=c[one[i].second][1];
          for(int j=0;j<10;i++){
            value[i]=min(value[i],c[one[i].second][j]+dp[j]);
          }
          dp[i]=value[i];
        }
      }
    }
    else{
      for(int i=left;i<=right;i++){
          value[i]=c[one[i].second][1];
          for(int j=0;j<10;i++){
            value[i]=min(value[i],c[one[i].second][j]+dp[j]);
          }
          dp[i]=value[i];
        }
      left=right+1;
      right=left;
    }
  }
  long long ans=0;
  for(int i=0;i<h;i++){
    for(int j=0;j<w;j++){
      ans+=value[a[i][j]];
    }
  }
  cout<<ans<<endl;
}

