int dis[10];
int dist[10];
struct edge
{
	int to, cost; 
	edge() {};
	edge(int t, int c) { to = t, cost = c; }
};
vector <edge> G[10];
void dijkstra(int v)
{
	priority_queue <P, vector <P>, greater <P> > q;
	q.push(P(0, v));
	while (!q.empty())
	{
		int v = q.top().second;
		int d = q.top().first;
		q.pop();
		if (dis[v] < d) continue;
		rep(i, G[v].size())
		{
			edge e = G[v][i];
			if (dis[e.to] > dis[v] + e.cost)
			{
				dis[e.to] = dis[v] + e.cost;
				q.push(P(dis[e.to], e.to));
			}
		}
	}
}
int main()
{
	int h, w; cin >> h >> w;
	rep(i, 10)
	{
		rep(j, 10)
		{
			int c; cin >> c;
			G[i].push_back(edge(j, c));
		}
	}
	dist[1] = 0;
	rep(i, 10)
	{
		if (i == 1) continue;
		fill(dis, dis + 10, INF);
		dis[i] = 0;
		dijkstra(i);
		dist[i] = dis[1];
	}
