  }
  int a;
  multiset<int> m;
  rep(i,H) rep(j,W){
    cin >> a;
    m.insert(a);
  }
  ll ans=0;
  rep(i,10){
    int count=m.count(i);
    if(count!=0 && i!=1){
      ans+=1LL*(dijkstra(g,i)[1]*count);
    }
  }
  cout << ans << endl;



  return 0;

}

