vector<int> total_cost;

void dfs(int row_num, vector<int> visited, vector<vector<int>> costs, int cost_acc){
    if (row_num == 1){
        total_cost.push_back(cost_acc);
        return;
    }
    visited.push_back(row_num);
    for (int i=0;i<10;i++){
        if (find(visited.begin(), visited.end(), i) == visited.end()){
            dfs(i, visited, costs, cost_acc + costs[row_num][i]);
        }
    }

}


