const int MAX_N = (int)205;
const int INF = (int)1e7;
int H, W;
int cost[10][10];
int A[MAX_N][MAX_N];
int d[10][10];

int V = 10;
int E = 100;

edge es[105];

void shortest_path(int s) {
  d[s][s] = 0;
  while (true) {
    bool update = false;
    for (int i = 0; i < E; ++i) {
      edge e = es[i];
      if (d[s][e.from] != INF && d[s][e.to] > d[s][e.from] + e.cost) {
        d[s][e.to] = d[s][e.from] + e.cost;
        update = true;
      }
    }
    if (!update) break;
  }
}

