//頂点構造体
struct vertex{
    vector<int> edges_to; //各エッジの接続先のノード番号
    vector<int> edges_cost;   //各エッジのコスト

    //ダイクストラ用
    bool isDone;    //確定フラグ
    int current_cost;   //現在までのこのノードへの最小コスト
    //比較関数のオーバーロード
    bool operator<(const vertex& vertex1) const {
        return  current_cost < vertex1.current_cost;
    }
    bool operator>(const vertex& vertex1) const {
        return  current_cost > vertex1.current_cost;
    }

};

//ダイクストラ法
int dijkstra_algorithm(vector<vertex> vertexes, int start, int end)
{
    for(auto &e : vertexes)
    {
        e.isDone = false;
        e.current_cost = -1;
    }
    vertexes[start].current_cost = 0;
    priority_queue<vertex, vector<vertex>, greater<vertex>> q;
    q.push(vertexes[start]);
    while(!q.empty())
    {
        vertex doneNode = q.top();
        q.pop();
        if(doneNode.isDone) continue;
        doneNode.isDone = true;
        for(int i = 0; i < doneNode.edges_to.size(); i++)
        {
            int cost = doneNode.current_cost + doneNode.edges_cost[i];
            int to = doneNode.edges_to[i];
            if(vertexes[to].current_cost < 0 || cost < vertexes[to].current_cost)
            {
                vertexes[to].current_cost = cost;
                q.push(vertexes[to]);
            }
        }
    }
    return vertexes[end].current_cost;
}

