int mn_magic(int start, int goal, int howmany_change)
{
    if (howmany_change == 1) return c[start][goal];

    if (start == goal) return c[start][goal];

    int mn = mn_magic(start, goal, howmany_change - 1);
    for (int i = 0; i <= 9; i++)
    {
        if (i == goal) continue;
        mn = min(mn, mn_magic(start, i, howmany_change - 1) + c[i][goal]);
    }

    return mn;
}

