// 戻り値がtrueなら負の閉路を含む
bool bellman_ford(int n, int s) { // nは頂点数、sは開始頂点
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      for (int k = 0; k < n; k++) {
        if (j == k) continue;
        if (graph[j][s] > graph[j][k] + graph[k][s]) {
          graph[j][s] = graph[j][k]+graph[k][s];
        }
      }
    }
  }
  return false;
}

