vector<vector<int>> c(10, vector<int>(10)), d(10, vector<int>(10, -1));
int calc(int a, int arr, int count)
{
    if (count >= 10)
    {
        return 1001;
    }
    if (d[a][arr] == -1)
    {
        int b = c[a][arr];
        for (int i = 0; i < 10; i++)
        {
            if (a != i && c[a][arr] > c[a][i])
            {
                int r = 0, l = 0;
                if (d[a][i] == -1)
                {
                    r = calc(a, i, count + 1);
                    if (r < 1001)
                    {
                        d[a][i] = r;
                    }
                }
                if (d[i][arr] == -1)
                {
                    l = calc(i, arr, count + 1);
                    if (l < 1001)
                    {
                        d[i][arr] = l;
                    }
                }
                b = min(r == 1001 || l == 1001 ? 1001 : d[a][i] + d[i][arr], b);
            }
        }
        d[a][arr] = b;
    }
    return d[a][arr];
}
