ll get_min_dist(ll start, ll goal, const vector<vector<ll>>& cs)
{
    vector<ll> dp(10, 1e9);
    vector<ll> dp_n(10, 1e9);

    dp[start] = 0;
    for (ll i = 0; i < 10; ++i) {
        for (ll j = 0; j < 10; ++j) {
            for (ll k = 0; k < 10; ++k) {
                dp_n[k] = min(dp_n[k], dp[j] + cs[j][k]);
            }
        }
        dp = move(dp_n);
        dp_n.assign(10, 1e9);
    }

    return dp[goal];
}

void main_()
{
    ll H, W;
    cin >> H >> W;
    vector<vector<ll>> cs(10, vector<ll>(10));
    for (auto&& c : cs) {
        copy_n(istream_iterator<ll>(cin), 10, begin(c));
    }
    vector<vector<ll>> As(H);
    for (ll i = 0; i < H; i++) {
        copy_n(istream_iterator<ll>(cin), W, back_inserter(As[i]));
    }

    vector<ll> min_dists_to_1(10);
    for (ll i = 0; i < 10; i++) {
        min_dists_to_1[i] = get_min_dist(i, 1, cs);
    }

    ll ans = 0;
