        ans += accumulate(
            begin(As[i]), end(As[i]),
            0LL, [&min_dists_to_1](auto acc, auto n) {
                return acc + ((n < 0) ? 0 : min_dists_to_1[n]);
            });
    }

    cout << ans << endl;
}
