// assume costs is initialized to INF s
void bellmanford(int *c, int N, int s, int *costs) {
  costs[s] = 0;
  for (int k = 0; k < N; k++) {
    for (int i = 0; i < N; i++) {
      for (int j = 0; j < N; j++) {
        costs[i] = min(costs[i], costs[j] + c[j + i * N]);
      }
    }
  }
}

