  }

  // calculate lowest cost to change to 1 for each number
  int costs[10];
  for (int i = 0; i < 10; i++) {
    costs[i] = INF;
  }
  bellmanford(c, 10, 1, costs);

  // solve
  int ans = 0;
  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      if (A[j + i * W] >= 0) {
        ans += costs[A[j + i * W]];
      }
    }
  }
  printf("%d\n", ans);

  return 0;
}

