int color[MAX];
int d[MAX];

void dijkstra(){

    priority_queue<pii> PQ;
    REP(i, n){
        d[i] = INFTY;
        color[i] = WHITE;
    }

    d[1] = 0;
    PQ.push(make_pair(0,1));
    color[1] = GRAY;

    while( !PQ.empty() ){
        pii f = PQ.top(); PQ.pop();
        int u = f.second;

        color[u] = BLACK;

        if( d[u] < f.first * (-1) ) continue;

        REP(j, adj[u].size()){
            int v = adj[u][j].first;
            if ( color[v] == BLACK )  continue;
            if ( d[v] > d[u] + adj[u][j].second ) {
                d[v] = d[u] + adj[u][j].second;
                PQ.push(make_pair(d[v]*(-1), v));
                color[v] = GRAY;
            }
        }
    }

    // REP(i, n){
    //     cout << i << " " << ( d[i] == INFTY ? -1 : d[i] ) << endl;
    // }

}

