vector<vector<int>> warshall_floyd(int n, vector<vector<int>>& E){
    vector<vector<int>> d = E;
    for (int k = 0; k < n; k++){
        for (int i = 0; i < n; i++){
            for (int j = 0; j < n; j++){
                if (i == j) continue;
                int dk = d[i][k] + d[k][j];
                if (dk < d[i][j]){
                    d[i][j] = dk;
                }
            }
        }
    }
    return d;
}

