void dijkstra() {
	FOR(i, 0, 9) d[i] = 1e9;
	pq.push(ii(d[1]=0, 1));
	while (!pq.empty()) {
		int u = pq.top().se, du = pq.top().fi; pq.pop();
		if (d[u] != du) continue;
		FOR(i, 0, 9) {
			if (d[i]  > d[u] + c[u][i])
				pq.push(ii(d[i]=d[u]+c[u][i], i));
		}
	}
}

