ll V,E;
const ll MAX_V = 15;
const ll MAX_E = 15;
void warshall(vector<vector<ll>> &dp){

    // dpは初期化する．
    // dp[i][i]=0, dp[i][j]=(経路があればその値), (なければINF)

    for(ll k = 0; k < V; k++){
        for(ll i = 0; i < V; i++){
            for(ll j = 0; j < V; j++){
                dp[i][j] = min(dp[i][j], dp[i][k]+dp[k][j]);
            }
        }
    }
}

int main(){
    V = 10;
