    rep(i,V){
        dp[i][i] = 0;
    }
    rep(i,V)rep(j,E){
        cin >> dp[i][j];
    }

    warshall(dp);

    ll ans = 0;
    rep(i,H)rep(j,W){
        ll tmp; cin >> tmp;
        if(tmp==-1)continue;
        ans += dp[tmp][1];
    }

    cout << ans << endl;

    return 0;
}

