struct Edge {
    int to,cost;
    Edge (int t,int c) {
        to = t; cost = c;
    }
    bool operator>(const Edge& e)const {
        return cost > e.cost;
    } 
    bool operator<(const Edge& e)const {
        return cost < e.cost;
    }
};

int main (void) {
    int H,W;
    cin>>H>>W;
    vector<vector<int>> c(10,vector<int>(10));
    vector<vector<Edge>> G(10);
    REP(i,10) {
        REP(j,10) {
            int c;
            cin>>c;
            G[j].pb(Edge(i,c));
        }
    }
    priority_queue<Edge,vector<Edge>,greater<Edge>> pq;
    vector<int> dist(10,inf);
    vector<bool> used(10,false);
    dist[1] = 0;
    pq.push(Edge(1,0));
    while(pq.size()) {
        int from = pq.top().to;
        pq.pop();
        if (used[from]) continue;
        used[from] = true;
        REP(i,10) {
            int c = G[from][i].cost;
            int to = G[from][i].to;
            if (dist[to] > c + dist[from]) {
