using namespace std;
void dijkstra(int start, vector<uint64_t> &costs,
              unordered_map<int, vector<pair<int, uint64_t>>> &edges) {
  priority_queue<pair<uint64_t, int>, vector<pair<uint64_t, int>>,
                 greater<pair<uint64_t, int>>>
      q;
  costs[1] = start;
  q.push(make_pair(0, start));
  while (!q.empty()) {
    auto v = q.top();
    q.pop();
    for (auto &e : edges[v.second]) {
      if (v.first + e.second < costs[v.second]) {
        costs[e.first] = v.first + e.second;
        q.push(make_pair(costs[e.first], e.first));
      }
    }
  }
}

