using namespace std;

int N = 10;
int H, W;

vector<int> dijkstra(int s, vector<vector<pair<int, int>>> adj) {
    vector<bool> visit(N);
    vector<int> dist(N, 1e9), par(N);
    priority_queue<pair<int, int>> q;
    dist[s] = 0; q.push(make_pair(0, s)); visit[s] = true;
    while (!q.empty()) {
        pair<int, int> tmp = q.top(); q.pop();
        int t = tmp.second; visit[t] = true;
        if (dist[t] < tmp.first * (-1) ) continue;  //別のルートでdist[t]が更新されていれば無視
        for (int i = 0; i < adj[t].size(); i++) {
            int next = adj[t][i].first;
            if (visit[next]) continue;
            if (dist[next] > dist[t] + adj[t][i].second) {
                dist[next] = dist[t] + adj[t][i].second;
                par[next] = t;
                q.push(make_pair(dist[next] * (-1), next));
            }
        }
    }
    return dist;
}

int main() {
    cin >> H >> W;
    vector<vector<pair<int, int>>> adj(N, vector<pair<int, int>>(N));
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            int d;
            cin >> d;
            adj[j][i] = make_pair(i, d);
        }
    }
    vector<int> dist = dijkstra(1, adj);
    long long ans = 0;
    for (int i = 0; i < H * W; i++) {
        int a; cin >> a;
        ans += dist[a];
    }
    cout << ans << endl;
}

