/*
    ワーシャルフロイド法
    vvc<ll> dist(n,vc<ll>(n,INF));

    下のようにして距離を保存してください
    rep(i,m){
        int a,b,c; cin >> a >> b >> c;
        a--; b--;
        dist[a][b] = c;
        dist[b][a] = c;
    }

    distに i -> j の最短距離が入ります
    dist[i][j] が負の値の場合　負閉路です
*/

void war(vvc<ll>& dist){
    ll n = SIZE(dist);
    rep(k,n) rep(i,n) rep(j,n){
        chmin(dist[i][j], dist[i][k] + dist[k][j]);
    }
}

