void shortest_path(int s) {
  d[s][s] = 0;
  while (true) {
    bool update = false;
    for (int i = 0; i < E; ++i) {
      edge e = es[i];
      if (d[s][e.from] != INF && d[s][e.to] > d[s][e.from] + e.cost) {
