struct Checked {

        bool checked[10];

        Checked(int n) {
                memset(checked, 0, sizeof(checked));
                checked[n] = true;
        }

        Checked(const Checked &src) {
                memcpy(checked, src.checked, sizeof(checked));
        }

        bool pass(int n) const {
                return checked[n];
        }
};

ll f(int n, const Checked &checked)
{
        if (n == 1) return 0;

        ll ret = 10000000000LL;

        rep (i, 10) {
                if (checked.pass(i)) continue;
                Checked nchecked = Checked(checked);
                nchecked.checked[i] = true;
                ret = min(ret, f(i, nchecked) + c[n][i]);
        }

        return ret;
}

