void warshall_floyd(vector<vector<ll>> &d) {
	ll node_size=d.size();
	for (int k=0; k<node_size; k++) {
		for (int i=0; i<node_size; i++) {
			for (int j=0; j<node_size; j++){
				if(d[i][k] != INF && d[k][j] != INF){
					d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
				}
			}
		}
	}
}


