void rec(const vector<int> used, int now, int before, int firstNumber)
{
    if (before == 1)
    {
        minTemp = (minTemp < now) ? minTemp : now;
    }
    else
    {
        if (firstNumber > before)
        {
            rec(used, now + minPower[before], 1, firstNumber);
        }
        else
        {
            for (int i = 0; i < used.size(); i++)
            {

                vector<int> cop = used;
                int temp = cop[i];
                cop.erase(cop.begin() + i);
                rec(cop, now + c[before][temp], temp, firstNumber);
            }
        }
    }
}

