    for (int i = 0; i < 10; i++) {
        for (int j = 0; j < 10; j++) {
            cin >> dist[i][j];
        }
    }
    warshall_floyd(10);
    int ans = 0;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            int a;
            cin >> a;
            if (a == -1) continue;
            ans += dist[a][1];
        }
    }
    cout << ans << endl;
    return 0;
}

