void dfs(ll now) {
    rep(i, 10) {
        if (!visited[i]) {
            if (d[now] + c[i][now] < d[i]) {
                d[i] = d[now] + c[i][now];
                visited[i] = true;
                dfs(i);
                visited[i] = false;
            }
        }
    }
