int memo[10];

int getMinCost(int start){
  int dist[10], update;

  if(memo[start] != -1){
    return memo[start];
  }

  for(int i=0; i<10; i++){
    dist[i] = INF;
  }
  dist[start] = 0;

  update = 1;
  while(update) {
    update = 0;
    for(int i=0; i<10; i++){
      for(int j=0; j<10; j++){
        if(i == j) continue;
        if(dist[j] > dist[i] + c[i][j]){
          dist[j] = dist[i] + c[i][j];
          update = 1;
        }
      }
    }
  }

  return dist[1];
}

