#include <bits/stdc++.h>

using namespace std;
using ll = long long;

using Graph = vector<vector<pair<int, ll>>>;

vector<ll> dijkstras(const Graph &g, int start) {
  int n = g.size();
  const ll inf = 1e18;
  vector<ll> d(n, inf);

  auto compare = [](const auto &l, const auto &r) {
    return l.second > r.second;
  };
  priority_queue<pair<int, ll>, vector<pair<int, ll>>, decltype(compare)> q{
      compare};
  d[start] = 0ll;
  q.push({start, 0ll});

  while (!q.empty()) {
    auto p = q.top();
    q.pop();
    if (p.second > d[p.first])
      continue;
    d[p.first] = p.second;
    for (const auto &pp : g[p.first]) {
      if (d[pp.first] != inf)
        continue;
      ll cost = p.second + pp.second;
      q.push({pp.first, cost});
    }
  }

  return d;
}

