struct Weighted_Graph {
  struct edge { ll node, cost; };
  vector<vector<edge>> e;

  void set(ll x){ e.resize(x + 1); }

  void add_edge(ll a, ll b, ll c) { e[a].pb(edge{ b,c }); }

  vll dijkstra(ll start) {
	priority_queue<pll, vector<pll>, greater<pll>> pq;
	ll u;
	pll p;
	vll dist(e.size(), inf);
	dist[start] = 0;
	pq.push(pll(0, start));

	while (!pq.empty()) {
	  p = pq.top(); pq.pop();
	  u = p.second;
	  if (dist[u] < p.first) continue;
	  for (edge e1 : e[u]) {
		if (dist[e1.node] > dist[u] + e1.cost) {
		  dist[e1.node] = dist[u] + e1.cost;
		  pq.push(pll(dist[e1.node], e1.node));
		}
	  }
	}
	return dist;
  }

  void floyd(vvll &dist) {
	ll x = e.size();
	dist.resize(x);
	rep(i, x) dist[i].resize(x, inf);
	rep(i, x) rep(j, e[i].size()) dist[i][e[i][j].node] = e[i][j].cost;
	rep(k, x) {
	  rep(i, x) {
		if (dist[i][k] == inf) continue;
		rep(j, x) {
		  if (dist[k][j] == inf) continue;
		  dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
		}
	  }
	}
  }

};

