#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
using P = pair<int, int>;

//dijkstraっぽい
vector<int> dijkstra(vector<vector<P>> G) {
    const int INF = 1e9;
    int N = G.size();
    vector<int> dist(N, INF);
    dist[1] = 0;
    priority_queue<P, vector<P>, greater<P>> pq;
    pq.emplace(P(dist[1], 1));
    while(pq.size()) {
        P p = pq.top();
        pq.pop();
        int d = p.first;
        int v = p.second;
        if (dist[v] < d) continue;

        for (int i = 0; i < G[v].size(); i++) {
            P e = G[v][i];
            int cost = d + e.second;
            int nv = e.first;
            if (cost < dist[nv]) {
                dist[nv] = cost;
                pq.emplace(P(dist[nv], nv));
            }
        }
    }
    return dist;
}

int main() {
    int H, W; cin >> H >> W;
    vector<vector<P>> G(10);
    for (int i = 0; i < 10; i++) {
        for (int j = 0; j < 10; j++) {
            int c; cin >> c;
            G[j].push_back(P(i, c));
        }
    }
    vector<int> vec = dijkstra(G);
    ll ans = 0;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            int a; cin >> a;
            if (a == -1) continue;
            else ans += vec[a];
        }
    }

    cout << ans << endl;
}

