int t[10][10];
int m[10];
bool visit[10];

int dfs(int i) {
    if (i == 1) return 0;
    if (m[i] > -1) return m[i];
    if (visit[i]) return -1;
    int mn = INT_MAX;
    visit[i] = true;
    for (int j = 0; j < 10; j++) {
        int cur = dfs(j);
        if (cur != -1) {
            mn = min(mn, cur + t[i][j]);
        }
    }
    m[i] = mn;
    visit[i] = false;
    return mn;
}

