        for (int j = 0; j < 10; j++) {
            scanf(" %d", &t[i][j]);
        }
    }
    fill(m, m + 10, -1);
    fill(visit, visit + 10, false);
    for (int i = 0; i < 10; i++) {
        if (!visit[i]) {
            m[i] = dfs(i);
        }
    }
    int ans = 0;
    forn(i, 0, h) {
        forn(j, 0, w) {
            int x;
            scanf(" %d", &x);
            if (x != -1) {
                ans += m[x];
            }
        }
    }
    printf("%d\n", ans);
    return 0;
}

