/// template

class DirectedGraph {
public:
    int V;
    vector<vector<int> > costs; //0-indexed

    DirectedGraph(int v) : V(v), costs(v, vector<int>(v, INF)) {
        for (int i = 0; i < V; i++) {
            costs[i][i] = 0;
        }
    }

    void add_edge(int u, int v, int cost) {
        costs[u][v] = cost;
    }

    void warshall_floyd() {
        for (int k = 0; k < V; k++) {
            for (int i = 0; i < V; i++) {
                for (int j = 0; j < V; j++) {
                    if(costs[i][k]!=INF && costs[k][j]!=INF) costs[i][j] = min(costs[i][j], costs[i][k] + costs[k][j]);
                }
            }
        }
    }
};



