using vi = vector<int>;
using vvi = vector<vi>;

int main()
{
    ios_base::sync_with_stdio(0);

    int u = 10;

    vvi cost(u, vi(u));

    int h, w; cin >> h >> w;

    for(int i = 0; i < u; i++)
    for(int j = 0; j < u; j++)
        cin >> cost[i][j];

    vvi v(h, vi(w));

    for(int i = 0; i < h; i++)
    for(int j = 0; j < w; j++)
        cin >> v[i][j];

    vi dist(u, INT_MAX);
    set<vi> q;

    dist[1] = 0;
    q.insert({0, 1});

    while(!q.empty())
    {
        auto elt = *begin(q); q.erase(elt);

        int c = elt[0];
        int k = elt[1];

        for(int i = 0; i < u; i++) if(i != k)
        {
            int newc = c + cost[i][k];

            if(newc < dist[i])
            {
                dist[i] = newc;
                q.insert({dist[i], i});
            }
        }
    }

    int ans = 0;

    for(int i = 0; i < h; i++)
    for(int j = 0; j < w; j++) if(v[i][j] != -1)
        ans += dist[v[i][j]];

    cout << ans << endl;
    return 0;
}

