void dijkstra(int s){
    //Pii first: 距離　second: 頂点
    priority_queue<PII, vector<PII>, greater<PII>> que;
    fill(ALL(d), INF);
    d[s] = 0;
    que.push(MP(0, s));

    while(!que.empty()){
        PII p = que.top(); que.pop();
        int v = p.second;
        if(d[v] < p.first) continue;
        REP(i, G[v].size()){
            edge e = G[v][i];
            if(d[e.to] > d[v] + e.cost){
                d[e.to] = d[v] + e.cost;
                que.push(MP(d[e.to], e.to));
            }
        }
    }
}

