const int N = 18;

ll G[N][N];
ll A[N];
ll dis[N];

ll gao(int s)
{
	memset(dis, -1, sizeof(dis));
	priority_queue< pair<ll, int>, vector< pair<ll, int> >, greater< pair<ll, int> > > Q;
	Q.push(mp(0ll, s));
	dis[s] = 0ll;

	while (!Q.empty()) {
		ll d = Q.top().fi;
		int u = Q.top().se;
		dis[u] = d;

		Q.pop();

		if (u == 1) return dis[u];

		for (int i = 0; i <= 9; ++i) {
			int v = i;
			ll _d = d + G[u][v];			
			if (dis[v] == -1 || _d < dis[v]) {
				dis[v] = _d;
				Q.push(mp(_d, v));
			}
		}
	}

	return 0ll;
}		

