void Build(int x, int y, LL z)
{
	pre[++all] = last[x];
	last[x] = all;
	other[all] = y;
	c[all] = z;
}

void Bfs(int s)
{
	int h = 1, t = 1, now, ed, dr;
	seq[t] = s;
	for(int i = 0; i <= 9; i++) {
		if(i == s) {
			dis[i] = 0;
		}
		else dis[i] = 1ll << 60;
	}
	In[s] = 1;
	while(h <= t)
	{
		now = seq[h];
		ed = last[now];
		while(ed != -1){
			dr = other[ed];
			if(dis[now] + c[ed] < dis[dr])
			{
				dis[dr] = dis[now] + c[ed];
				if(!In[dr])
				{
					In[dr] = 1;
					seq[++t] = dr;
				}
			}
			ed = pre[ed];
		}
		In[now] = 0;
		h++;
	}
}
