static int32_t memo[10][2000];

static int32_t dfs(int32_t index, int32_t used)
{
	if (memo[index][used] > -1)
		return memo[index][used];

	int32_t res = numeric_limits<int32_t>::max();
	for (int32_t i = 0; i < 10; i++) {
		if ((used & (1 << i)) == 0) {
			res = min(res, dfs(i, used | (1 << i)) + c[index][i]);
		}
	}

	memo[index][used] = res;
	return res;
}

