        v.assign(n, vector<int>(n,INF));
        for(int i=0;i<n;i++)v[i][i]=0;
    }

    // 入力の初期化
    void init(int n){
        for(int i=0;i<n;i++){
            int a,b,c;
            cin>>a>>b>>c;
            //a--; b--;
            v[a][b]=c;
            //v[b][a]=c; #無向グラフの時
        }
    }

    // 最小コストを求める
    void solve(){
        for(int i=0;i<v.size();i++){
            for(int j=0;j<v.size();j++){
                for(int k=0;k<v.size();k++){
                    v[j][k]=min(v[j][k], v[j][i]+v[i][k]);
                }
            }
        }
    }

    // 頂点aから頂点bへのコストを求める
    int get_cost(int a, int b){
        //a--;  b--;
        return v[a][b];
    }
};

