void BFS(vvll &g,vll &cnt,ll n,queue<ll> &q){
	ll d = cnt.at(n) ;
	for(int i=0;i<g.at(n).size();i++){
		if(cnt.at(i)>d+g.at(n).at(i)){
			cnt.at(i) = d+g.at(n).at(i) ;
			q.push(i) ;
		}
	}
	if(q.empty()) return ;
	ll next = q.front() ; q.pop() ;
	BFS(g,cnt,next,q) ;
}

