			}
		}
	}

	int ans = 0;

	rep(i, 10) {
		// iから1へ行く
		if (num[i] == 0) continue;
		ans += c[i][1] * num[i];
	}

	// 計算量はO(HW) or O(100log(HW)) := O(1000) でいいのかな

	cout << ans << endl;

	return 0;
}

