struct Node {
  // このノードから伸びるエッジの情報
  int number;
  std::vector<int> edges_to;    // 各エッジの接続先のノード番号
  std::vector<int> edges_cost;  // 各エッジのコスト

  // ダイクストラ法のためのデータ
  bool done;  // 確定ノードか否か
  int cost;   // このノードへの現時点で判明している最小コスト
  Node() {
    done = false;
    cost = INT_MAX;
  }
  bool operator> (const Node &node) const {
    return cost > node.cost;
  }
};

class MyGraph {
public:
  MyGraph(int numNodes) {
    this->numNodes = numNodes;
    nodes = std::vector<Node>(numNodes);
    doneCount = 0;
  }
  int numNodes;
  std::vector<Node> nodes;
  std::priority_queue<Node, std::vector<Node>, std::greater<Node> > queue;
  int doneCount;

  void addEdge(int edge_from, int edge_to, int edge_cost) {
    nodes[edge_from].number = edge_from;
    nodes[edge_from].edges_to.push_back(edge_to);
    nodes[edge_from].edges_cost.push_back(edge_cost);
  }
  void updateCost(int node_start) {
    nodes[node_start].cost = 0;
    queue.push(nodes[node_start]);
    while (!queue.empty()) {
      Node &node = nodes[queue.top().number];
      queue.pop();
      if (node.done) {
        continue;
      }
      //printf("%d\n", node.number);
      node.done = true;
      doneCount++;
      for (int i = 0; i < (int)node.edges_to.size(); ++i) {
        Node &nodeNext = nodes[node.edges_to[i]];
        if (!nodeNext.done && nodeNext.cost > node.cost + node.edges_cost[i]) {
          nodeNext.cost = node.cost + node.edges_cost[i];
          //printf("%d %d\n", nodeNext.number, node.cost + node.edges_cost[i]);
          queue.push(nodeNext);
        }
      }
    }
  }
  int getCost(int node_num) {
    return nodes[node_num].cost;
  }
};

int main(int argc, char const *argv[]) {
  int H, W;
  scanf("%d%d", &H, &W);
  int A[H][W];
  int c;
  MyGraph graph = MyGraph(10*10);
  for (int i = 0; i < 10; i++) {
    for (int j = 0; j < 10; j++) {
      scanf("%d", &c);
      if (i != j) {
        graph.addEdge(j, i, c);
      }
    }
  }
  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      scanf("%d", &A[i][j]);
    }
  }
  graph.updateCost(1);
  int cost = 0;
  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      if (A[i][j] != -1) {
        cost += graph.getCost(A[i][j]);
        // printf(" %d\n", graph.getCost(A[i][j]));
      }
    }
  }
  printf("%d\n", cost);
  return 0;
}

