int dykstra(int s) {
	if (s == 1) {
		return 0;
	}
	priority_queue<P, vector<P>, greater<P> > que;
	vector<int > d(10, inf);

	d[s] = 0;
	que.push(make_pair(0, s));

	while(! que.empty()) {
		P p = que.top();
		que.pop();
		int v = p.second;
		if (d[v] < p.first) {
			continue;
		}
		for(int i = 0; i < 10; i++) {
			if (i == v) continue;
			int cost = c[v][i];
			if (p.first + cost < d[i]) {
				d[i] = p.first + cost;
				que.push(make_pair(p.first + cost, i));
			}

		}
	}
	return d[1];
}


