void solve(int H, int W, vector<vector<int>> c, vector<vector<int>> A) {
  vector<int> num = {0, 2, 3, 4, 5, 6, 7, 8, 9};
  vector<int> cost(10, INF);
  cost[1] = 0;

  do {
    xrep(lim, 9) {
      int tmp = 0;
      rep(i, lim) {
        if (i < lim - 1)
          tmp += c[num[i]][num[i + 1]];
        else
          tmp += c[num[i]][1];
      }
      chmin(cost[num[0]], tmp);
    }
  } while (next_permutation(num.begin(), num.end()));

  watchVec(cost);
  long long ans = 0;
  rep(i, H) {
    rep(j, W) {
      if (A[i][j] != -1) ans += cost[A[i][j]];
    }
  }

  cout << ans << "\n";
}

