class Edge{
public:
    int from, to;
    long long cost;
    Edge(): from(0), to(0), cost(0){};
    Edge(int u, int v, long long w): from(u), to(v), cost(w){};
    ~Edge(){};
};

// Dijkstra's Algorithm
void Dijkstra(std::vector<Edge> &edge, int N, int start, std::vector<long long> &distance)
{
    typedef std::pair<long long, int> P;
    const long long infty = 1e+18;

    // initialize
    distance.clear();
    for(int i=0; i<N; i++) distance.push_back(infty);
    distance[start] = 0;
    std::priority_queue<P, std::vector<P>, std::greater<P> > q;
    q.push(P(0, start));

    std::vector<std::list<P> > edge_list(N);
    for(auto &&itr = edge.begin(); itr != edge.end(); itr++){
        edge_list[itr->from].push_back(P(itr->cost, itr->to));
    }

    // update
    while(!q.empty()){
        int d = q.top().first;
        int u = q.top().second;
        q.pop();
        if(distance[u] < d) continue; // not updated

        for(auto &&itr = edge_list[u].begin(); itr != edge_list[u].end(); itr++){
            int v = itr->second;
            long long w = itr->first;
            if(distance[u] + w < distance[v]){
                distance[v] = distance[u] + w;
                q.push(P(distance[v], v));
            }
        }
    }
}

int main()
{
    int H, W;
    std::cin >> H >> W;
    std::vector<std::vector<int> > c(10, std::vector<int>(10));
    std::vector<std::vector<int> > A(H, std::vector<int>(W));
    for(int i=0; i<10; i++){
        for(int j=0; j<10; j++) scanf(" %d", &c[i][j]);
    }
    for(int i=0; i<H; i++){
        for(int j=0; j<W; j++){
            scanf(" %d", &A[i][j]);
            if(A[i][j] == -1) A[i][j] = 1;
        }
    }

    std::vector<Edge> edge;
    for(int i=0; i<10; i++){
        for(int j=0; j<10; j++){
            if(i != j) edge.push_back(Edge(j, i, c[i][j]));
        }
    }
    std::vector<long long> distance;
    Dijkstra(edge, 10, 1, distance);

    long long ans = 0;
    for(int i=0; i<H; i++){
        for(int j=0; j<W; j++) ans += distance[A[i][j]];
    }
    std::cout << ans << std::endl;
}

