using namespace std;
const int INF = 10000000;

//min cost
int cache[10][10] = {0, };
int cost[10][10];

int n, m;

int make_one(int num, int vis, int z){
    if((vis & (1<<1)) == 2) return 0;
    int & ret = cache[z][num];
    if(ret != -1) return ret;

    int ans = INF;
    for(int i = 0; i < 10; i++){
        if(((1 << i) & vis) == 0){
            ans = min(ans, make_one(i, vis | (1<<i), z) + cost[num][i]);
        }
    }

    return ret = ans;
}

int main(){
    scanf("%d %d", &n, &m);
    memset(cache, -1, sizeof(cache));
    for(int i = 0; i < 10; i++){
        for(int j = 0; j < 10; j++){
            scanf("%d", &cost[i][j]);
        }
    }
    int ans = 0;
    for(int i = 0; i < 10; i++){
        make_one(i, 0, i);
    }

    for(int i = 0; i < n; i++){
        for(int j = 0; j < m; j++){
            int tmp;
            scanf("%d", &tmp);
            if(tmp != -1){
                int minn = INF;
                for(int i = 0; i < 10; i++){
                    if(cache[i][tmp] != -1) minn = min(minn, cache[i][tmp]);
                }
                ans += minn;
            }
        }
    }

    printf("%d\n", ans);
    return 0;
}

