int cost[10];
int dist[10][10];
int expanded[10];

void djkInit() {
  for (int i = 0; i < 10; i++) {
    cost[i] = 0xfffffff;
  }
  cost[1] = 0;
}

void djkExpand(int n) {
  for (int i = 0; i < 10; i++) {
    int tmp = cost[n] + dist[i][n];
    if (cost[i] > tmp) {
      cost[i] = tmp;
    }
  }
  expanded[n] = 1;
}

void djk() {
  djkExpand(1);
  for (;;) {
    int min = 0xfffffff, minIndex;
    for (int i = 0; i < 10; i++) {
      if (expanded[i]) continue;
      if (min > cost[i]) {
        min = cost[i];
        minIndex = i;
      }
    }
    if (min == 0xfffffff) {
      break;
    }
    djkExpand(minIndex);
  }
}

