		p_ii p = que.top(); que.pop();
		int v = p.second;
		if (cost[v] < p.first)continue;

		for (int i = 0; i < c[v].size(); i++) {
			if (i == v)continue;
			if (cost[i] > cost[v] + c[i][v]) {
				cost[i] = cost[v] + c[i][v];
				que.push(p_ii(cost[i], i));
			}
		}
	}

	for (int i = 0; i < h; i++)for (int j = 0; j < w; j++) {
		if (a[i][j] == -1)continue;
		ans += cost[a[i][j]];
	}

	cout << ans << endl;


	return 0;
}

