void dijkstra(ll start){
    priority_queue<P,vector<P>,greater<P>>que;
    dist[start][start]=0;
    que.push(P(start,dist[start][start]));
    while(!que.empty()){
        P p=que.top();
        que.pop();
        ll now=p.first;
        ll d=p.second;
        for(ll i=0;i<10;i++){
            if(now==i)continue;
            if(dist[start][i]>d+cost[now][i]){
                dist[start][i]=d+cost[now][i];
                que.push(P(i,dist[start][i]));
            }
        }
    }
}

