using namespace std;

#define INF_INT 2147483647

//現状保存用
class status{
public:
    int now, len;
    vector<bool> mem;
    status(){}
    status(int n, int l, vector<bool> m){
        now = n;
        len = l;
        mem = m;
    }
};

queue<status> q;
int G[10][10];
int lenList[10];

void bfs(){
    status st = q.front();
    q.pop();

    //行ったことあるフラグ更新
    st.mem[st.now] = false;
    //最短距離の更新
    if(st.len < lenList[st.now]) lenList[st.now] = st.len;
    //行ったことのない場所があればキューに追加
    for(int i = 0; i < 10; i++){
        if(st.mem[i]){
            status add(i, st.len+G[i][st.now], st.mem);
            q.push(add);
        }
    }
}

int main(){
    //入力
    int H,W;
    cin >> H >> W;
    for(int i = 0; i < 10; i++){
        for(int j = 0; j < 10; j++){
            cin >> G[i][j];
        }
    }

    //初期値を作成
    vector<bool> v;
    for(int i = 0; i < 10; i++) v.push_back(true);
    status st(1, 0, v);
    q.push(st);
    for(int i = 0; i < 10; i++) lenList[i] = INF_INT;

    //キューがなくなるまで計算
    while(!q.empty()){
        bfs();
    }

    //計算
    int sum = 0;
    for(int i = 0; i < H; i++){
        for(int j = 0; j < W; j++){
            int kabe;
            cin >> kabe;
            if(kabe != -1) sum += lenList[kabe];
        }
    }
    cout << sum << endl;
    return 0;
}

