    to[i] = C[i][1];
    queue<P> q;
    rep(j, 10) {
      if (i == j) continue;
      if (C[i][j] > to[i]) continue;
      q.push({j, C[i][j]});
    }

    while (!q.empty()) {
      P p = q.front();
      q.pop();

      if (p.first == 1) {
        to[i] = min(to[i], p.second);
