        q.push({j, p.second + C[p.first][j]});
      }
    }
  }

  ll ans = 0;
  rep(i, H) rep(i, W) {
    ll a;
    cin >> a;
    if (a == -1 || a == 1) continue;
    ans += to[a];
  }
