struct UnionFind{
  vi root;
  vi sizes;
  UnionFind(int n):root(n),sizes(n,1){
    REP(i,n)root[i]=i;
  }
  int find(int x){
    if(x==root[x])return x;
    return root[x]=find(root[x]);
  }
  void unite(int x,int y){
    x=find(x);y=find(y);
    if(x==y) return;
    if(sizes[x]<sizes[y])swap(x,y);
    root[y]=x;
    sizes[x]+=sizes[y];sizes[y]=0;
  }
  bool same(int x,int y){
    return find(x)==find(y);
  }
  int size(int x){
    return sizes[find(x)];
  }
};

