struct warshall_floyd {
  vvint d ;

  void make(int n){
    REP(i,n){
      d.PB(vint());
    }
    REP(i,n){
      REP(j,n){
        if(i==j){
          d[i].PB(0);
        }
        else{
          d[i].PB(INF) ;
        }
      }
    }
  }

  void inin(int a,int b,int c){
    d[a][b] = c ;
  }

  void work(){
    int n = SZ(d[0]) ;
    REP(k,n){
      REP(i,n){
        REP(j,n){
          d[i][j] = min(d[i][j],d[i][k]+d[k][j]) ;
        }
      }
    }
  }

  int dis(int i,int j){
    return d[i][j] ;
  }

  bool negative(){
    int n = SZ(d[0]) ;
    REP(i,n){
      REP(j,n){
        if(d[i][j]<0){
          return true ;
        }
      }
    }
    return false ;
  }


};


















