struct Tree{
    public:
    vector<vector<IVector2>> list;
    Tree(lint n){
        list.resize(n);
    }
    void unite(lint a,lint b,lint w){
        list[a].push_back(IVector2{b,w});
        list[b].push_back(IVector2{a,w});
    }
    void to(lint a,lint b,lint w){
        list[a].push_back(IVector2{b,w});
    }
    vec dij(lint x){
        vec _diff;
        priority_queue<IVector2,vector<IVector2>,greater<IVector2>>que;
        _diff.resize(list.size(),INF);
        _diff[x]=0;
        que.push(IVector2{0,x});
        while(!que.empty()){
            auto d = que.top();
            que.pop();
            if(_diff[d.y]<d.x)continue;
            rep(i,list[d.y].size()) {
                IVector2 e =list[d.y][i];
                if (_diff[e.x] > _diff[d.y] + e.y) {
                    _diff[e.x] = _diff[d.y] + e.y;
                    que.push(IVector2{_diff[e.x],e.x});
                }
            }
        }
        return _diff;
    }
};
