namespace path {
	vector<ll> dijkstra(int s, vector<vector<edge>>* G, ll INF = LLONG_MAX) {
		int V = (*G).size();
		vector<ll> d(V);
		fill(d.begin(), d.end(), INF);
		priority_queue<P, vector<P >, greater<P > > que;
		d[s] = 0;
		que.push(P(d[s], s));
		while (!que.empty()) {
			P p = que.top();
			que.pop();
			int v = p.second;
			if (d[v] < p.first)continue;
			for (edge e : (*G)[v]) {
				if (e.to < V && d[e.to] > d[v] + e.cost) {
					d[e.to] = d[v] + e.cost;
					que.push(P(d[e.to], e.to));
				}
			}
		}
		return d;
	}

	vector<vector<ll>> warshall_floyd(vector<vector<edge>>* G, ll INF = LLONG_MAX) {
		int V = (*G).size();
		vector<vector<ll>> d(V, vector<ll>(V, INF));
		for (int i = 0; i < V; i++) {
			d[i][i] = 0;
			for (edge e : (*G)[i]) {
				if (e.to < V) {
					d[i][e.to] = e.cost;
				}
			}
		}
		for (int k = 0; k < V; k++) {
			for (int i = 0; i < V; i++) {
				if (d[i][k] == INF)continue;
				for (int j = 0; j < V; j++) {
					if (d[k][j] == INF)continue;
					// 頂点iから頂点jへ行きたい。
					//   (頂点i, jの他には)頂点0～kのみを使える場合
					//     もしも頂点kを使わない場合は、頂点0～(k-1)のみを使える場合と同コスト
					//     頂点kを使う場合は、頂点iから頂点kまで頂点0～(k-1)以外を使わずに行くコストと、頂点kから頂点jまで頂点0～(k-1)以外を使わずに行くコストの和
					//   補足: 負の閉路がある <=> d[i][i]<0となるiが存在する
					//   　　: (負の閉路が存在しないならば)同じ頂点を２度通る必要はない
					d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
				}
			}
		}
		return d;
	}
}
