#include <bits/stdc++.h>
using namespace std;

#define LL long long
#define REP(i, n) for(int i = 0; i < (int)(n); i++)
#define FOR(i,a,b) for(int i=(a);i<(b);++i)
#define ALL(x) (x).begin(),(x).end()
const int IINF = 1e9;
const LL LINF = 1e18;
const LL mod = 1e9+7;

struct Node {
    vector<pair<int, LL>> edges;

    Node(){}
    Node(vector<pair<int, LL>> edges) {
        this->edges = edges;
    }
};

vector<LL> dijkstra(vector<Node> nodes, int start) {
    vector<LL> cost;
    vector<bool> visited;
    cost.resize(nodes.size());
    visited.resize(nodes.size());

    fill(ALL(cost), LINF);
    fill(ALL(visited), false);

    cost[start] = 0;
    visited[start] = true;

    for(auto edge : nodes[start].edges) {
        cost[edge.first] = edge.second;
    }

    REP(i, nodes.size() - 1) {
        LL min_cost = LINF;
        LL min_index;
        REP(j, nodes.size()) {
            if(!visited[j] && cost[j] < min_cost) {
                min_index = j;
                min_cost = cost[j];
            }
        }

        cost[min_index] = min_cost;
        visited[min_index] = true;
        for(auto edge : nodes[min_index].edges) {
            cost[edge.first] = min(cost[edge.first], cost[min_index] + edge.second);
        }
    }
    return cost;
}

int main() {
    int H, W;
    cin >> H >> W;

    vector<Node> nodes(10);
    REP(i, 10) {
        REP(j, 10) {
            LL c;
            cin >> c;
            nodes[i].edges.push_back(make_pair(j, c));
        }
    }

    vector<LL> cost(10);
    REP(i, 10) {
        cost[i] = dijkstra(nodes, i)[1];
    }

    LL res = 0;
    REP(h, H) {
        REP(w, W) {
            int a;
            cin >> a;
            if(a == -1)continue;
            res += cost[a];
        }
    }
    cout << res << endl;
    return 0;
}

