void findMin() {
	LL newC;
	bool changed = false;
	do {
		changed = false;
		REP(i, 10) {
			REP(j, 10) {
				if (i == j) continue;
				REP(k, 10) {
					if (k == i || k == j) continue;
					newC = c[i][k] + c[k][j];
					if (c[i][j] > newC) {
 						c[i][j] = newC;
						changed = true;
					}
				}
			}
		}
	} while (changed);

	return;
}

