// Time Complexity: O(V^3)
// init_d should be {INF(if i!=j), 0 (if i==j)}
template <typename T>
void WarshallFloyd(vector<vector<T>>& d, T INFD){
    int v = d.size();
    for(int k = 0; k < v; k++){
        for(int i = 0; i < v; i++){
            for(int j = 0; j < v; j++){
                if(d[i][k] == INFD || d[k][j] == INFD) continue;
                d[i][j] = min(d[i][j],d[i][k]+d[k][j]);
            }
        }
    }
}
