class Solver
{
  public:
	Solver() {}

	// [row][col]
	int dist[10][10];
	void Solve(istream &cin, ostream &cout)
	{
		int H, W;
		cin >> H >> W;

		REP(i, 10){
			REP(j, 10){
				cin >> dist[i][j];
			}
		}

		// 最短経路問題
		// ワーシャル・フロイドで求める
		REP(k, 10){
			REP(i, 10){
				REP(j, 10){
					dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
				}
			}
		}
		// REP(i, 10){
		// 	DumpArray(dist[i]);
		// }

		ll ans = 0;
		REP (i, H) {
			REP (j, W) {
				int n;
				cin >> n;

				if (n == -1 || n == 1) continue;

				ans += dist[n][1];
			}
		}

		cout << ans << endl;
	}
};
