vector<int> dp(10, -1);
int h, w, c[10][10];
int dfs(int i, vector<int> p = vector<int>())
{
    if (dp[i] >= 0)
    {
        return dp[i];
    }
    int closest = c[i][1];
    p.emplace_back(i);
    rep(k, 10)
    {
        if (k == i)
            continue;
        if (k < i)
            closest = min(closest, dp[k] + c[i][k]);
        else
            closest = min(closest, dfs(k, p) + c[i][k]);
    }
    if (p.size() == 1)
        dp[i] = closest;
    return closest;
}

