class UnionFind {
  vector<int> parent;
  vector<int> rank;

  public:

  UnionFind(int N);
  int root(int x);
  void unite(int x, int y);
  bool isUnited(int x, int y);
  int getRank(int x);
};

UnionFind::UnionFind(int N):parent(N),rank(N,1){
  for(int i=0; i<N; i++){parent[i]=i;}
}

int UnionFind::root(int x){
  if(parent[x] == x) return x;
  return root(parent[x]);
  /*parent[x] = parent[parent[x]];
  if(parent[x]!=parent[parent[x]]) rank[x]-=1;*/
}

void UnionFind::unite(int x, int y) { // xとyの木を併合
  int rx = root(x); //xの根をrx
  int ry = root(y); //yの根をry
  if (rx == ry) return; //xとyの根が同じ(=同じ木にある)時はそのまま

  if(rank[x] >= rank[y]){parent[ry] = rx; rank[y]+=1;}//大きい木に小さい木が併合される
  else{parent[rx] = ry; rank[x]+=1;}//根に直接辺を張る
}

bool UnionFind::isUnited(int x, int y) { // 2つのデータx, yが属する木が同じならtrueを返す
  int rx = root(x);
  int ry = root(y);
  parent[x]=rx; parent[y]=ry;rank[x]=2;rank[y]=2;
  return rx == ry;
}

int UnionFind::getRank(int x){
  return rank[x];
}

int main()
{
  //input
  cin.tie(0);
  ios::sync_with_stdio(false);

  ll H, W; cin >> H >> W;
  vector<vector<ll>> change(10,vector<ll>(10,0));
  FOR(i,10){ FOR(j,10){ cin >> change[i][j]; } }
  vector<vector<ll>> wall(H,vector<ll>(W,0));
  FOR(i,H){ FOR(j,W){ cin >> wall[i][j]; } }

  //main
  ll ans = 0;

  vector<vector<pair<ll,ll>>> graph(10);
  FOR(i,10){
    FOR(j,10){
      graph[i].pb(make_pair(j,change[i][j])); 
    }
  }

  vector<ll> cost(10,INF);

  FOR(s,10){//全頂点からダイクストラ
    vector<ll> dist(10,INF); dist[s] = 0;
    vector<bool> isSearched(10,false); 
    priority_queue< pair<ll,ll>,vector<pair<ll,ll>>,greater<pair<ll,ll>> > pq; pq.push(make_pair(0,s));

    while(!pq.empty()){
	  pair<ll,ll> p = pq.top(); pq.pop(); ll d = p.first, f = p.second;
      if(isSearched[f]) continue;

      for(auto edge : graph[f]){
        ll t = edge.first, c = edge.second;
        if(dist[t] > d+c){
          dist[t] = d+c;
          pq.push(make_pair(d+c,t));
        }
      }
    }

    cost[s] = dist[1];

  }

  // output
  FOR(h,H){
    FOR(w,W){
      if(wall[h][w] == -1) continue;
      ans += cost[wall[h][w]];
    }
  }
  cout << ans << endl;

  return 0;
}

