class Int2 {
public:
	int x, y;
	Int2() {}
	Int2(int x, int y) :x(x), y(y) {}
	Int2(const Int2& ano) :x(ano.x), y(ano.y) {}

	bool operator<(const Int2& ano) const {
		if (x != ano.x)
			return x < ano.x;
		return y < ano.y;
	}
	bool operator>(const Int2& ano) const {
		if (x != ano.x)
			return x > ano.x;
		return y > ano.y;
	}
};
int costs[10][10];
int min_cost(int x) {
	int dp[10];
	priority_queue<Int2, vector<Int2>, greater<Int2>> que;
	for (int i = 0; i < 10; i++) {
		dp[i] = costs[x][i];
		que.emplace(dp[i], i);
	}
	while (!que.empty()) {
		Int2 top = que.top();
		que.pop();

		for (int i = 0; i < 10; i++)
			if (dp[top.y] + costs[top.y][i] < dp[i]) {
				que.emplace(dp[top.y] + costs[top.y][i], i);
				dp[i] = dp[top.y] + costs[top.y][i];
			}
	}
	return dp[1];
}
int main() {
	int H, W, nums[10] = { 0 };
	scanf("%d %d", &H, &W);

	for (int i = 0; i < 10; i++)
		for (int j = 0; j < 10; j++)
			scanf("%d", &costs[i][j]);

	for (int i = 0; i < H; i++)
		for (int j = 0; j < W; j++) {
			int temp;
			scanf("%d", &temp);
			if (temp != -1)
				nums[temp]++;
		}

	int total = 0;
	for (int i = 0; i < 10; i++)
		total += min_cost(i) * nums[i];
	printf("%d\n", total);
}

