template<class V, class W, class F>
void dijkstra(F adj_v_w, V start, vector<W>& dest) {
    using P = pair<W, V>;
    fill(begin(dest), end(dest), numeric_limits<W>::max());
    priority_queue<P, vector<P>, greater<P>> pq;
    dest[start] = 0;
    pq.emplace(dest[start], start);
    while (!pq.empty()) {
        auto [wv, v] = pq.top(); pq.pop();
        TRACE(v, wv);
        if (dest[v] < wv) continue;
        for (auto [u, wu] : adj_v_w(v)) {
            if (dest[u] > dest[v] + wu) {
                dest[u] = dest[v] + wu;
                pq.emplace(dest[u], u);
            }
        }
    }
}

