#define MAX_V 10

struct edge {
	int to;
	int cost;
};

int d[MAX_V];
vector<edge> G[MAX_V]; // 隣接リスト表現

void dijkstra(int s) {
	fill(d, d + MAX_V, INF);
	d[s] = 0;  // 始点sへの最短距離は0

	priority_queue<P, vector<P>, greater<P>> que;  // 距離が小さい順に取り出せるようgreater<P>を指定
	que.push(P(0, s));
	while (!que.empty()) {
		P p = que.top();
		que.pop();
		int v = p.second;  // 更新した頂点の中で距離が最小の頂点v
		if (d[v] < p.first) {
			continue;
		}
		for (auto e : G[v]) {  // 頂点vから出る辺eを走査
			if (d[e.to] > d[v] + e.cost) {
				d[e.to] = d[v] + e.cost;
				que.push(P(d[e.to], e.to));
			}
		}
	}
}

