// O(v^3) 負閉路にも使える
// vector<vector<ll>> dp(v, vector<ll>(v, INF)) dp[i][j]はiからjへのコスト
// https://qiita.com/ageprocpp/items/cdf67e828e1b09316f6e#%E3%83%80%E3%82%A4%E3%82%AF%E3%82%B9%E3%83%88%E3%83%A9%E6%B3%95
bool warshall_floyd(vector<vector<ll>> &dp, vector<edge> &edges, ll v) {
  ll e = edges.size();
  REP(i, e) { dp[edges[i].from][edges[i].to] = edges[i].cost; }
  REP(i, v) { dp[i][i] = 0; }

  REP(k, v) {
    REP(i, v) {
      REP(j, v) {
        if (dp[i][k] == INF || dp[k][j] == INF) continue;
        dp[i][j] = min(dp[i][j], dp[i][k] + dp[k][j]);
      }
    }
  }

  REP(i, v) {
    //負閉路を持つ
    if (dp[i][i] < 0) return false;
  }
  return true;
}

int main() {
  // ios::sync_with_stdio(false);
  // cin.tie(nullptr);
  // v=頂点数,e=辺の数
  ll v, e, h, w;
  cin >> h >> w;
  v = 10, e = 100;
  vector<edge> edges(e);
  REP(i, 10) {
    REP(j, 10) {
      ll c;
      cin >> c;
      edges[i*10+j] = {i, j, c};
    }
  }
  vector<ll> cnt(10, 0);
  REP(i, h * w) {
    ll a;
    cin >> a;
    if (a != -1) cnt[a]++;
  }
  vector<vector<ll>> dist(v, vector<ll>(v, INF));
  warshall_floyd(dist, edges, v);
  ll ans = 0;
  REP(i, 10) {
    ans += cnt[i] * dist[i][1];
  }
  cout << ans << endl;
  return 0;
}

