void solve() {
    ll H,W;
    cin >> H >> W;
    int Cost[10][10];
    rep(i,10){
        rep(j,10){
            int c; cin >> c;
            Cost[i][j] = c;
        }
    }

    map<int,int> min_cost;
    for(int i=-1;i<10;++i){
        if(i==-1 || i==1) min_cost[i] = 0;
        else min_cost[i] = Cost[i][1];
    }

    rep(i,10){
        rep(j,i){
            min_cost[j] = min(min_cost[j],Cost[j][i] + Cost[i][1]);
        }

        rep(j,i){
            min_cost[i] = min(min_cost[i], Cost[i][j] + min_cost[j]);
        }
    }

    while(true){
        bool flag = true;
        rep(i,10){
            rep(j,10){
                if(chmin(min_cost[i], Cost[i][j] + min_cost[j])) flag = false;
            }
        }

        if(flag) break;
    }

    // for(auto c: min_cost){
