    int c;
};

ll V,E;
const ll MAX_V = 10000;
const ll MAX_E = 10000;
void warshall(vector<vector<ll>> &dp){

    // dpは初期化する．
    // dp[i][i]=0, dp[i][j]=(経路があればその値), (なければINF)

    for(ll k = 0; k < V; k++){
        for(ll i = 0; i < V; i++){
            for(ll j = 0; j < V; j++){
                dp[i][j] = min(dp[i][j], dp[i][k]+dp[k][j]);
            }
        }
    }
}

int main(){
    V = 10;
    E = 10;
    ll H,W;
    cin >> H >> W;

    vector<vector<ll>> dp(MAX_V, vector<ll>(MAX_E,INF));
    rep(i,V){
        dp[i][i] = 0;
    }
    rep(i,V)rep(j,E){
        cin >> dp[i][j];
    }

    warshall(dp);

    ll ans = 0;
    rep(i,H)rep(j,W){
        ll tmp; cin >> tmp;
        if(tmp==-1)continue;
        ans += dp[tmp][1];
    }

    cout << ans << endl;

    return 0;
}

