const int INF = numeric_limits<int>::max();

int edge[10][10];
int dijkstra(int start, int end, int N) {
  ll cost[N];
  priority_queue<pii, vector<pii>, greater<pii> > q;
  fill(cost, cost + N, INF); cost[start] = 0;
  q.push(pii(0, start));

  while (!q.empty()) {
    pii p = q.top(); q.pop();
    int u = p.second;
    ll cur_cost = p.first;

    if (cost[u] < cur_cost)
      continue;
    rep(v, N) {
      if (edge[u][v] == INF)
        continue;
      if (cost[v] > cost[u] + edge[u][v]) {
        cost[v] = cost[u] + edge[u][v];
        q.push(pii(cost[v], v));
      }
    }
  }
  return cost[end];
}

int main() {
  cin.tie(0); ios::sync_with_stdio(false);
  int H, W;
