  int cost[10];
  rep(i, 10) rep(j, 10) cin >> edge[i][j];
  rep(i, 10) cost[i] = dijkstra(i, 1, 10);

  int ans = 0;
  rep(i, H) rep(j, W) {
    int a; cin >> a;
    if (a != -1)
      ans += cost[a];
  }
  out(ans);

  return 0;
}

