    for(ll i = 0; i <= 9; i++){
        for(ll j = 0; j <= 9; j++){
            if(i == j){
                //自分から自分へ
                G[i].push_back(0);
            }else{
                G[i].push_back(INF);
            }
            path[i].push_back(j);
        }       
    }

    //辺入力
    for(ll i = 0; i <= 9; i++){
        for(ll j = 0; j <= 9; j++){
            ll w; cin >> w;
            //有向か無向かでコメントアウト　多重辺も防止
            G[i][j] = min(G[i][j], w);
