#include <bits/stdc++.h>
using namespace std;

typedef vector<vector<int> > Matrix;

const int INF = 100000000;
Matrix d; // グラフの距離を格納した2次元配列（隣接行列）
          // d[u][v]は辺e=(u,v)のコスト（辺が存在しない場合はINF、ただしd[i][i]=0）

void warshall_floyd(int n) { // nは頂点数
  for (int i = 0; i < n; i++)      // 経由する頂点
    for (int j = 0; j < n; j++)    // 開始頂点
      for (int k = 0; k < n; k++)  // 終端
        d[j][k] = min(d[j][k], d[j][i] + d[i][k]);
}

int main() {
  int h,w;
  std::cin >> h>>w;
  d = Matrix(10, vector<int>(10, INF));
  for (int i = 0; i < 10; i++) {
    /* code */
    for (int j = 0; j < 10; j++) {
      /* code */
      std::cin >> d[i][j];
    }
  }
  warshall_floyd(10);
  int ans=0;

  for (int i = 0; i < h*w; i++) {
    /* code */
    int a;
    std::cin >> a;
    if(a!=-1){
      ans+=d[a][1];

    }
  }
  std::cout << ans << std::endl;

}

#include <bits/stdc++.h>
#define INF 1000000007
using namespace std;

int c[10][10];
int sp[10];

void dijkstra() {
    bool used[10];
    fill(used, used + 10, false);
    fill(sp, sp + 10, INF);
    sp[1] = 0;
    while (true) {
        int v = -1, min_p = INF;
        for (int i = 0; i < 10; i++) {
            if (used[i] == false && sp[i] < min_p) {
                v = i;
                min_p = sp[i];
            }
        }
        if (v == -1)
            return;

        for (int i = 0; i < 10; i++) {
            if (used[i] == false) {
                sp[i] = min(sp[i], c[i][v] + sp[v]);
            }
        }
        used[v] = true;
    }
}

int main() {
    int h, w;
    cin >> h >> w;
    for (int i = 0; i < 10; i++) {
        for (int j = 0; j < 10; j++) {
            cin >> c[i][j];
        }
    }

    dijkstra();
    int ans = 0;
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            int a;
            cin >> a;
            if (a == -1)
                continue;
            ans += sp[a];
        }
    }
    cout << ans << endl;
    return 0;
}

