int masu[10][10] = {0};

int dp[10] = {0};

void dykstra(int i){

    priority_queue<int, vector<int>> pq;
    rep(i, 10) dp[i] = MOD; // enough large
    dp[1] = 0;

    pq.push(i);
    while(!pq.empty()){
        int p = pq.top(); pq.pop();
        rep(i, 10){
            if (p == i) continue;
            if (dp[i] > dp[p] + masu[i][p]){
                pq.push(i);
                dp[i] = dp[p] + masu[i][p];
            }
        }
    }    
}


