using Graph = vector<vector<int>>;

void RoyFloyd(Graph &g)
{
    int n = g.size();
    for (int k = 0; k < n; k += 1) {
        for (int i = 0; i < n; i += 1) {
            for (int j = 0; j < n; j += 1) {
                if (i == j || i == k || j == k) {
                    continue;
                }
                g[i][j] = min(g[i][j], g[i][k] + g[k][j]);
            }
        }
    }
}

int main()
{
    int rows, cols;
    cin >> rows >> cols;

    Graph graph(10, vector<int>(10));
    for (auto &row : graph) {
        for (auto &num : row) {
            cin >> num;
        }
    }
    RoyFloyd(graph);

    int sum = 0;
    for (int i = 0; i < rows; i += 1) {
        for (int j = 0; j < cols; j += 1) {
            int num;
            cin >> num;
            sum += (num == -1 ? 0 : graph[num][1]);
        }
    }

    cout << sum << "\n";
    return 0;
}

