ll solve_a() {

#ifdef debug
    line2;
    dout << "solve_a()\n";
#endif

    init();

    //calc. d[] by dijkstra algorithm
    d[1] = 0;
    v[1] = true;

    int s = 1;
    while(1) {

#ifdef debug
        line;
        disp(s);
#endif

        v[s] = true;

        int next_s = NONE;
        int d_of_next_s = INF;

        rep(i,0,N) {
            d[i] = min( d[i], d[s] + c[i][s] );

            if( v[i]==false and d[i]<d_of_next_s ) {
                next_s = i;
                d_of_next_s = d[i];
            }
        }

        display();

        if(next_s==NONE) break;

        s = next_s;


    } //end of while(1)-loop




    //calc. ans
    ll ans = 0;
    rep(i,0,H) {
        rep(j,0,W) {
            if(a[i][j]!=NONE)
                ans += d[a[i][j]];
#ifdef debug
            line;
            disp(a[i][j]);
            disp(ans);
#endif
        }
    }




    return ans;

}









ll solve_q() {

#ifdef debug
    line2;
    dout << "solve_q()\n";
#endif

    init();

    //calc. d[] by dijkstra algorithm
    d[1] = 0;
    Q.push(make_pair(-d[1], 1));

    int s;
    while(not Q.empty()) {

        ii x = Q.top(); Q.pop();
        s = x.second;

        if(v[s]==true) continue;

        v[s] = true;

#ifdef debug
        line;
        disp(s);
#endif

        rep(i,0,N) {
            d[i] = min( d[i], d[s] + c[i][s] );

            if( v[i]==false ) Q.push(make_pair(-d[i], i));
        }

        display();

    } //end of while(1)-loop




    //calc. ans
    ll ans = 0;
    rep(i,0,H) {
        rep(j,0,W) {
            if(a[i][j]!=NONE and a[i][j]!=1) {
                ans += d[a[i][j]];

#ifdef debug
                line;
                disp(a[i][j]);
                disp(ans);
#endif

            }
        }
    }



    return ans;
}











