using namespace std;

constexpr long long mod = static_cast<long long>(1e9 + 7);

int main() {
    int H, W;
    cin >> H >> W;

    int path[10][10];

    for(int i = 0; i < 10; ++i){
        for(int j = 0; j < 10; ++j){
            cin >> path[i][j];
        }
    }

    vector<vector<int>> wall(H, vector<int>(W, 0));

    for(auto& vec: wall) {
        for(auto& val: vec){
            cin >> val;
        }
    }

    int answers[10] = {};

    for(int i = 0; i < 10; ++i) {
        auto comp = [](auto x, auto y){return std::get<0>(x) > std::get<0>(y);};
        int costs[10];
        fill(costs, costs + 10, -1);
        priority_queue<tuple<int, int>, vector<tuple<int, int>>, decltype(comp)> pque(comp);
        pque.push(make_tuple(0, i));

        while(!pque.empty()) {
            auto state = pque.top();
            pque.pop();
            int cost = std::get<0>(state);
            int pos = std::get<1>(state);

            costs[pos] = cost;
            if(pos == 1) break;
            for(int j = 0; j < 10; ++j) {
                if(costs[j] < 0 || cost + path[pos][j] < costs[j]) {
                    pque.push(make_tuple(cost + path[pos][j], j));
                }
            }
        }
        answers[i] = costs[1];
    }

    int ans = 0;
    for(auto& vec: wall){
        for(auto val: vec) {
            if(val > 0) ans += answers[val];
        }
    }

    cout << ans << endl;

    return 0;
}

