int dis[15];
vector<int>g[15],cost[15];

void dijstkra(int n,int source) {

    for(int i=0; i<=n; i++) {
        dis[i] = INF;
    }

    priority_queue<node>q;
    q.push(node(source,0));
    dis[source] = 0;

    while(!q.empty()) {
        node top = q.top();
        q.pop();
        int u=top.u;

        for(int i=0; i<(int)g[u].size(); i++) {
            int v=g[u][i];

            //Relaxation
            if(dis[u] + cost[u][i] < dis[v]) {
                dis[v] = dis[u] + cost[u][i];
                q.push(node(v, dis[v]));
            }
        }
    }
}

