class Graph {
    Graph(){}
public:
    ll N;
    vector<vector<ll> > mat;
    Graph(ll sz) {
        N = sz;
        mat.assign(sz, vector<ll>(sz));
        REP(i, N) {REP(j, N) {mat[i][j] = INF;} mat[i][i] = 0;}
    }
    void warshall_floyd() {
        REP(i,N)REP(j,N)REP(k,N)
            mat[j][k] = min(mat[j][k], mat[j][i]+mat[i][k]);
    }
};

