int dist[14];
#define inf 1000000000
int s_p(int st,int ed)
{
    for(int i=0;i<14;i++)dist[i]=inf;
    priority_queue<pi,vector<pi>,greater<pi> >q;
    q.push({0,st});
    dist[st]=0;
    while(!q.empty())
    {

        int top=q.top().second;
        int cost=q.top().first;
        q.pop();
        if(top==ed)break;
        for(int i=0;i<adj[top].size();i++)
        {
            int chi=adj[top][i].second;
            int ct=adj[top][i].first;
            if(ct+cost<dist[chi])
            {
                dist[chi]=ct+cost;
                q.push({dist[chi],chi});
            }
        }
    }
    return dist[ed];
}

