			int a;
			cin >> a;
			edgeList.emplace_back(Edge(i, j, a));
		}
	}

	VVLL wallVal(H, VLL(W));
	REP(i, H) {
		REP(j, W) {
			cin >> wallVal[i][j];
		}
	}

	// ワーシャルフロイド
	WarshallFloyd<int> res(10, edgeList);

	ll ans = 0;
	REP(i, H) {
		REP(j, W) {
			int val = wallVal[i][j];
			if (val != -1 && val != 1) {
				ans += res.distList[val][1];
			}
		}
	}
	cout << ans << endl;
	return 0;
}

