template<typename T>
void warshall_floyd(std::vector<std::vector<T>> &distance, const T INF) {
  for(int k = 0; k < distance.size(); ++k) {
    for(int i = 0; i < distance.size(); ++i) {
      for(int j = 0; j < distance.size(); ++j) {
        if(distance[i][k] == INF || distance[k][j] == INF) continue;
        else distance[i][j] = std::min(distance[i][j], distance[i][k] + distance[k][j]);
      }
    }
  }
}

