            cin>>A[i][j];
        }
    }

    for(i=0;i<=9;i++){//i->1への最小消費魔力を計算
        vector<bool> visit(10,false);
        ans=INF;
        visit[i]=true;
        change_to_one[i]=dfs(i,visit,0);//i->1のMIN
    }

    int answer=0;
    for(i=0;i<h;i++){
        for(j=0;j<w;j++){
            if(A[i][j]!=-1){
                answer+=change_to_one[A[i][j]];
