int wall[201][201] = {};
int c[11][11] = {};
int h,w;
int ans = 0;
int cost[10];
int a;

int f(int i, int a) {
	if (cost[i] != -1) return cost[i];
	int re = c[i][1];
	for (int j = 0; j < 10; j++) {
		if (j != i && c[i][1] > c[i][j] && ((a & (2^j)) == 0)) {
			re = min(re, f(j, a + 2^i) + c[i][j]);
		}
	}
	return cost[i] = re;
}

