void execute()
{
	int H, W;
	int current_distance;
	int current_point;
	int ans = 0;
	cin >> H >> W;

	vector<vector<int>> a(10, vector<int>(10, 0));
	vector<int> distance(10, INF32);
	priority_queue<pair<int, int>> next;
	for (int i = 0; i < 10; i++)
	{
		for (int j = 0; j < 10; j++)
		{
			cin >> a[i][j];
		}
