	next.push(P(0, 1));

	for (; !next.empty();)
	{
		current_distance = next.top().first;
		current_point = next.top().second;
		next.pop();

		for (int i = 0; i < 10; i++)
		{
			if (i == current_point)
				continue;
			if (distance[i] <= current_distance + a[i][current_point])
				continue;

			next.push(P(current_distance + a[i][current_point], i));
			distance[i] = current_distance + a[i][current_point];
