	for (int i = 0; i < H; i++)
	{
		for (int j = 0; j < W; j++)
		{
			cin >> tmp;
			if (tmp == -1)
				continue;
			ans += distance[tmp];
		}
	}

	cout << ans << endl;
	return;
}

