struct EdgeA
{
	int to;
	ll cost;
};

void calcAllShortest(vector<vector<EdgeA>>& G, vector<vector<ll>>& d)
{
	auto numV = (int)G.size();
	for (auto i = 0; i < numV; ++i)
	{
		d.push_back(vector<ll>(numV, LLONG_MAX));

		for (auto v : G[i])
		{
			d[i][v.to] = v.cost;
		}
		d[i][i] = 0;
	}

	for (auto k = 0; k < numV; ++k)
	{
		for (auto i = 0; i < numV; ++i)
		{
			for (auto j = 0; j < numV; ++j)
			{
				if (d[i][k] >= LLONG_MAX || d[k][j] >= LLONG_MAX)
				{
					continue;
				}
				auto kd = d[i][k] + d[k][j];
				if (d[i][j] > kd)
				{
					d[i][j] = kd;
				}
			}
		}
	}
}


int main()
{
	int H, W;
	cin >> H >> W;
	int V = 10;
	vector<vector<EdgeA>> G(V);
	for (auto i = 0; i < V; ++i)
	{
		for (auto j = 0; j < V; ++j)
		{
			ll c;
			cin >> c;
			G[i].push_back({ j, c });
		}
	}

	vector<vector<ll>> d;
	calcAllShortest(G, d);

	auto ans = 0ll;
	for (auto i = 0; i < H; ++i)
	{
		for (auto j = 0; j < W; ++j)
		{
			int A;
			cin >> A;
			if (A < 0)
			{
				continue;
			}

			ans += d[A][1];
		}
	}

	cout << ans << endl;

	return 0;
}

