long long gcd(long long a, long long b){
    if(b == 0){
        return a;
    }
    return gcd(b, a % b);
}

long long lcm(long long a, long long b){
    return (a / gcd(a, b)) * b;
}

struct Node {
    ll cost;
    int pos;

    Node(ll _totalCost, int _currentPos) {
        cost = _totalCost;
        pos = _currentPos;
    }
};

int findMinimumCost(const vvi& cost, vi& visited, int from, int to) {
    vector<Node> queue;
    queue.push_back(Node(0, from));
    while (queue.size() != 0) {
        vector<Node>::iterator candidate = queue.begin();
        vector<Node>::iterator itr = queue.begin();
        for (; itr != queue.end(); itr++) {
            if (candidate->cost > itr->cost) {
                candidate = itr;
            }
        }
        Node current = *candidate;
        queue.erase(candidate);
        if (visited[current.pos] != -1 && visited[current.pos] < current.cost) {
            continue;
        }
        visited[current.pos] = current.cost;
//        cout << "current pos: " << current.pos << " cost: " << current.cost << endl;
        if (current.pos == to) {
            return current.cost;
        }
        for (int i = 0; i < 10; ++i) {
            if (i == current.pos) {
                continue;
            }
            queue.push_back(Node(current.cost + cost[current.pos][i], i));
        }
    }
}

