    repeat (i, H) {
        repeat (j, W) {
            cin >> number;
            vi visited(11, -1);
            if (number == -1) {
                continue;
            }
            totalCost += findMinimumCost(cost, visited, number, 1);
        }
    }
    cout << totalCost << endl;
    return 0;
}

