		queue<pr>q; pr pus,rec;
		int64_t least=mn.at(y);
		for(int x=0;x<10;++x){
			if(y!=x&&c.at(y).at(x)<least){
				pus.to=x,pus.cost=c.at(y).at(x);
				q.push(pus);
			}
		}
		while(q.size()){
			rec=q.front(); q.pop();
			if(rec.to==1)least=mn.at(y)=min(mn.at(y),rec.cost);
			else for(int x=0;x<10;++x){
				int64_t yy=rec.to,spend=rec.cost;
				if(x==yy)continue;
				int64_t tcost=spend+c.at(yy).at(x);
				if(tcost<least){
					pus.to=x,pus.cost=tcost;
					q.push(pus);
				}
			}
