template<class T> struct Grid {
    vector<T> data;
    const size_t h, w;
    Grid(size_t h, size_t w, T v = T()) : data(h * w, v), h(h), w(w) {}
    T& operator()(size_t i, size_t j) { return data[i * w + j]; }
    friend istream& operator>>(istream& in, Grid& g) {
        for (auto& v : g.data) in >> v;
        return in;
    }
    friend ostream& operator<<(ostream& out, const Grid& g) {
        for (size_t i = 0; i < g.h; ++i) {
            cout << g.data[i * g.w];
            for (size_t j = 1; j < g.w; ++j) {
                out << " " << g.data[i * g.w + j];
            }
            out << "\n";
        }
        return out;
    }
};

template<class V, class W, class F>
void dijkstra(F adj_v_w, V start, vector<W>& dest) {
    using P = pair<W, V>;
    fill(begin(dest), end(dest), numeric_limits<W>::max());
    priority_queue<P, vector<P>, greater<P>> pq;
    dest[start] = 0;
    pq.emplace(dest[start], start);
    while (!pq.empty()) {
        auto p = pq.top(); pq.pop();
        auto wv = p.first; auto v = p.second;
        TRACE(v, wv);
        if (dest[v] < wv) continue;
        for (auto q : adj_v_w(v)) {
            auto u = q.first;
            auto wu = q.second;
            if (dest[u] > dest[v] + wu) {
                dest[u] = dest[v] + wu;
                pq.emplace(dest[u], u);
            }
        }
    }
}

