void floyd(vector<vector<s64>>& d, vector<vector<s64>>& inter)
{
    s64 n = SIZE(d);
    inter.assign(n, vector<s64>(n, INF));

    REP(k, n) {
        REP(i, n) {
            if(d[i][k] == INF) continue;
            REP(j, n) {
                if(d[k][j] == INF) continue;
                if(chmin(d[i][j], d[i][k] + d[k][j])) {
                    inter[i][j] = k;
                }
            }
        }
    }
}

