typedef long long ll;
const ll INF=1e16;
const ll MAX=11;
ll dist[MAX][MAX];

void init(int n){
    for(int i=0;i<n;i++){
        for(int j=0;j<n;j++){
            dist[i][j]=INF;
            dist[i][i]=0;
        }
    }
}

void warshall_floyd(int n){
    for(int i=0;i<n;i++){
        for(int j=0;j<n;j++){
            for(int k=0;k<n;k++){
                dist[j][k]=min(dist[j][k],dist[j][i]+dist[i][k]);
            }
        }
    }
}

int main(){
    int H,W;
    cin >> H >> W;
    init(10);
    for(int i=0;i<10;i++){
        for(int j=0;j<10;j++){
            int c; cin >> c;
            dist[i][j]=c;
        }
    }
    warshall_floyd(10);
    ll res;
    for(int i=0;i<H;i++){
        for(int j=0;j<W;j++){
            int a;
            cin >> a;
            if(a!=1&&a!=-1){
                res+=dist[a][1];
            }
        }
    }
    cout << res << endl;
}

