int kousin(int num, int cost[10], int c[10][10]){
    int pre_cost = cost[num];
    int now = 0;
    for (int i = 0; i < 10; i++){
        //printf("cost_vec[%d] : %d\n",i,cost[i]);
    }
    //printf("*********************\n");

    for(int i = 0; i < 10; i++){
        now = pre_cost + c[i][num];
        if(now < cost[i]){
            cost[i] = now;
            kousin(i,cost,c);
        }
    }

    return cost[10];
}

