template<typename T>
void warshall_floyd(int n, vector<T> &g, vector<T> &dp) {
    for (int k = 0, kv = 0; k < n; ++k, kv += n) {
        for (int i = 0, iv = 0; i < n; ++i, iv += n) {
            for (int j = 0; j < n; ++j) {
                dp[iv + j] = min(dp[iv + j], dp[iv + k] + dp[kv + j]);
            }
        }
    }
}

