class Edge {
public:
	ll from,to,cost;
	Edge() {}
	Edge(ll from, ll to, ll cost) : from(from), to(to), cost(cost) {}
	bool operator < (const Edge &another) const {
		return cost != another.cost ? (cost > another.cost) : 
			(from != another.from ? from < another.from : to < another.to);
	}
};

/*
引数
 start:探索するスタートノード番号
 node_size:ノードの数、0〜(node_size-1)がノード番号として定義される
戻り値
　dist:スタートノードから各頂点までの距離
　prev:最短路木の親頂点
　return:負閉路が存在しない(グラフが正常)のとき true，負閉路が存在するとき false
*/
bool bellman_ford(const vector<vector<Edge>> &g, ll start, vector<ll> &dist, vector<ll> &prev) {
	ll gsize = g.size();
	dist.assign(gsize, INF+INF); dist[start] = 0;
	prev.assign(gsize, -1);

	bool negative_cycle = false;
	for(ll k=0;k<gsize;k++){
		for(ll i=0;i<gsize;i++){
			for(auto e=(g[i]).begin(); e!=(g[i]).end(); e++){
				if (dist[e->to] > dist[e->from] + e->cost) {
					dist[e->to] = dist[e->from] + e->cost;
					prev[e->to] = e->from;
					if (k == gsize-1) {
						dist[e->to] = -INF;
						negative_cycle = true;
					}
				}
			}
		}
	}
	return !negative_cycle;
}
//最短路木の親頂点を元にstart->goalの経路を作成
vector<ll> buildPath(const vector<ll> &prev, ll goal) {
	vector<ll> path;
	for (ll u = goal; u >= 0; u = prev[u])
		path.push_back(u);
	reverse(path.begin(), path.end());
	return path;
}


