#define INF 1000000009

vector<int> dijkstra(int start, int n, vector<vector<int>>& E){
    using P = pair<int, int>;

    vector<int> d(n, INF);
    vector<int> prev(n, -1);
    priority_queue<P, vector<P>, greater<P>> que;
    que.push(P (0, start));
    d[start] = 0;

    while(!que.empty()){
        P p = que.top();
        que.pop();
        int dp = p.first;
        int idx = p.second;

        for (int i = 0; i < n; i++){
            if (i == idx) continue;
            int di = dp + E[i][idx];
            if (d[i] > di){
                d[i] = di;
                que.push(P (di, i));
                prev[i] = idx;
            }
        }
    }
    return d;
}

int main(){
    int h, w;
    cin >> h >> w;
    vector<vector<int>> E(10, vector<int>(10));
