            cin >> E[i][j];
        }
    }
    vector<vector<int>> a(h, vector<int>(w));
    for (int i = 0; i < h; i++){
        for (int j = 0; j < w; j++){
            cin >> a[i][j];
        }
    }
    vector<int> d;
    d = dijkstra(1, 10, E);

    int ans = 0;
    for (int i = 0; i < h; i++){
        for (int j = 0; j < w; j++){
            int aij = a[i][j];
            if (aij < 0) continue;
            ans += d[aij];
        }
    }
    cout << ans << endl;
}

