      }
    }

    vector<vector<int>> wall(n);
    for (int i = 0; i < n; ++i) {
      for (int j = 0; j < m; ++j) {
        int x;
        cin >> x;
        wall[i].push_back(x);
      }
    }

    long long ans = 0;
    for (int i = 0; i < n; ++i) {
      for (int j = 0; j < m; ++j) {
        if (wall[i][j] == -1) continue;
        ans += solve(wall[i][j], wall, cost);
      }
    }

    cout << ans << endl;
  }

  return 0;
}

