ll sp(ll s) {
  ll d[10];
  for(int i=0; i<10; i++) d[i] = INF;
  d[s] = 0;
  while(true) {
    bool update = false;
    for(int i=0; i<10; i++) {
      for(int j=0; j<10; j++) {
	if(d[i] != INF and d[j] > d[i]+c[i][j]) {
	  d[j] = d[i] + c[i][j];
	  update = true;
	}
      }
    }
    if(!update) break;
  }
  return d[1];
}

void solve(long long H, long long W, std::vector<std::vector<long long>> A){
