  for(int i=0; i<H; i++) {
    for(int j=0; j<W; j++) {
      if(A[i][j] != -1 and A[i][j] != 1) {
	ans += d[A[i][j]];
      }
    }
  }
  std::cout << ans << std::endl;
}

