#define REP(i,n) for (int i = 0; i<n; i++)
#define ALL(a) begin(a), end(a)

struct Edge {
    int to,cost;
    Edge (int t,int c) {
        to = t; cost = c;
    }
    bool operator>(const Edge& e)const {
        return cost > e.cost;
    } 
    bool operator<(const Edge& e)const {
        return cost < e.cost;
    }
};

int main (void) {
    int H,W;
    cin>>H>>W;
    vector<vector<Edge>> G(10);
    REP(i,10) {
        REP(j,10) {
            int c;
            cin>>c;
            G[j].pb(Edge(i,c)); //辺を逆向きに追加
        }
    }

    //Dijkstraで1をnに変えるのに必要なコストを求める。
    //-> グラフの辺は逆向きなので、
    //   nから1に変えるのに必要なコストを求めることになる（はず）
    priority_queue<Edge,vector<Edge>,greater<Edge>> pq;
    vector<int> dist(10,inf);
    vector<bool> used(10,false);
    dist[1] = 0;
    pq.push(Edge(1,0));
    while(pq.size()) {
        int from = pq.top().to;
        pq.pop();
        if (used[from]) continue;
        used[from] = true;
        REP(i,10) {
            int c = G[from][i].cost;
            int t = G[from][i].to;
            if (dist[t] > c + dist[from]) {
                dist[t] = c + dist[from];
                pq.push(G[from][i]);
            }
        }
    }
    ll ans = 0;
    REP(i,H) {
        REP(j,W) {
            int n;
            cin>>n;
            if (abs(n) != 1) {
                ans += dist[n];
            }
        }
    }
    cout<<ans<<endl;
    return 0;
}

