using namespace std;

int H,W;
int C[10][10];
int A[210][210];
const int Inf = 10000*100000+100;

int main(){
	while(cin >> H >> W  && H > 0){
		for(int i=0;i<10;i++){
			for(int j=0;j<10;j++){
				cin >> C[i][j];
			}
		}
		for(int i=0;i<H;i++){
			for(int j=0;j<W;j++){
				cin >> A[i][j];
			}
		}
		int ct[10];
		for(int i=0;i<10;i++){
			ct[i] = Inf;
		}
		ct[1] = 0;
		for(int i=0;i<10;i++){
			int cost[10];
			for(int j=0;j<10;j++){
				cost[j] = Inf;
			}
			cost[i] = 0;
			priority_queue<pair <int,int> > P;
			P.push(make_pair(0,i));
			while(!P.empty()){
				pair<int,int> t = P.top();
				int s = t.second;//スタート
				P.pop();
				if(cost[s] < t.first) continue;
				for(int j=0;j<10;j++){
					pair<int,int> e = make_pair(C[s][j],j);
					if(cost[e.second] > cost[s] + e.first){
						cost[e.second] = cost[s] + e.first;
						P.push(make_pair(-cost[e.second],e.second));
					}
				}
			}
			ct[i] = cost[1];
		}
		int ans = 0;
		for(int i=0;i<H;i++){
			for(int j=0;j<W;j++){
				if(A[i][j]!=-1)
					ans += ct[A[i][j]];
			}
		}
		cout << ans << endl;
	}
}

