int mp[10];
int c[10][10];

void update(vector<int> num) {
	int ind = 0;
	for (int i = 0; i < 10; ++i) {
		if (num[i] == 1) {
			ind = i;
		}
	}

	int res = 0;
	for (int i = ind; i > 0; --i) {
		res += c[num[i-1]][num[i]];
		if (res > mp[num[i-1]]) {
			return;
		}
		mp[num[i-1]] = res;
	}
	return;
}

int main(void) {
