int visit[15];

void dfs(int num, int start, int now=0){
  if(num==1){
    cost[start]=min(cost[start],now);
    return;
  }
  for(int i = 0; i <= 9; i++){
    visit[num]=1;
    if(visit[i]) continue;
    now+=c[num][i];
    dfs(i,start,now);
    now-=c[num][i];
    visit[i]=0;
  }
}

