int read() {
    int tmp = 0;
    char c = getchar(), f = 1;
    while (c < '0' || '9' < c) {
        if (c == '-')
            f = -1;
        c = getchar();
    }
    while ('0' <= c && c <= '9') {
        tmp = tmp * 10 + c - '0';
        c = getchar();
    }
    return tmp * f;
}

const int SZ = 10;
int cost[SZ][SZ], mcost[SZ][SZ];
int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int h, w, t;
    h = read();
    w = read();
    REP(i, SZ) REP(j, SZ) cost[i][j] = read();
    vector<vector<int>> v(h);
    REP(i, h) REP(j, w) {
        t = read();
        v[i].push_back(t);
    }
    // undirectedS は無向グラフ、directedS は有向グラフ
    adjacency_list<listS, vecS, directedS, no_property,
                   property<edge_weight_t, int>>
        graph1(SZ);
    REP(i, SZ) REP(j, SZ) {
        if (i != j) {
            add_edge(i, j, cost[i][j], graph1);
        }
    }

    // k からの最短距離を求める
    vector<int> dist(SZ);
    vector<int> par(SZ);
    REP(i, SZ) {
        dijkstra_shortest_paths(
            graph1, i, distance_map(dist.data()).predecessor_map(par.data()));
        REP(j, SZ) {
            mcost[i][j] = dist[j];
            // cout << mcost[i][j] << " ";
        }
        // cout << endl;
    }
    ll sum = 0;
    REP(i, h) REP(j, w) {
        int a = v[i][j];
        if (a >= 2 || a == 0) {
            sum += mcost[a][1];
        }
    }
    cout << sum << endl;

    return 0;
}

