struct edge { int to, cost; };
typedef std::pair<int, int> PP;
// ↑costと頂点番号のペア
std::vector<edge> list[10];
int d[10];
void DIJX(int st) {
	for (int i = 0; i<V; i++)d[i] = INF; // std::fillでも書ける
	d[st] = 0; // 始点
	std::priority_queue<PP, std::vector<PP>, std::greater<PP>> pq;
	pq.push(std::make_pair(d[st], st)); // (cost,頂点番号)
	while (!pq.empty()) {
		PP p = pq.top();
		pq.pop();
		int i = p.second; // costがfirst、頂点番号がsecond
		if (d[i]<p.first)continue;
		for (int k = 0; k<list[i].size(); k++) {
			edge e = list[i][k];
			if (d[e.to] <= d[i] + e.cost)continue;
			d[e.to] = d[i] + e.cost;
			pq.push(std::make_pair(d[e.to], e.to));
		}
	}
}
