		queue<pair<int, int>> cand;
		REP(i, 10) {
			if (i != 1)
				cand.push(make_pair(i, cost[i * 10 + 1]));
		}
		while (not cand.empty()) {
			pair<int, int> c = cand.front(); cand.pop();
			REP(i, 10) {
				if (i == c.first) continue;
				int nextCost = c.second + cost[i * 10 + c.first];
				if (nextCost < cost[i * 10 + 1]) {
					cost[i * 10 + 1] = nextCost;
					cand.push(make_pair(i, nextCost));
				}
			}
		}
		int ans = 0;
		REP(i, H * W) {
			int a; cin >> a;
			if (a > -1) ans += cost[a * 10 + 1];
		}
