			c[j].emplace_back(i, tmp); // あえて逆に入れる（stまでの最小がほしいので）
		}
	}

	auto d = Dijkstra(c, 1);

	lint ans = 0;
	for (int i = 0; i < H*W; i++) {
		cin >> tmp;
		if(tmp != -1) ans += d[tmp];
	}

	cout << ans << "\n";

	return 0;
}

