template<class VECTOR_T>
void floyd_warshall(VECTOR_T& v, int origin = 0) {
    int stop = v.size();
    for (int k = origin; k < stop; k++)
        for (int i = origin; i < stop; i++)
            for (int j = origin; j < stop; j++)
                v[i][j] = min(v[i][j], v[i][k] + v[k][j]);
}

