//最短経路問題
int V;//頂点の数
int E;//辺の数
long long c[1000][1000];//二点間コスト、存在しなければINF
long long d[1000];//kを始点とする最短経路
edge es[1000];
bool roop=false;//負の閉路の存在の有無

bool used[1000];


//ベルマンフォード法
void shortest_path(int s){
    for(int i=0;i<V;i++){d[i]=INF;}
    d[s]=0;//sを始点とする
    int cnt=0;
    while(cnt<V){
        bool update=false;
        for(int i=0;i<E;i++){
            edge e=es[i];
            if(d[e.from]!=INF && d[e.to]>d[e.from]+e.cost){
                d[e.to]=d[e.from]+e.cost;
                update=true;
            }
        }
        if(!update){break;}
        cnt++;
    }
    if(cnt==V){roop=true;}
}

//ダイクストラ法
void dijkstra (int s){
    for(int i=0;i<V;i++){d[i]=INF;}
    for(int i=0;i<V;i++){used[i]=false;}
    d[s]=0;
    while(true){
        int v=-1;
        for(int u=0;u<V;u++){
            if(!used[u] && (v==-1 || d[u]<d[v]) ){v=u;}
        }
        if(v==-1){break;}
        used[v]=true;
        for(int u=0;u<V;u++){
            d[u]=min(d[u],d[v]+c[v][u]);
        }
    }
}

