        d[i] = 0;
        priority_queue<P, vector<P>, greater<P> > q;
        q.push(P(0, i));
        while (!q.empty()) {
            int dis,to;
            tie(dis, to) = q.top(); q.pop();
            if (used[to]) continue;
            used[to] = true; d[to] = dis;
            for (int j=0; j<10; j++) {
                if (d[j] <= dis + c[to][j]) continue;
                q.push(P(dis + c[to][j], j));
            }
        }
        min[i] = d[1];
    }

    int ans = 0;
    for (int i=0; i<H; i++) {
        for (int j=0; j<W; j++) {
            if (A[i][j] == -1) continue;
            ans += min[A[i][j]];
        }
    }

    cout << ans << endl;

