int dijkstra(int s) {
  vector<int> d(10, INF);
  vector<int> used(10, false);
  priority_queue<P, vector<P>, greater<P>> pq;
  d[s] = 0;
  pq.push(make_pair(0, s));
  while (pq.size() > 0) {
    int C = pq.top().first;
    int V = pq.top().second;
    pq.pop();
    if (used[V]) continue;
    rep(i, 10) {
      int alt = C + c[V][i];
      if (d[i] > alt) {
        d[i] = alt;
        pq.push(make_pair(alt, i));
      }
    }
    used[V] = true;
  }
  return d[1];
}

