void bk(int k, int cr, int sum)
{
    if(k == 1) return;
    if(sum >= q[k]) return;
    if(sum + a[cr][1] < q[k])
        q[k] = sum + a[cr][1];
    int i = 0;
    for(i = 0; i <= 9; i ++)
    {
        if(i == 1 || i == cr) continue;
        bk(k, i, sum + a[cr][i]);
    }
}

