void to_lower(string& x) {
  for (ll i = 0; i < x.length(); i++) if ('A' <= x[i] && x[i] <= 'Z') {
    x[i] -= 'A' - 'a';
  }
}

//小文字→大文字
void to_bigger(string& x) {
  for (ll i = 0; i < x.length(); i++) if ('a' <= x[i] && x[i] <= 'z') {
    x[i] += 'A' - 'a';
  }
} 

