class Dijkstra {

	const int INF;

	// d[i] : 始点 s から頂点 i への最短距離
	// d[i] = min(d[j] + (j から i への辺のコスト) | e = (j, i) in E)
	vector<int> d;
	vector<int> prev;

public:

	typedef pair<int, int> pii;

	// Dijkstra 法 O(|V|^2) (負の辺がない場合)
	// cost : 隣接行列, s : スタート地点
	// cost が存在しない場合は INF を入れておく
	Dijkstra(const vector<vector<int> >& cost, int s)
		: INF(1 << 29), d(cost.size(), INF), prev(cost.size(), -1)
	{
		int V = cost.size();
		vector<bool> used(V, false);

		d[s] = 0;
		while (true) {
			int v = -1;
			// まだ使われていない頂点のうち距離が最小のものを探す
			for (int u = 0; u < V; u++) {
				if (!used[u] && (v == -1 || d[u] < d[v])) v = u;
			}

			if (v == -1) break;

			used[v] = true;

			for (int u = 0; u < V; u++) {
				if (d[u] > d[v] + cost[v][u]) {
					d[u] = d[v] + cost[v][u];
					prev[u] = v;
				}
			}
		}
	}

	vector<int> shortest_path_cost() { return d; }
	int shortest_path_cost(int v) { return d[v]; }

	vector<int> get_path(int t) {
		vector<int> path;
		// t が s になるまで prev[t] を辿っていく
		for (; t != -1; t = prev[t]) path.push_back(t);
		reverse(all(path));
		return path;
	}

};

