using namespace std;
typedef long long signed int ll;

constexpr int inf = INT32_MAX / 2;

class djikstra {
private:
	ll* d = nullptr;
	map<int, map<int, ll>> p;
	int sz = 0;
public:
	void add_path(int from, int to, ll cost) {
		p[from][to] = cost;
	}
	void compute(int from,int nodes) {
		sz = nodes;
		if (d != nullptr) delete d;
		d = new ll[nodes];
		auto cmp = [this](int a, int b) {return d[a] > d[b]; };
		priority_queue <ll, vector<ll>, decltype(cmp)> q(cmp);
		for (int i = 0; i < nodes; i++) d[i] = INT64_MAX / 2;
		d[from] = 0;
		q.push(from);
		while (!q.empty()) {
			for (auto& e : p[q.top()]) {
				if (d[e.first] > d[q.top()] + e.second) {
					d[e.first] = d[q.top()] + e.second;
					q.push(e.first);
				}
			}
			q.pop();
		}
	}
	ll operator[](int node) {
		if (node >= sz) return INT64_MAX/2;
		return d[node];
	}
};

int main() {
	djikstra d;
	int h, w, n, r = 0;
	auto g = [&n]() {cin >> n; return n; };
	cin >> h >> w;
	for (int i = 0; i < 10; i++) for (int j = 0; j < 10; j++) d.add_path(j, i, g());
	d.compute(1, 10);
	for (int i = 0; i < h; i++)for (int j = 0; j < w; j++) if(g() != -1) r += d[n];
	cout << r << endl;
}

