struct Tmp
{
public:
  int H, W;
  int C[10][10] = {};
  vector<vector<int>> A;
  vector<int> count;

  Tmp(int H, int W)
  : H(H), W(W)
  , A(H, vector<int>(W))
  , count(10, 0)
  {}

  void operator()() {
    input();
    vector<vector<ll>> costTable(10, vector<ll>(10, INF));
    for (int i = 0; i < 10; ++i) {
      for (int j = 0; j < 10; ++j) {
        costTable[i][j] = C[i][j];
      }
    }

    for (int k = 0; k < 10; ++k) {
      for (int i = 0; i < 10; ++i) {
        for (int j = 0; j < 10; ++j) {
          chmin(costTable[i][j], costTable[i][k] + costTable[k][j]);
        }
      }
    }

    ll res{};
    for (int i = 0; i < 10; ++i) {
      res += count[i] * costTable[i][1];
    }
    cout << res << CRLF;

  }

  void input() {
    for (int i = 0; i < 10; ++i) {
      for (int j = 0; j < 10; ++j) {
        cin >> C[i][j];
      }
    }
    for (int i = 0; i < H; ++i) {
      for (int j = 0; j < W; ++j) {
        cin >> A[i][j];
        if (A[i][j] == -1) {
          A[i][j] = 1;
        } else {
          ++count[A[i][j]];
        }
      }
    }
  }
};

void solve(void)
{
  int H, W; cin >> H >> W;
  Tmp t(H, W);
  t();
  return;
}

int main(void)
{
  std::ios_base::sync_with_stdio(false);
  std::cin.tie(0);

  solve();

  return 0;
}

