void rec(const int table[10][10], const int &start, const int &u, const int &v, const int &end, const int &cost, map<int, map<int, int> > &lookUpTable) {
    int newCost = cost + table[u][v];

    if (v == end) {
        if (lookUpTable.find(start) == lookUpTable.end() || lookUpTable[start].find(end) == lookUpTable[start].end()) lookUpTable[start][end] = newCost;
        else if (newCost < lookUpTable[start][end]) lookUpTable[start][end] = newCost;

        return;
    }

    if (lookUpTable.find(start) == lookUpTable.end() || lookUpTable[start].find(v) == lookUpTable[start].end()) lookUpTable[start][v] = newCost;
    else if (lookUpTable[start][v] < newCost) return;

    int i;

    for (i = 0; i < 10; i++) {
        if (i != start && i != u && i != v) rec(table, start, v, i, end, newCost, lookUpTable);
    }
}

int getMinCost(const int table[10][10], const int &start, const int &end, map<int, map<int, int> > &lookUpTable) {
    int i;

    for (i = 0; i < 10; i++) if (start != i) rec(table, start, start, i, end, 0, lookUpTable);

    return lookUpTable[start][end];
}

