void bfs(int x) {
    if(x==1) return;

    rep(i,10) d[i]=INF;
    mem( visited, false);
    int u = x;
    d[x] = 0;

    while(true){

        int minv = INF;
        visited[u] = true;

        for(int i=0; i<10; i++){
            if( d[i]>d[u]+G[u][i] ){
                d[i] = d[u]+G[u][i];
            }
        }

        for(int i=0; i<10; i++){
            if( !visited[i] && d[i]<minv ) {
                u = i;
                minv = d[i];
            }
        }

        if(u==1) {
            cost[x] = d[u];
            return;
        }
    }

}

