int calc(int a, int arr)
{

    if (d[a][arr] == -1)
    {
        int b = c[a][arr];
        for (int i = 0; i < 10; i++)
        {
            if (a != i && c[a][arr] > c[a][i])
            {
                if (d[a][i] == -1)
                {
                    d[a][i] = calc(a, i);
                }
                if (d[i][arr] == -1)
                {
                    d[i][arr] = calc(i, arr);
                }
                b = min(d[a][i] + d[i][arr], b);
            }
        }
        d[a][arr] = b;
    }
    return d[a][arr];
}
