#include <bits/stdc++.h>
using namespace std;
using Graph= vector<vector<int>>;
const int Ndig= 10;

void solve(const Graph &weights, int g, vector<int> *dists){
  using path= pair<int, int>;

  priority_queue<path, vector<path>, greater<path>> search;
  search.push(make_pair(0, g));
  while( !search.empty() ){
    int d_tmp, to_tmp;
    tie(d_tmp, to_tmp)= search.top();
    search.pop();
    if(dists->at(to_tmp) <= d_tmp){ continue; }
    else{
      dists->at(to_tmp)= d_tmp;
      for(int from=0; from<Ndig; from++){
        search.push(make_pair(d_tmp+ weights.at(from).at(to_tmp), from));
      }
    }
  }
}

int main(){
  int H,W,buf;
  cin >> H >> W;

  Graph weights(Ndig, vector<int>(Ndig));
  vector<int> freq(Ndig);
  for(int i=0; i<Ndig; i++){
    for(int j=0; j<Ndig; j++){
      cin >> weights.at(i).at(j);
    }
  }
  for(int i=0; i<H; i++){
    for(int j=0; j<W; j++){
      cin >> buf;

      if(buf != -1){ freq.at(buf)++; }
    }
  }

  vector<int> dists(Ndig, INT_MAX);
  solve(weights, 1, &dists);

  int ans= 0;
  for(int i=0; i<Ndig; i++){
    ans+= freq.at(i)* dists.at(i);
  }

  cout << ans << endl;
}

