void warshall_floyd(vector<vll> &g, ll INF) {
  for (size_t k = 0; k < g.size(); k++) {
    for (size_t i = 0; i < g.size(); i++) {
      for (size_t j = 0; j < g.size(); j++) {
        if (g[i][k] == INF || g[k][j] == INF) continue;
        g[i][j] = min(g[i][j], g[i][k] + g[k][j]);
      }
    }
  }
}

int main() {
  ll H, W;
  cin >> H >> W;

  vector<vll> g(10, vll(10));

  for (int i = 0; i <= 9 ; i++) {
    for (int j = 0; j <= 9; j++) {
      cin >> g[i][j];
    }
  }

  warshall_floyd(g, -1);

  ll ans = 0;
  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      ll tmp;
      cin >> tmp;
      if (tmp == -1) continue;
      ans += g[tmp][1];
    }
  }

  cout << ans << endl;

  return 0;
}

