            cin >> adj[i][j];
            best[i][j] = -1;
        }
    }

    for(int dig = 0; dig < 10; ++dig){
        priority_queue<pair<int, int>> q;
        q.push(make_pair(0, dig));
        while(!q.empty()){
            pair<int, int> state = q.top();
            q.pop();
            if(best[dig][state.second] != -1)
                continue;
            best[dig][state.second] = -state.first;
            for(int nx = 0; nx < 10; ++nx){
                q.push(make_pair(state.first - adj[state.second][nx], nx));
