typedef pair<int, int> P; // first:最短距離，second:頂点番号

typedef pair<ll, ll> P_dij;

ll dijkstra(int s, int g, Graph_e G)
{
    ll d[110];
    fill(d, d + 110, INF_64);
    d[s] = 0;

    priority_queue<P, vector<P>, greater<P>> que;
    que.push(P(0, s));

    while (!que.empty()) {
        P p = que.top();
        que.pop();
        ll v = p.second;
        if (d[v] < p.first)
            continue;
        for (auto e : G.at(v)) {
            if (d[e.to] > d[v] + e.cost) {
                d[e.to] = d[v] + e.cost;
                que.push(P(d[e.to], e.to));
            }
        }
    }

    if (d[g] != INF_64) {
        return d[g];
    } else {
        return -1;
    }
}

