void BFS(vvll &num,vll &cnt,int n,queue<int> &q){
	int d = cnt.at(n) ;
	for(int i=0;i<10;i++){
		if(cnt.at(i)>d+num.at(n).at(i)){
			cnt.at(i) = d+num.at(n).at(i) ;
			q.push(i) ;
		}
	}
	if(q.empty()) return ;
	n = q.front() ;
	q.pop() ;
	BFS(num,cnt,n,q) ;
}

