void solve(void)
{ 
  int H,W;
  cin>>H>>W;
  int N = 10;
  vector<vector<int> > GRAPH(N,vector<int>(N));
  for (int i = 0; i < N; i++)
  {
    for (int j = 0; j < N; j++)
    {
      cin>>GRAPH[i][j];
    }
  }
  for (int k = 0; k < N; k++)
  {
    for (int i = 0; i < N; i++)
    {
      for (int j = 0; j < N; j++)
      {
        if(GRAPH[i][j] > GRAPH[i][k] + GRAPH[k][j])
        {
          GRAPH[i][j] =  GRAPH[i][k] + GRAPH[k][j];
        }
      }

    }

  }

  vector<vector<int> > DATA(H,vector<int>(H));
  int ANS = 0;
  for (int h = 0; h < H; h++)
  {
    for (int w = 0; w < W; w++)
    {
      int A;
      cin>>A;
      if((A + 1)*(A-1) != 0)
      {
        ANS += GRAPH[A][1];
      }
    }


  }

  cout<<ANS<<endl;

  return;
}


