int dfs(int curr, const vector<vector<int> >& c, bitset<10> passed) {
    passed.set(curr);
    int ret = c[curr][1];
    for (int i = 0; i < 10; ++i) {
        if (!passed[i] && i != curr && i != 1) {
            ret = min(ret, dfs(i, c, passed) + c[curr][i]);
        }
    }
    return ret;
}

