    for(int i = 0; i < 10; i++){
        for(int j = 0; j < 10; j++){
            cin >> board[i][j];
        }
    }
    int necessary_cost[10];
    bool if_finished[10];
    for(int i = 0; i < 10; i++){
        necessary_cost[i] = 1e9;
        if_finished[i] = false;
    }
    necessary_cost[1] = 0;
    while(true){
        int min_cost = 1e9;
        int min_cost_number = -1;
        for(int i = 0; i < 10; i++){
            if(min_cost > necessary_cost[i] && !if_finished[i]){
                min_cost = necessary_cost[i];
                min_cost_number = i;
            }
        }
        if(min_cost_number == -1){
            break;
        }
        for(int i = 0; i < 10; i++){
            if(min_cost_number != i){
                necessary_cost[i] = min(necessary_cost[i], min_cost + board[i][min_cost_number]);
            }
        }
        if_finished[min_cost_number] = true;
    }
    int ans = 0;
    for(int i = 0; i < H; i++){
        for(int j = 0; j < W; j++){
            int input;
            cin >> input;
            if(input != -1){
                ans += necessary_cost[input];
            }
        }
    }
    cout << ans << endl;
}

