int dp(int i,int cnt){
  int rec=INF;
  if(memo[i][cnt]!=-1)return memo[i][cnt];
  if(i==1)return 0;
  if(cnt>9)return INF;
  for(int j=0;j<10;j++){
    rec=min(rec,dp(j,cnt+1)+c[i][j]);
  }
  return memo[i][cnt]=rec;
}

