bool warshall_floyd(){
  rep(k,0,V) rep(i,0,V){
    if(d[i][k]==INF)continue;
    rep(j,0,V){
      if(d[k][j]==INF)continue;
      d[i][j] = min(d[i][j],d[i][k]+d[k][j]);
    }
  }
  rep(i,0,V) if(d[i][i] < 0) return true;
  return false;
}

