struct UF
{
public:
	ll tsize;
	ll mode;
	ll connect = 0;
	vll nodeSize;
	vll par;
	vll rank;
	UF(){};
	UF(const UF &uf) {}
	UF(ll _size, ll _mode = 0)
	{
		tsize = _size;
		mode = _mode;
		par.assign(tsize, -1);
		if (!mode)
			rank.resize(tsize, 0);
		nodeSize.resize(tsize, 1);
	}
	ll root(ll x)
	{
		return par[x] < 0 ? x : par[x] = root(par[x]);
	}
	bool isRoot(ll x)
	{
		return root(x) == x;
	}
	void unite(ll x, ll y)
	{
		x = root(x);
		y = root(y);
		if (x == y)
			return;
		if (mode)
		{
			par[x] += par[y];
			par[y] += x;
		}
		else
		{
			connect -= sumOfRange(nodeSize[x]) + sumOfRange(nodeSize[y]);
			connect += sumOfRange(nodeSize[x] + nodeSize[y]);
			if (rank[x] < rank[y])
			{
				nodeSize[y] += nodeSize[x];
				par[y] += par[x];
				par[x] = y;
			}
			else
			{
				nodeSize[x] += nodeSize[y];
				par[x] += par[y];
				par[y] = x;
				if (rank[x] == rank[y])
					rank[x]++;
			}
		}
	}
	bool same(ll x, ll y)
	{
		return root(x) == root(y);
	}
	ll size(ll x)
	{
		return -par[root(x)];
	}
};


class Vertex
{
  public:
