int dfs(int i, vector<int> p = vector<int>())
{
    if (dp[i] >= 0)
    {
        return dp[i];
    }
    int closest = c[i][1];
    p.emplace_back(i);
    rep(k, 10)
    {
        if (find(p.begin(), p.end(), k) != p.end())
            continue;
        closest = min(closest, dfs(k, p) + c[i][k]);
    }
    if (p.size() == 1)
        dp[i] = closest;
    return closest;
}

