void warshallFloyd(vector<vector<int>>& g){
  int n = g.size();
  REP(k, n){
    REP(i, n){
      REP(j, n){
        if(g[i][k] == INF || g[k][j]==INF) continue;
        if(g[i][k] + g[k][j] < g[i][j]){
          g[i][j] = g[i][k] + g[k][j];
        }
      }
    }
  }
}

