vector<vector<ll> > WarshallFloyd(vector<vector<P> >& adj) {
	int n=(int)adj.size();
	vector<vector<vector<ll> > > dp(n+1, vector<vector<ll> >(n, vector<ll>(n, INF*INF)));
	for(int i=0; i<n; ++i) dp[0][i][i]=0;
	for(int i=0; i<n; ++i) {
		for(int j=0; j<adj[i].size(); ++j) {
			dp[0][i][adj[i][j].first]=adj[i][j].second;
		}
	}

	for(int i=1; i<n+1; ++i) {
		for(int j=0; j<n; ++j) {
			for(int k=0; k<n; ++k) {
				dp[i][j][k]=min(dp[i-1][j][k], dp[i-1][j][i-1]+dp[i-1][i-1][k]);
			}
		}
	}
	return dp[n];
}

