typedef long long ll;
typedef unsigned long long ull;

array<vector<ll>,2> Dijkstra(vector<vector<ll>> g, vector<vector<ll>> w, ll istart){
    auto n = g.size();
    priority_queue<array<ll,2>> q;
    vector<ll> d(n, numeric_limits<ll>::max());
    vector<ll> prev(n, -1);

    d[istart] = 0;
    q.push(array<ll,2>{-0, istart});

    while(!q.empty()){
        auto u = q.top()[1]; q.pop();
        for(size_t i=0; i<g[u].size(); i++){
            auto v = g[u][i];
            auto alt = d[u] + w[u][i];
            if(alt < d[v]){
                d[v] = alt;
                prev[v] = u;
                q.push(array<ll,2>{-alt, v});
            }
        }
    }
    return array<vector<ll>,2>{d, prev};
}

