  int total = 0;
  for (int h = 0; h < H; ++h) {
    for (int w = 0; w < W; ++w) {
      int A;
      scanf("%d", &A);

      if (A == -1) continue;
      total += cost[A][1];
    }
  }

  printf("%d\n", total);
  return 0;
}

