void djkstra(int N, vector<vector<int> >& edges, vector<int>& state, vector<int>& dist){
    dist[1] = 0;
    while(1){
        int min_i = -1, min_v = INFTY;
        for(int i=0;i<N;++i){
            if(state[i] == 0 && min_v > dist[i]){
                min_i = i;
                min_v = dist[i];
            }
        }
        if(min_i == -1) break;
        state[min_i] = 1;
        for(int e =0;e<N;++e){
            if(state[e] == 0 && dist[e] > dist[min_i] + edges[e][min_i]){
                dist[e] = dist[min_i] + edges[e][min_i];
            }
        }
    }
}

