#define MAX_V 11

vector<pair<ll, ll>> G[MAX_V];

// ダイクストラ法
vector<ll> dijkstra(ll start) {
	vector<ll> dist(MAX_V, inf);
	dist[start] = 0; // dist[i] := start->iまでの最短距離
	priority_queue < pair<ll, ll>, vector<pair<ll, ll>>, greater<pair<ll, ll>>> que;
	que.push({ 0, start });
	while (!que.empty()) {
		ll cost, u; // 今までにかかった時間　現在の頂点
		cost = que.top().first, u = que.top().second;
		que.pop();
		if (dist[u] < cost) continue;
		for (auto tmp : G[u]) {
			ll v = tmp.first, time = tmp.second; // 隣接する頂点、その頂点まで行く時間
			if (dist[v] > dist[u] + time) {
				dist[v] = dist[u] + time;
				que.push({ dist[v], v });
			}
		}
	}
	return dist;
}

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	int h, w;
	cin >> h >> w;
	vector<vector<int>> c(10, vector<int>(10));
	rep(i, 10) {
		rep(j, 10) {
			cin >> c[i][j];
			G[i].push_back({ j, c[i][j] });
		}
	}
	vector<vector<int>>a(h, vector<int>(w));
	rep(i, h)rep(j, w) cin >> a[i][j];

	// それぞれの数字の数を保存
	vector<int> num(10, 0);
	rep(i, h) {
		rep(j, w) {
			if (a[i][j] == -1) continue;
			num[a[i][j]]++;
		}
	}

	// これグラフ理論では？
	// ダイクストラ法使えそう

	int ans = 0;

	rep(i, 10) {
		// iから1へ行く
		if (num[i] == 0) continue;
		auto dist = dijkstra(i);
		ans += dist[1] * num[i];
	}

	// 計算量はO(HW) or O(100log(HW)) := O(1000) でいいのかな

	cout << ans << endl;

	return 0;
}

