void dijstkra(ll n,ll source) {

    for(ll i=0; i<=n; i++) {
        dis[i] = INF;
    }

    priority_queue<node>q;
    q.push(node(source,0));
    dis[source] = 0;

    while(!q.empty()) {
        node top = q.top();
        q.pop();
        ll u=top.u;

        for(ll i=0; i<(ll)g[u].size(); i++) {
            ll v=g[u][i];

            //Relaxation
            if(dis[u] + cost[u][i] < dis[v]) {
                dis[v] = dis[u] + cost[u][i];
                q.push(node(v, dis[v]));
            }
        }
    }
}

