/** ワーシャル・フロイド法による全点対最短路探索

    経路を逐次最小化していく。

    頂点番号は0オリジン。

    知らないパスにはコスト大きめを設定しておくこと。
    その初期コストはすべての都市を回ってくるパスよりも大きくすべし。
    ただ、内部で加算するのでオーバーフローに注意。MAXダメ、絶対。
    std::fill(mat.data(), mat.data() + mat.num_elements(), MAXCOST+1);

    O(|V|^3)

    @note 反対方向もいれた？
    mat[a][b] = mat[b][a] = c;

    @note 自分自身へのルートはコスト0か？
    for (int i = 0; i < N; ++i) {
    mat[i][i] = 0;
    }

    @param[in] V  頂点数
    @param[in, out] distance[i][j]: 頂点i -> jのコスト
*/
template<typename T, typename M>
void warshall_floyd(T V, M& distance)
{
    for (T k = 0; k < V; ++k) {
        for (T i = 0; i < V; ++i) {
            for (T j = 0; j < V; ++j) {
                distance[i][j] = std::min(distance[i][j],
                                          distance[i][k] + distance[k][j]);
            }
        }
    }
}


int main()
{
    int64_t H, W;
    std::cin >> H >> W;

    boost::multi_array<int64_t, 2> c(boost::extents[10][10]);

    for (auto p = c.data(); p < (c.origin() + c.num_elements()); ++p) {
        std::cin >> *p;
    }


    boost::multi_array<int64_t, 2> A(boost::extents[H][W]);
    for (auto p = A.data(); p < (A.origin() + A.num_elements()); ++p) {
        std::cin >> *p;
    }

    warshall_floyd(10, c);

    int64_t ans = 0;

    for (auto p = A.data(); p < (A.origin() + A.num_elements()); ++p) {
        if (*p != -1) {
            ans += c[*p][1];
        }
    }

    std::cout << ans << std::endl;

    return 0;
}

