const int kInf = 0x3F3F3F3F;

template <class T>
vector<T> Dijkstra(
            vector<vector<T> >& g,
            typename vector<T>::size_type s
) {
  typedef typename vector<T>::size_type size_type;

  size_type MAX_SIZE = numeric_limits<size_type>::max();
  size_type n = g.size();

  vector<T> d(n, kInf);
  vector<size_type> pa(n, MAX_SIZE);
  d[s] = 0;
  priority_queue<pair<size_type, T> > q;
  q.push(make_pair(s, 0));

  while (!q.empty()) {
    const size_type u = q.top().first;
    const T cost = -q.top().second;
    q.pop();
    for (size_type v = 0; v < n; v++) {
      if (v == s) { continue; }
      const T c = d[u] + g[u][v];
      if (d[v] > c) {
        d[v] = c;
        pa[v] = u;
        q.push(make_pair(v, -c));
      }
    }
  }

  return d;
}

int main(int argc, char const *argv[]) {
  long ans = 0;
  int h, w;

  cin >> h >> w;
  vector<vector<int>> g(10, vector<int>(10));
  for (int i = 0; i < 10; ++i) {
    for (int j = 0; j < 10; ++j) {
      cin >> g[j][i];
    }
  }

  vector<int> count(10, 0);
  for (int i = 0; i < h; ++i) {
    for (int j = 0; j < w; ++j) {
      int num;
      cin >> num;
      if (num == -1) { num = 1; }
      ++count[num];
    }
  }

  auto diss = Dijkstra(g, 1);
  for (int i = 0; i < 10; ++i) {
    ans += count[i] * diss[i];
  }
  cout << ans << endl;

  return 0;
}

