struct edge
{
	int from, to, cost;
};

int h, w;
int a[15];
edge es[95];
int cnt;
long long d[15];
int main() {
	std::cin >> h >> w;
	for (int i = 0; i < 10; ++i)
		for (int j = 0; j < 10; ++j) {
			int tmp;
			std::cin >> tmp;
			if (i != j) {
				edge e;
				e.from = i;
				e.to = j;
				e.cost = tmp;
				es[cnt++] = e;
			}
		}

	for (int i = 0; i < h; ++i)
		for (int j = 0; j < w; ++j) {
			int in;
			std::cin >> in;
			if (in != -1 && in != 1)
				++a[in];
		}

	std::fill(d, d + 10, 999999999);
	d[1] = 0;
	while (true)
	{
		bool update = false;
		for (int i = 0; i < 90; ++i) {
			auto e = es[i];
			if (d[e.to] != 999999999 && d[e.from] > d[e.to] + e.cost) {
				d[e.from] = d[e.to] + e.cost;
				update = true;
			}
		}

		if (!update)
			break;
	}

	long long ans = 0;
	for (int i = 0; i < 10; ++i)
		ans += d[i] * a[i];

	std::cout << ans << std::endl;
	return 0;
}

