class Edge {
public:
	ll from,to,cost;
	Edge() {}
	Edge(ll from, ll to, ll cost) : from(from), to(to), cost(cost) {}
	bool operator < (const Edge &another) const {
		return cost != another.cost ? (cost > another.cost) : 
			(from != another.from ? from < another.from : to < another.to);
	}
};

/*
引数
 start:探索するスタートノード番号
 node_size:ノードの数、0〜(node_size-1)がノード番号として定義される
戻り値
　dist:スタートノードから各頂点までの距離
　prev:最短路木の親頂点
*/
void dijkstra(const vector<vector<Edge>> &g, ll start, vector<ll> &dist, vector<ll> &prev) {
	ll gsize = g.size();
	dist.assign(gsize, INF); dist[start] = 0;
	prev.assign(gsize, -1);

	priority_queue<Edge> que;
	que.push(Edge(-INF, start, 0));
	while (!que.empty()) {
		Edge e = que.top();
		que.pop();
		if (prev[e.to] != -1) continue;
		prev[e.to] = e.from;
		for(auto f=(g[e.to]).begin(); f!=(g[e.to]).end(); f++){
			if (dist[f->to] > e.cost + f->cost) {
				dist[f->to] = e.cost + f->cost;
				que.push(Edge(f->from, f->to, e.cost+f->cost));
			}
		}
	}
