struct ST {
  pair<int, int> pos;
  int x, cost;
  ST() {}
  ST(int i, int j, int xx, int c) {
    pos = {i, j};
    x = xx;
    cost = c;
  }
};

int make_key (pair<int, int> x) {
  return x.first * 10 + x.second;
}

int solve (int x, vector<vector<int>> &wall, vector<vector<int>> &cost) {
  queue<ST> Q;
  Q.push(ST(-1, -1, x, 0));
  unordered_map<int, bool> visited;

  int mm = INT_MAX;
  while (!Q.empty()) {
    ST cur = Q.front(); Q.pop();
    visited[make_key(cur.pos)] = true;
    if (cur.x == 1) {
      mm = min(mm, cur.cost);
      continue;
    }

    for (int k = 0; k < 10; ++k) {
      if (k == cur.x) continue;
      ST next = ST(cur.x, k, k, cur.cost + cost[cur.x][k]);
      if (visited.count(make_key(next.pos)) == 0) {
        Q.push(next);
      }
    }
  }

  return mm;
}

