#include <stdio.h>
#include <stdlib.h>
int sub[10][10];
int num[10];
typedef struct qq{
    int cost;
    int num;
}qq;
qq change[10];
int cmp(const void*v1, const void*v2){
    return ((qq*)v1)->cost -((qq*)v2)->cost;
}
int main(void){
    int H, W;
    scanf("%d %d", &H, &W);
    for(int i = 0; i < 10; i++)
        for(int j = 0; j < 10; j++)
            scanf("%d", &sub[i][j]);

    for(int i = 0; i < H; i++)
        for(int j = 0; j < W; j++){
            int tmp;
            scanf("%d", &tmp);
            if(tmp == -1 && tmp == 1) continue;
            num[tmp]++;
        }

    for(int i = 0; i < 10; i++){
        change[i].cost = sub[i][1];
        change[i].num = i;
    }
    qsort(change, 10, sizeof(qq), cmp);

    for(int i = 1; i < 10; i++){
        int min = change[i].cost;
        for(int j = 0; j < 10; j++){
            if(sub[change[i].num][change[j].num] + change[j].cost < min)
                min = sub[change[i].num][change[j].num] + change[j].cost;
        }
        change[i].cost = min;
    }
    int sum = 0;
    for(int i = 0; i < 10; i++){
        if(i == 1) continue;
        int flag = 0;
        for(int j = 0; j < 10; j++){
            if(change[j].num == i){
                flag = change[j].cost;
                break;
            }
        }
        sum += num[i]*flag;
    }
    printf("%d", sum);
    return 0;
}

