	uli gcd(uli a, uli b) {
		while (1) {
			if (a < b) swap(a, b);
			if (!b) break;
			a %= b;
		}
		return a;
	}

	uli lcm(uli a, uli b)
	{
		return a / gcd(a, b) * b;
	}

	const uli mod = 1000000007;
