class BFS {
private:
    vvi table;
public:
    BFS(int SIZE) {
        table.resize(SIZE);
        for (auto& elem : table) {
            elem.resize(SIZE);
        }
        rep(i, SIZE)rep(j, SIZE) cin >> table[i][j];
    }

    int solve(int start) {
        vi Cost;
        Cost.resize(table.size(), pint_INF);
        Cost[start] = 0;
        queue<int> S;
        S.push(start);

        while (!S.empty()) {
            int u = S.front(); // pop条件で調節
            int v = next(Cost,u);

            if (v == -1) {
                S.pop();
                continue;
            }
            else {
                Cost[v] = Cost[u] + table[u][v];
                S.push(v);
            }


        }
        return Cost[1];
    }

    int next(vi& Cost, int u) {
        for (int v = 0; v < table.size(); v++) {
                if (Cost[u] + table[u][v] < Cost[v]) {
                    return v;
                }
        }
        return -1;
    }

};
