	  update = true;
	  //std::cout << i << " " << distance[i] << " " << j << " " << distance[j] << std::endl;
	}
      }
    }
    if (!update){ break; }
  }

  ll ans = 0;
  for (int w = 0; w < W; w++) {
    for (int h = 0; h < H; h++) {
      if (wh[w][h] != -1) {
	ans += distance[wh[w][h]];
      }
    }
  }

  std::cout << ans << std::endl;

  return 0;
}

