      int c;
      cin >> c;
      edge e = {j,c};
      G[i].pb(e);
    }
  }

  ll dis[10][10];
  REP(i,10){
    dijkstra(i);
    REP(j,10){
      dis[i][j] = d[j];
    }
  }
  ll sum = 0;
  REP(i,10){
    //cout << "i = " << d[i] << endl;
  }
  REP(i,h){
    REP(j,w){
      int a;
