  static const int INF = 1<<28;
  struct edge {
    int from, to, dist;
  };

  int V_SIZE = 0;
  std::vector<edge> G[V_MAX];

  int wf_dp[V_MAX][V_MAX];
  bool wf_initialized = false;
  void wf_init() {
    if(wf_initialized) return;
    assert(V_SIZE > 0);
    for(int i = 0; i < V_SIZE; i++)
    for(int j = 0; j < V_SIZE; j++) {
      if(i == j) wf_dp[i][j] = 0;
      else {
        auto itr = find_if(G[i].begin(), G[i].end(), [j](edge e) { return e.to == j; });
        if(itr != G[i].end()) wf_dp[i][j] = itr->dist;
        else wf_dp[i][j] = INF;
      }
    }
    for(int k = 0; k < V_SIZE; k++)
    for(int i = 0; i < V_SIZE; i++)
    for(int j = 0; j < V_SIZE; j++) {
      wf_dp[i][j] = std::min(wf_dp[i][j], wf_dp[i][k] + wf_dp[k][j]);
    }
    wf_initialized = true;
  }
}

namespace solver {
  using namespace std;
  using namespace graph;
  typedef long long ll;

  ll H, W, A[40040];

  void init() {
    scanf("%lld %lld", &H, &W);
    int c;
    V_SIZE = 10*10;
    rep(i, 10) rep(j, 10) {
      scanf("%d", &c);
      G[i].push_back({i, j, c});
    }
    rep(i, H*W) scanf("%lld", A+i);
  }

  void solve() {
    ll ans = 0;
    wf_init();
    rep(i, H*W) if(A[i] != -1) {
      ans += wf_dp[A[i]][1];
    }
    cout << ans << endl;
  }
}

int main() {
  solver::init();
  solver::solve();
  return 0;
}

