int dfs(int i, int rest){
  if (cost[i]< INF) return cost[i];
  if (rest <= 0) return INF;
  int ans = INF;
  rep(j, 10){
    int m;
    if (i == j) m = INF;
    else m = c[i][j] + dfs(j, rest - c[i][j]);
    ans = min(ans, m);
  }
  cost[i]= ans;
  return ans;
}

