int H, W;
int c[10][10];
int A[201][201];

bool used[10] = {false};

int cnt[10] = {1000000000};

int dfs(int n, int s) {
    int ret = 1000000;
    REP(i, 10) {
        if (i==1)
            continue;
        if (!used[i]) {
            used[i] = true;
            ret = min(min(ret, s+c[n][1]), dfs(i, s+c[n][i]));
            used[i] = false;
        }
    }
    return ret;
}

int main()
{
    scanf("%d %d", &H, &W);
    REP(i, 10) {
        REP(j, 10)
            scanf(" %d", &c[i][j]);
    }
    REP(i, H) {
        REP(j, W)
            scanf(" %d", &A[i][j]);
    }


    REP(i, 10) {
        cnt[i] = dfs(i, 0);
    }
    int ans = 0;
    REP(i, H) {
        REP(j, W) {
