        int u = minDistance(dist, checkFlag);
        checkFlag[u] = 1;
        for (int v = 0; v < N; v++)
            if (!checkFlag[v] && graph[u][v]
                && dist[u] != INF
                && dist[u]+graph[u][v] < dist[v])
                dist[v] = dist[u] + graph[u][v];
//        for (int i = 0; i < N; i++)
//            printf("%d -> %d\n", i, dist[i]);
    }


}

