        }
    }

    for(int i=0; i < H; i++){
        for(int j=0; j<W; j++){
            cin >> A[i][j];
        }
    }
    int dist[N];
    //calc all node min cost changing to 1
    dijkstra(graph, 1, dist);

    int cost = 0;
    for(int i=0; i < H; i++){
        for(int j=0; j<W; j++){
            if(A[i][j] == -1 || A[i][j] == 1)continue;

            cost += dist[(A[i][j])];
        }
    }
    cout << cost << endl;

    return 0;
}

