#include <cstdio>
#include <algorithm>
using namespace std;

const int maxn = 10;
int e[maxn][maxn];
int h, w;

void floyd()
{
    for (int k = 0; k < maxn; k++)
        for (int i = 0; i < maxn; i++)
            for (int j = 0; j < maxn; j++)
                e[i][j] = min(e[i][j], e[i][k] + e[k][j]);
}

int main(void)
{
    while (scanf("%d %d", &h, &w) != EOF && h != 0 && w != 0)
    {
        for (int i = 0; i < maxn; i++)
            for (int j = 0; j < maxn; j++)
                scanf("%d", &e[i][j]);
        floyd();

        int ans = 0;
        for (int i = 0; i < h; i++)
        {
            for (int j = 0; j < w; j++)
            {
                int tmp;
                scanf("%d", &tmp);
                if (tmp != -1 && tmp != 1)
                {
                    ans += e[tmp][1];
                }
            }
        }
        printf("%d\n", ans);
    }

    return 0;
}

