ll ans(vector<vector<int>> field,int to,int end,int now){
    int mn = INF;
    int id;
    if(to==1)return min(end,now);
    rep(i,10){
        if(to==i)continue;
        if(mn>field[to][i]){
            mn = field[to][i];
            id = i;
        }
    }
    if(end==0)end = field[to][1];
    else end = min(end,now+field[to][1]);
    now += mn;
    if(end<=now)return end;
    else return ans(field,id,end,now);
}

