void warshall_floyd(vector<vector<int>>& G, ll n){
  for (int k = 0; k < n; ++k){      //経由する頂点
    for (int i = 0; i < n; ++i){    //始点
      for (int j = 0; j < n; ++j){  //終点
        G[i][j] = min(G[i][j], G[i][k] + G[k][j]);
      }
    }
  }
}

