class DIJKSTRA {
  typedef long long ll;

  private:
    std::vector<ll> from;
    std::vector<ll> cost;
    std::vector<std::unordered_map<ll, ll>> direction;
    ll start;
    bool directed;

  public:

    DIJKSTRA ( ll N , bool dir = false ) : directed(dir) {
      from.assign(N, std::numeric_limits<ll>::max());
      cost.assign(N, std::numeric_limits<ll>::max());
      direction.resize(N);
    }

    void push ( ll i, ll j, ll x ) {
      direction[i][j] = x;
      if ( !directed ) direction[j][i] = x;
    }

    void SetStart( ll i ) {
      start = i;
      cost[i] = 0;
      from[i] = i;
    }

    void Go () {
      std::priority_queue<std::pair<ll,ll>> pq;
      pq.push( {0, start} );

      while(!pq.empty()){
        auto cur = pq.top(); pq.pop();
        if ( cost[cur.second] < (cur.first * -1) ) continue;
        for(auto itr = direction[cur.second].begin(); itr != direction[cur.second].end(); ++itr) {
          if ( cost[itr->first] > cost[cur.second]+itr->second ) {
            cost[itr->first] = cost[cur.second]+itr->second;
            pq.push( { (cost[itr->first]*-1), itr->first } );
          }
        }
      }
      return;
    }

    ll get_cost ( ll i ){
      return cost[i];
    }

    std::string get_path ( ll i ) {
      std::string rtn = std::to_string(i) + " " ;
      ll cur = i;
      while( from[cur] != cur ) {
        rtn += std::to_string(from[cur]) + " ";
        cur = from[cur];
      }
      rtn += "(start)";
      return rtn;
    }
};


int main (void) {
  std::cin.tie(0);  std::ios::sync_with_stdio(false);
  int H, W; std::cin >> H >> W;
  std::vector<std::vector<int>> c(10, std::vector<int>(10));
  rep(i,10) rep(j,10) std::cin >> c[i][j];

  std::vector<int> A(10);
  rep(i,H) rep(j,W) {
    int a; std::cin >> a;
    if ( a == -1 ) continue;
    A[a]++;
  }

  ll ans = 0;
  for(int i=0; i<10; i++) {
    // i -> 1
    DIJKSTRA d(10, true);
    rep(m,10) rep(n,10) d.push(m,n,c[m][n]);
    d.SetStart(i);
    d.Go();
    ans += (A[i]*d.get_cost(1));
  }
  std::cout << ans << std::endl;

  return 0;
}

