void DIJX(int st) {
	for (int i = 0; i<V; i++)d[i] = INF; // std::fillでも書ける
	d[st] = 0; // 始点
	std::priority_queue<PP, std::vector<PP>, std::greater<PP>> pq;
	pq.push(std::make_pair(d[st], st)); // (cost,頂点番号)
	while (!pq.empty()) {
