int dijkstra(int src) {
  vector<int> res(10, inf);
  set<pair<int,int>> fringe;
  for (int i=0; i<=9; i++) {
    fringe.insert({cost[src][i], i});
  }

  while (!fringe.empty()) {
    auto cur = *fringe.begin();
    fringe.erase(fringe.begin());
    int v = cur.second;
    int dist = cur.first;
    if (dist < res[v]) {
      res[v] = dist;
      for (int to=0; to<=9; to++) {
        fringe.insert({dist + cost[v][to], to});
      }
    }
  }
  return res[1];
}

