// 内部定数
#define D_HEAP_MAX		10000									// 最大ヒープ数
#define D_NO_CNT		10										// 数字種類数
#define D_MAGIC_MAX		1000									// 最大魔力

// 内部構造体 - 魔力情報
typedef struct Magic {
	int miFNo;													// 数字 - 変更前
	int miTNo;													// 数字 - 変更後
	int miVal;													// 必要魔力
} Magic;

// 内部変数
static Magic sz1Heap[D_HEAP_MAX];								// ヒープ
static int siHCnt;												// ヒープ数
static int si2Magic[D_NO_CNT][D_NO_CNT];						// 必要魔力

// 内部変数 - テスト用
#ifdef D_TEST
	static int siRes;
	static FILE *szpFpT, *szpFpA;
#endif

// ヒープ - 親子関係チェック
// 戻り値：[>=0]:変更した子の配列番号 [-1]:変更なし
int
fHeapChk(
	int piPNo					// <I> 親の配列番号 0～
)
{
	// 最小値
	int liMNo = piPNo;

	// 左の子と比較
	int liCNo = piPNo * 2 + 1;
	if (liCNo < siHCnt) {
		if (sz1Heap[liMNo].miVal > sz1Heap[liCNo].miVal) {
			liMNo = liCNo;
		}
	}

	// 右の子と比較
	liCNo = piPNo * 2 + 2;
	if (liCNo < siHCnt) {
		if (sz1Heap[liMNo].miVal > sz1Heap[liCNo].miVal) {
			liMNo = liCNo;
		}
	}

	// 自分が最小値であるかチェック
	if (piPNo == liMNo) {
		return -1;
	}

	// 値の交換
	Magic lzWork;
	memcpy(&lzWork, &sz1Heap[liMNo], sizeof(Magic));
	memcpy(&sz1Heap[liMNo], &sz1Heap[piPNo], sizeof(Magic));
	memcpy(&sz1Heap[piPNo], &lzWork, sizeof(Magic));

	return liMNo;
}

// ヒープ - キュー追加
int
fHeapEnqueue(
	int piFNo					// <I> 数字 - 変更前
	, int piTNo					// <I> 数字 - 変更後
	, int piVal					// <I> 必要魔力
)
{
	int liRet;

	// 末尾に追加
	sz1Heap[siHCnt].miFNo = piFNo;		// 数字 - 変更前
	sz1Heap[siHCnt].miTNo = piTNo;		// 数字 - 変更後
	sz1Heap[siHCnt].miVal = piVal;		// 必要魔力
	siHCnt++;

	// 親子関係チェック
	int liNo = siHCnt - 1;
	while (1) {

		// 親の配列番号
		liNo = (liNo - 1) / 2;

		// 親子関係チェック
		liRet = fHeapChk(liNo);
		if (liRet < 0) {
			break;
		}
	}

	return 0;
}

// ヒープ - キュー取得
int
fHeapDequeue(
	Magic *pzpRet				// <O> 取得データ
)
{
	// データ数
	if (siHCnt < 1) {
		return -1;
	}

	// 取得
	memcpy(pzpRet, &sz1Heap[0], sizeof(Magic));
	siHCnt--;

	// データ数
	if (siHCnt < 1) {
		return 0;
	}

	// 末尾を先頭へ
	memcpy(&sz1Heap[0], &sz1Heap[siHCnt], sizeof(Magic));

	// 親子関係チェック
	int liNo = 0;
	while (liNo >= 0) {
		liNo = fHeapChk(liNo);
	}

	return 0;
}

