int
fMain(
	int piTNo					// <I> テスト番号 1～
)
{
	int i, j, liRet;
	char lc1Buf[1024], lc1Out[1024];

	// データ初期化
	siHCnt = 0;													// ヒープ数

	// テストファイルオープン
#ifdef D_TEST
	sprintf(lc1Buf, ".\\Test\\T%d.txt", piTNo);
	szpFpT = fopen(lc1Buf, "r");
	sprintf(lc1Buf, ".\\Test\\A%d.txt", piTNo);
	szpFpA = fopen(lc1Buf, "r");
	siRes = 0;
#endif

	// 高さ・幅取得
	int liH, liW;
#ifdef D_TEST
	fgets(lc1Buf, sizeof(lc1Buf), szpFpT);
#else
	fgets(lc1Buf, sizeof(lc1Buf), stdin);
#endif
	sscanf(lc1Buf, "%d%d", &liH, &liW);

	// 魔力情報取得・ヒープにセット
	for (i = 0; i < D_NO_CNT; i++) {
		for (j = 0; j < D_NO_CNT; j++) {
#ifdef D_TEST
			fscanf(szpFpT, "%d", &si2Magic[i][j]);
#else
			fscanf(stdin, "%d", &si2Magic[i][j]);
#endif

			// ヒープにセット
			if (i != j) {
				fHeapEnqueue(i, j, si2Magic[i][j]);
			}
		}
#ifdef D_TEST
		fgets(lc1Buf, sizeof(lc1Buf), szpFpT);
#else
		fgets(lc1Buf, sizeof(lc1Buf), stdin);
#endif
	}

	// 必要魔力 - 更新
	while (1) {

		// ヒープ取得
		Magic lzMagic;
		liRet = fHeapDequeue(&lzMagic);
		if (liRet != 0) {
			break;
		}

		// 更新チェック
		if (si2Magic[lzMagic.miFNo][lzMagic.miTNo] < lzMagic.miVal) {
			continue;
		}
		si2Magic[lzMagic.miFNo][lzMagic.miTNo] = lzMagic.miVal;				// 更新

		// 魔力情報作成・ヒープにセット
		for (i = 0; i < D_NO_CNT; i++) {
			if (lzMagic.miFNo == i) {
				continue;
			}
			if (lzMagic.miTNo == i) {
				continue;
			}

			// 魔力チェック
			int liVal = lzMagic.miVal + si2Magic[lzMagic.miTNo][i];
			if (liVal >= D_MAGIC_MAX) {
				continue;
			}

			// ヒープにセット
			fHeapEnqueue(lzMagic.miFNo, i, liVal);
		}
	}

	// 現在の数字取得・合計値取得
	int liSum = 0;
	for (i = 0; i < liH; i++) {
		for (j = 0; j < liW; j++) {
			int liNo;
#ifdef D_TEST
			fscanf(szpFpT, "%d", &liNo);
#else
			fscanf(stdin, "%d", &liNo);
#endif

			// 合計値加算
			if (liNo < 0 || liNo == 1) {
				continue;
			}
			liSum += si2Magic[liNo][1];
		}
#ifdef D_TEST
		fgets(lc1Buf, sizeof(lc1Buf), szpFpT);
#else
		fgets(lc1Buf, sizeof(lc1Buf), stdin);
#endif
	}

	// 結果セット
	sprintf(lc1Out, "%d\n", liSum);

	// 結果表示
#ifdef D_TEST
	fgets(lc1Buf, sizeof(lc1Buf), szpFpA);
	if (strcmp(lc1Buf, lc1Out)) {
		siRes = -1;
	}
#else
	printf("%s", lc1Out);
#endif

	// テストファイルクローズ
#ifdef D_TEST
	fclose(szpFpT);
	fclose(szpFpA);
#endif

	// テスト結果
#ifdef D_TEST
	if (siRes == 0) {
		printf("OK %d\n", piTNo);
	}
	else {
		printf("NG %d\n", piTNo);
	}
#endif

	return 0;
}

