int min(int c[])
{
	int min;
	if (c[0] == 0) min = c[1];
	else min = c[0];
	for (int i = 0; i <N; i++){
		if (c[i] < min&&c[i]!=0) min =c[i];
	}
	return min;
}
int minId(int c[])
{
	int min; int cnt;
	if (c[0] == 0) {
		min = c[1]; cnt = 1;
	}
	else {
		min = c[0]; cnt = 0;
	}
	for (int i = 0; i <N; i++){
		if (c[i] < min&&c[i] != 0) {
			cnt=i;
		}
	}
	return cnt;
}

