// <arr[0]> <arr[1]> .. <arr[size-1]>
int fget_array(int *arr, int size) {
#ifdef BUF_SIZE
    char line[BUF_SIZE];
    char *tmpbuf = line;
    int i;
    if(!fgets(line, BUF_SIZE, stdin)) return -1;
    for(i = 0; i < size; i++) {
        char *tmp = strtok(tmpbuf, " ");
        arr[i] = strtol(tmp, NULL, 10);
        tmpbuf = NULL;
    }
#else
#error
#endif
    return 0;
}

int main(void) {
    int graph[VERTEXES][VERTEXES];
    memset(graph, 0x01, sizeof(int)*VERTEXES*VERTEXES);
    int cnt_map[VERTEXES] = {0};
    int row, col;
    get_int2(&row, &col);
    int i, j, k;
    for(i = 0; i < VERTEXES; i++) {
        fget_array(graph[i], VERTEXES);
    }

    for(i = 0; i < row; i++) {
        static int buf[COL_MAX];
        fget_array(buf, col);
        for(j = 0; j < col; j++) {
            if(buf[j] == -1) continue;
            cnt_map[buf[j]]++;
        }
    }

    // * -> 1 (Warshall–Floyd Algorithm)
    for(k = 0; k < VERTEXES; k++) {
        for(i = 0; i < VERTEXES; i++) {
            for(j = 0; j < VERTEXES; j++) {
                int new = graph[i][k] + graph[k][j];
                if(new < graph[i][j]) {
                    graph[i][j] = new;
                }
            }
        }
    }

    int ans = 0;
    for(i = 0; i < VERTEXES; i++) {
        ans += (graph[i][1] * cnt_map[i]);
    }
    printf("%d\n", ans);

    return 0;
}

