                cost[loop1]=sel_min(cost[loop1],cost[last_kakutei]+change_data[loop1][last_kakutei]);
            }
        }
        //未確定の中での最小のやつを確定
        long kouho;
        long kouho_cost=INFTY;
        for(loop1=0;loop1<=9;loop1++){
            if(kakutei[loop1]==0){
                if(cost[loop1]<kouho_cost){
                    kouho_cost=cost[loop1];
                    kouho=loop1;
                }
            }
        }
        kakutei[kouho]=1;
        last_kakutei=kouho;

    }


    long ans=0;
    int target;
    for(loop1=0;loop1<H*W;loop1++){
        scanf("%d",&target);
        if(target!=-1){
            ans+=cost[target];
        }
    }
