int a[200][200], c[10][10], dist[10][10], h, w;
void dijkstra(int start) {
    int i, prev[10], queue[10], u, v;
    for (i = 0; i <= 9; ++i) {
        if (i == start) {
            dist[start][i] = 0;
        } else {
            dist[start][i] = INT_MAX;
        }
        prev[i] = -1;
        queue[i] = 1;
    }
    while (1) {
        for (i = 0; i <= 9; ++i) {
            if (queue[i]) {
                break;
            }
        }
        if (i == 10) {  /* queue is empty. */
            break;
        }
        u = i;
        for (i = 0; i <= 9; ++i) {
            if (queue[i]) {
                if (dist[start][i] < dist[start][u]) {
                    u = i;
                }
            }
        }
        queue[u] = 0;
        for (v = 0; v <= 9; ++v) {
            if (dist[start][v] > dist[start][u] + c[u][v]) {
                dist[start][v] = dist[start][u] + c[u][v];
                prev[v] = u;
            }
        }
    }
}
