    scanf("%d%d", &h, &w);
    for (i = 0; i <= 9; ++i) {
        for (j = 0; j <= 9; ++j) {
            scanf("%d", &c[i][j]);
        }
    }
    for (i = 0; i <= 9; ++i) {
        dijkstra(i);
    }
    for (i = 0; i < w; ++i) {
        for (j = 0; j < h; ++j) {
            scanf("%d", &a[i][j]);
            if (a[i][j] != -1) {
                sum += dist[a[i][j]][1];
            }
        }
    }
    printf("%d\n", sum);
    return 0;
}

