#define N 10
#define M 200

void minCost(int w[][N], int m[][N]){
	int i, j, k, D;
	int pre[N][N];
	for (i = 0; i < N; i++){
		for (j = 0; j < N; j++){
			m[i][j] = w[i][j];
			pre[i][j] = i;
		}
	}

	for (k = 0; k < N; k++){
		for (i = 0; i < N; i++){
			for (j = 0; j < N; j++){
				D = m[i][k] +m[k][j];
				if (D < m[i][j]){
					m[i][j] = D; 
					pre[i][j] = pre[k][j];
				}
			}
		}
	}
}
