		//printf("%d: ", i);
		for (j = 0; j < N; j++){
			 scanf("%d", &c[i][j]);
		}
	}
	//printf("Aij>>\n");
	for (i = 0; i < H; i++){
		//printf("%d: ", i);
		for (j = 0; j < W; j++){
			 scanf("%d", &A[i][j]);
		}
	}
	int minM[N][N];
	minCost(c, minM);
	int res = 0;
	for (i = 0; i < H; i++){
		for (j = 0; j < W; j++){
			if (A[i][j] == -1) res += 0;
