/** O((costMatrix.size)^3) costMatrix is changed */
fun warshallFloyd(costMatrix: Array<MutableList<Long>>): Array<MutableList<Long>> {
    val indices = costMatrix.indices
    for (k in indices) {
        for (i in indices) {
            for (j in indices) {
                if (costMatrix[i][k] != Long.MAX_VALUE && costMatrix[k][j] != Long.MAX_VALUE) {
                    costMatrix[i][j] = Math.min(costMatrix[i][j], costMatrix[i][k] + costMatrix[k][j])
                }
            }
        }
    }
    return costMatrix
}


