fun PrintWriter.solve(sc: FastScanner) {
    val h = sc.nextInt()
    val w = sc.nextInt()
    val c = Array(10) { Array(10) { sc.nextInt() } }
    val a = Array(h) { Array(w) { sc.nextInt() } }
    val wf = Array(10) { Array(10) { 1000000000 } }
    for (i in 0 until 10) {
        for (j in 0 until 10) {
            if (i != j) {
                wf[i][j] = c[i][j]
            }
        }
    }
    for (k in 0 until 10) {
        for (i in 0 until 10) {
            for (j in 0 until 10) {
                if (wf[i][j] > wf[i][k] + wf[k][j]) {
                    wf[i][j] = wf[i][k] + wf[k][j]
                }
            }
        }
    }
    var ans = 0
    for (i in 0 until h) {
        for (j in 0 until w) {
            val v = a[i][j]
            if (v != -1 && v != 1) {
                ans += wf[v][1]
            }
        }
    }
    println(ans)
}

