class Graph(v: Int) {
    private val vec = Array(v + 1) { mutableListOf<E>() }

    fun addEdge(a: Int, b: Int, c: Int = 0) {
        vec[a].add(E(b, c))
    }

    // 負のコストがない場合の起点から全頂点への移動最小コスト
    fun dijkstra(start: Int): IntArray {
        val que = PriorityQueue<E>(11, Comparator { o1, o2 -> o1.c - o2.c })
        que.add(E(start, 0))
        val d = IntArray(vec.size) { 1000000 }
        d[start] = 0
        while (que.isNotEmpty()) {
            val cur = que.poll()
            if (d[cur.v] < cur.c) continue
            for (next in vec[cur.v]) {
                if (d[next.v] > d[cur.v] + next.c) {
                    d[next.v] = d[cur.v] + next.c
                    que.add(next)
                }
            }
        }
        return d
    }

    data class E(val v: Int, val c: Int)
}

