fun main(arg: Array<String>) {
    val (H, W) = listOfInt()
    val C = Array(10) { listOfInt().toIntArray() }
    val A = Array(H) { listOfInt().toIntArray() }
    val INF = 1001001001
    val M = Array(10) { IntArray(10) { INF } }
    fun get(s: Int, v: Int): Int {
        if (M[s][v] == INF) {
            M[s][v] = C[s][v]
            val Q = Queue<Pair<Int, Int>>()
            Q.enqueue(v to 0)
        exit@
            while (!Q.isEmpty()) {
                val q = Q.dequeue()!!
                if (q.first == s)
                    M[s][v] = Math.min(M[s][v], q.second)
                else {
                    var min = INF
                    for (h in 0 .. 9) if (h != q.first && C[h][q.first] < min) min = C[h][q.first]
                    for (h in 0 .. 9) {
                        if (h != q.first && C[h][q.first] == min) {
                            if (q.second + min >= C[s][v]) break@exit
                            Q.enqueue(h to q.second + min)
                        }
                    }
                }
            }
        }
        return M[s][v]
    }
    var ans = 0
    for (h in 0 until H)
        for (w in 0 until W)
            if (A[h][w] != -1 && A[h][w] != 1) {
                ans += get(A[h][w], 1)
            }
    println(ans)
}
class Queue<T> {
    val elements = mutableListOf<T>()
    fun isEmpty() = elements.isEmpty()
    fun enqueue(item: T) = elements.add(item)
    fun dequeue() = if (!isEmpty()) elements.removeAt(0) else null
}
