			for ( int j = 0; j < w; j++ ) {
				turnAry[i][j] = in.nextInt();
			} in.nextLine();
		}

		// Floyd-Warshall algo
		for ( int k = 0; k < 10; k++ ) {
			for ( int i = 0; i < 10; i++ ) {
