            int[] minCost = new int[10];

            for (int i = 0; i < 10; i++) {
                ArrayList<Integer> path = new ArrayList<Integer>();
                for (int j = 0; j < 10; j++) if (j != i) path.add(j);
                minCost[i] = getMinCost(0, Integer.MAX_VALUE, i, path);
            }

