import java.util.Arrays;
import java.util.Scanner;
public class Main {
	static class Edge {
		int from, to, cost;
		public Edge(int from, int to, int cost) {
			this.from = from;
			this.to = to;
			this.cost = cost;
		}
	}
	static int V = 10;
	static int E = 100;
	static Edge[] edges = new Edge[E];
	static int[] d;
	static int INF = Integer.MAX_VALUE / 2;
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int h = Integer.parseInt(sc.next());
		int w = Integer.parseInt(sc.next());
		int k = 0;
		for (int i = 0; i < 10; i++)
			for (int j = 0; j < 10; j++)
				edges[k++] = new Edge(i, j, Integer.parseInt(sc.next()));
		int[] ans = new int[10];
		for (int i = 0; i < 10; i++) {
			bellman_ford(i);
			ans[i] = d[1];
		}
		int sum = 0;
		for (int i = 0; i < h * w; i++) {
			int t = Integer.parseInt(sc.next());
			if (t != -1)
				sum += ans[t];
		}
		System.out.println(sum);
	}
	static void bellman_ford(int sv) {
		d = new int[V];
		Arrays.fill(d, INF);
		d[sv] = 0;
		while (true) {
			boolean update = false;
			for (int i = 0; i < E; i++) {
				int u = edges[i].from;
				int v = edges[i].to;
				int c = edges[i].cost;
				if (d[u] + c < d[v]) {
					d[v] = d[u] + c;
					update = true;
				}
			}
			if (!update) {
				break;
			}
		}
	}
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static void main(final String[] args) {
        final Scanner scanner = new Scanner(System.in);
        final int h = scanner.nextInt();
        final int w = scanner.nextInt();

        final int[][] table = new int[10][10];
        for (int i = 0; i < 10; i++) {
            for (int j = 0; j < 10; j++) {
                table[i][j] = scanner.nextInt();
            }
        }

        final int[] magicPowers = new int[10];
        for (int i = 0; i < 10; i++) {
            if (i == 1) {
                continue;
            }

            final int min = table[i][1];
            magicPowers[i] = search(table, 0, i, min);
        }

        int answer = 0;
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                final int tmp = scanner.nextInt();
                if (tmp != -1) {
                    answer += magicPowers[tmp];
                }
            }
        }

        System.out.println(answer);
    }

    private static int search(final int[][] table, final int magicPower, final int index, final int min) {
        if (index == 1) {
            return magicPower + table[index][1];
        }
        if (magicPower > min) {
            return min;
        }

        int tmp = min;
        for (int i = 0; i < 10; i++) {
            if (i == index) {
                continue;
            }
            tmp = Math.min(tmp, search(table, magicPower + table[index][i], i, min));
        }

        return tmp;
    }
}

