        Scanner sc = new Scanner(System.in);
        long[][][] warshall=new long[10][10][10];
        int h=sc.nextInt();
        int w=sc.nextInt();
        for(int i=0;i<10;i++){
            for(int j=0;j<10;j++){
                warshall[0][i][j]=sc.nextInt();
            }
        }
        for(int i=1;i<10;i++){
            for(int j=0;j<10;j++){
                for(int k=0;k<10;k++){
                    warshall[i][j][k]=Math.min(warshall[i-1][j][k],warshall[i-1][j][i]+warshall[i-1][i][k]);
                }
            }
        }
        long ans=0;
        int tmp;
        for(int i=0;i<h*w;i++){
            tmp=sc.nextInt();
            if(tmp>=0)ans+=warshall[9][tmp][1];
        }
        System.out.println(ans);
    }
}

import java.util.*;

import static java.lang.System.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int H = sc.nextInt();
        int W = sc.nextInt();

        int[][] distances = new int[10][10];
        for (int i = 0; i < 10; i++) {
            for (int j = 0; j < 10; j++) {
                distances[i][j] = sc.nextInt();
            }
        }

        int[] nums = new int[10];
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                int a = sc.nextInt();
                if(a != -1){
                    nums[a]++;
                }
            }
        }

        warshallFloyd(10, distances);

        int ans = 0;
        for(int i = 0; i < 10; i++){
            ans += nums[i] * distances[i][1];
        }

        out.println(ans);
    }

    public static void warshallFloyd(int vertex, int[][] distance) {
        for (int k = 0; k < vertex; k++) {           // 経由する頂点
            for (int i = 0; i < vertex; i++) {        // スタートの頂点
                for (int j = 0; j < vertex; j++) {   // ゴールの頂点
                    if (distance[i][j] > distance[i][k] + distance[k][j]) {
                        distance[i][j] = distance[i][k] + distance[k][j];
                    }
                }
            }
        }
    }
}

