        boolean[] used = new boolean[10];
        int calc(int now, int total) {
        	if(now == 1) return total;
        	int ans = 1000000100;
        	for (int i = 0; i < 10; i++) {
				if(!used[i]) {
					used[i] = true;
					ans = Math.min(ans, calc(i, total + C[now][i]));
					used[i] = false;
				}
			}
        	return ans;
        }
