	public static int dfs(int n,boolean[] flg,int remain,int[][] c ,int sum) {
		if(remain==0) {
			return sum;
		}
		int ans=99999999;
		for(int i=0;i<flg.length;i++) {
			if(i==n) {
				continue;
			}
			if(flg[i]&&i==1) {
				ans=Math.min(ans,sum+c[n][i]);
			}else {
				if(sum+c[n][i] < c[n][1]) {
					flg[i]=false;
					ans=Math.min(ans,dfs(i,flg,remain-1,c,sum+c[n][i]));
					flg[i]=true;
				}
			}
		}
		return ans;
