import java.util.List;
import java.util.NoSuchElementException;
import java.util.PriorityQueue;
import java.util.Queue;

public class Main {

	public static void main(String[] args) {
		FastScanner sc = new FastScanner();
		PrintWriter out = new PrintWriter(System.out);

		int h = sc.nextInt();
		int w = sc.nextInt();

		List<List<Edge>> edges = new ArrayList<>();
		for (int i = 0; i < 10; i++) {
			edges.add(new ArrayList<>());
		}

		for (int i = 0; i < 10; i++) {
			for (int j = 0; j < 10; j++) {
				int c = sc.nextInt();
				edges.get(i).add(new Edge(i, j, c));
			}
		}

		int[][] dist = new int[10][];
		for (int i = 0; i < 10; i++) {
			dist[i] = dijkstra(10, edges, i);
		}

		int cost = 0;
		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				int a = sc.nextInt();
				if (a < 0) continue;
				cost += dist[a][1];
			}
		}

		out.println(cost);
		out.flush();
	}

	static int[] dijkstra(int n, List<List<Edge>> edges, int s) {
		int[] dist = new int[n];
		Arrays.fill(dist, Integer.MAX_VALUE);
		dist[s] = 0;

		Queue<Edge> q = new PriorityQueue<Edge>();
		q.add(new Edge(s, s, 0));

		while (!q.isEmpty()) {
			Edge edge = q.poll();
			if (dist[edge.tgt] < edge.cost) {
				continue;
			}
			for (Edge e : edges.get(edge.tgt)) {
				if (dist[e.tgt] > dist[edge.tgt] + e.cost) {
					dist[e.tgt] = dist[edge.tgt] + e.cost;
					q.add(new Edge(edge.tgt, e.tgt, dist[e.tgt]));
				}
			}
		}

		return dist;
	}

	static class Edge implements Comparable<Edge> {
		int src, tgt, cost;

		Edge(int src, int tgt, int cost) {
			this.src = src;
			this.tgt = tgt;
			this.cost = cost;
		}

		@Override
		public int compareTo(Edge e) {
			return this.cost - e.cost;
		}
	}

}

