public static int dijkstra(int s)
{
	int inf=100000000;
	int []dist=new int[10];
	Arrays.fill(dist, inf);
	dist[s]=0;
	PriorityQueue<edge> pq=new PriorityQueue();
	pq.add(new edge(s,0));
	while(!pq.isEmpty())
	{
		edge e=pq.poll();
		int from=e.to;
		int w=e.weight;
		if(from==1)
			return w;
		if(dist[from]<w)
			continue;
		for(edge curr:adj[from])
		{
			int total=w+curr.weight;
			if(total<dist[curr.to])
			{
				dist[curr.to]=total;
				pq.add(new edge(curr.to,total));
			}
		}
	}
	return -1;

}
