import java.io.IOException;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

public class Main {

	public static void main(String[] args) throws IOException {

		Scanner in = new Scanner(System.in);
		int h = in.nextInt();
		int w = in.nextInt();

		int u = 10;
		int[][] mat = new int[u][u];
		for (int i = 0; i < u; i++) {
			Arrays.fill(mat[i], -1);
		}
		for (int i = 0; i < u; i++) {
			for (int j = 0; j < u; j++) {
				mat[i][j] = in.nextInt();
			}
		}
		int[] wall = new int[h*w];
		for (int i = 0; i < h*w; i++) {
			wall[i] = in.nextInt();
		}

		// solve
		int[] transCost = new int[10];

		for (int fromNode = 0; fromNode < 10; fromNode++) {
			if (fromNode == 1) {
				continue;
			}
			Set<Integer> x = new HashSet<>();
			Set<Integer> y = new HashSet<>();
			boolean[] visit = new boolean[u];
			for (int i = 0; i < u; i++) {
				if (fromNode == i) {
					continue;
				}
				y.add(i);
			}
			int[] nodeCost = new int[u];
			Arrays.fill(nodeCost, Integer.MAX_VALUE);
			x.add(fromNode);
			nodeCost[fromNode] = 0;
			visit[fromNode] = true;

			while (!y.isEmpty()) {
				int min = Integer.MAX_VALUE;
				int v = -1;
				for (int from : x) {
					for (int to = 0; to < u; to++) {
						int visitCost = mat[from][to] + nodeCost[from];
						// toのノードが最小コストで訪問済でない場合
						if (mat[from][to] != -1 && !visit[to] && visitCost <= nodeCost[to]) {
							nodeCost[to] = visitCost;
							if (nodeCost[to] < min) {
								min = nodeCost[to];
								v = to;
							}
						}
					}
				}
				x.add(v);
				y.remove(v);
				visit[v] = true;
			}
			transCost[fromNode] = nodeCost[1];
		}

		int ans = 0;
		for (int wa : wall) {
			if (wa == -1 || wa == 1) {
				continue;
			}
			ans += transCost[wa];
		}
		System.out.println(ans);
	}
}

import java.util.Scanner;

class Main {

    static int[][] cost = new int[10][10];

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int height = sc.nextInt(), width = sc.nextInt();
        int[][] num = new int[height][width];
        for (int i = 0; i < 10; i++) {
            for (int j = 0; j < 10; j++) {
                cost[i][j] = sc.nextInt();
            }
        }
        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                num[i][j] = sc.nextInt();
            }
        }

        long actual[] = new long[10];

        long sum = 0;
        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                if (num[i][j] == 1 || num[i][j] == -1) {
                    continue;
                } else if (actual[num[i][j]] != 0) {
                    sum += actual[num[i][j]];
                } else {
                    boolean[] visit = new boolean[10];
                    actual[num[i][j]] = search(num[i][j], 0, visit, cost[num[i][j]][1]);
                    sum += actual[num[i][j]];
                }
            }
        }
        System.out.println(sum);
    }

    private static long search(int num, long sum, boolean[] v, long direct) {
        boolean[] visit = new boolean[10];
        for (int i = 0; i < 10; i++) {
            visit[i] = v[i];
        }
        visit[num] = true;
        if (num == 1 || sum >= direct) {
            return sum;
        }
        long min = direct;
        for (int i = 0; i < 10; i++) {
            if (visit[i]) {
                continue;
            }
            long c = search(i, sum + cost[num][i], visit, direct);
            if (c < min) {
                min = c;
            }
        }
        return min;
    }
}

