			return sum;
		}
		int ans=99999999;
		for(int i=0;i<flg.length;i++) {
			if(flg[i]) {
				if(i==1) {
					ans=Math.min(ans,sum+c[n][i]);
				}else {
					if(sum+c[n][i] < c[n][1]) {
