	static int[][] allPairsShortest(int[][] graph){
		int n = graph[0].length;
		int[][] dist = new int[n][n];

		for(int u = 0; u < n; u++){
			Arrays.fill(dist[u], Integer.MAX_VALUE);
			dist[u][u] = 0;

			for(int v = 0; v < n; v++){
				if(u != v){
					dist[u][v] = graph[u][v];
				}
			}
		}

		for(int k = 0; k < n; k++){
			for(int i = 0; i < n; i++){
				if(dist[i][k] == Integer.MAX_VALUE){
					continue;
				}

				for(int j = 0; j < n; j++){
					long newLen = dist[i][k];
					newLen += dist[k][j];

					if(newLen < dist[i][j]){
						dist[i][j] = (int)newLen;
					}
				}
			}
		}

		return dist;
	}

	static int[] singleSourceShortestDense(int[][] matrix, int s){
        int n = matrix[0].length;
        int[] dist = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        boolean[] visited = new boolean[n];
        Arrays.fill(visited, false);

        dist[s] = 0;

        while(true){

            int u = -1;
            int sd = Integer.MAX_VALUE;

            for(int i = 0; i < n ; i++){
                if(!visited[i] && dist[i] < sd){
                    sd = dist[i];
                    u = i;
                }
            }

            if(u == -1){
                break;
            }

            visited[u] = true;
            for(int v = 0; v < n ; v++){
                int w = matrix[u][v];
                if(v == u) continue;

                long newLen = dist[u];
                newLen += w;
                if(newLen < dist[v]){
                    dist[v] = (int)newLen;
                }
            }

        }

        return dist;
    }

}

