public class Main{
	public static void main(String[] args) {
		FastScanner sc = new FastScanner();
		int h = sc.nextInt();
		int w = sc.nextInt();
		int[][] c = new int[10][10];
		for (int i = 0; i < 10; i++) {
			for (int j = 0; j < 10; j++) {
				c[i][j] = sc.nextInt();
			}
		}
		int[][] a = new int[h][w];
		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				a[i][j] = sc.nextInt();
			}
		}
		int[] dis = new int[10];
		for (int i = 0; i < 10; i++) {
			PriorityQueue<Node> queue = new PriorityQueue<>(Comparator.comparingInt(node -> node.cost));
			Node[] nodes = new Node[10];
			for (int j = 0; j < 10; j++) {
				nodes[j] = new Node(j);
			}
			nodes[i].cost = 0;
			queue.addAll(Arrays.asList(nodes).subList(0, 10));
			while (!queue.isEmpty()) {
				Node d = queue.poll();
				d.done = true;
				for (int j = 0; j < 10; j++) {
					if (nodes[j].done) {
						continue;
					}
					int tmp = d.cost + c[d.num][j];
					if (tmp < nodes[j].cost) {
						nodes[j].cost = tmp;
						queue.remove(nodes[j]);
						queue.add(nodes[j]);
					}
				}
			}
			dis[i] = nodes[1].cost;
		}

		long ans = 0;
		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				if (a[i][j] == -1) {
					continue;
				}
				ans += dis[a[i][j]];
			}
		}
		System.out.println(ans);
	}
}

