	class WarshallFloyd {

		private final long INF = Long.MAX_VALUE / 3;
		private long[][] d;
		private int V;

		/**
		 * 初期化
		 *
		 * @param n 頂点の数
		 */
		public WarshallFloyd(int n) {
			this.d = new long[n][n];
			for (long[] ls : this.d) {
				Arrays.fill(ls, this.INF);
			}
			this.V = n;
		}

		public void set(int from, int to, long cost) {
			this.d[from][to] = cost;
		}

		/**
		 * すべての2頂点間の最短距離を計算する O(|V|^3)
		 */
		public void calc() {
			for (int k = 0; k < this.V; k++) {
				for (int i = 0; i < this.V; i++) {
					for (int j = 0; j < this.V; j++) {
						this.d[i][j] = Math.min(this.d[i][j], this.d[i][k] + this.d[k][j]);
					}
				}
			}
		}

		/**
		 * 全ての配列を返却
		 * @return d
		 */
		public long[][] getd() {
			return this.d;
		}

		/**
		 * fromからtoまでの最短距離を返す O(1).<br>
		 * 経路が存在しない場合はINF(Long.MAX_VALUE / 3)を返す
		 *
		 * @param from
		 * @param to
		 * @return fromからtoまでの最短距離
		 */
		public long distance(int from, int to) {
			return this.d[from][to];
		}

	}

	class Exm implements Comparable<Exm> {

		public int a;
		public int b;

		public Exm(int a, int b) {
			this.a = a;
			this.b = b;
		}

		@Override
		public int compareTo(Exm o) {

			//return this.a - o.a;//昇順
			// return o.a - this.a;//降順

			//複数項目で並び替え。aの降順、aが同じならbの降順
			if (this.a == o.a) {
				return o.b - this.b;
			} else {
				return o.a - this.a;
			}
		}
	}

	/**
	 *
	 * @param n
	 * @param m
	 * @return Combinationの数を返す(mod無しなので、大きい値には使用できない桁溢れする)
	 */
	long calcCombination(int n, int m) {
		if (n < m || m < 0) {
			throw new IllegalArgumentException("引数の値が不正です ( n : " + n + ", m : " + m + ")");
		}
		long c = 1;
		m = (n - m < m ? n - m : m);
		for (int ns = n - m + 1, ms = 1; ms <= m; ns++, ms++) {
			c *= ns;
			c /= ms;
		}
		return c;
	}

	/*
	 * 使用するときはModに注意。Global変数を参照
	 */
	public static long comb(long a, long b) {
		if (a < b)
			return 0;
		long res = 1;
		long inv = pow(fact(Math.min(b, a - b)), mod - 2);
		for (long i = a; i > a - Math.min(b, a - b); i--) {
			res *= i;
			res %= mod;
		}
		res *= inv;
		res %= mod;
		return res;
	}

	public static long pow(long x, long n) {
		long res = 1;
		while (n > 0) {
			if ((n & 1) == 1) {
				res *= x;
				res %= mod;
			}
			x *= x;
			x %= mod;
			n >>= 1;
		}
		return res;
	}

	public static long fact(long n) {
		long res = 1;
		while (n > 0) {
			res *= n;
			res %= mod;
			n--;
		}
		return res;
	}

