	private int solveSub(int cost, int i, int j, int def, int[] matrix, int check) {
		int ret = def;
		if(i==j){
			ret = cost;
		}else{
			for(int n=0; n<10; n++) {
				if((check & (1<<n)) > 0){
					continue;
				}else if(cost + matrix[i*10+n] < ret){
					ret = Math.min(ret, solveSub(cost + matrix[i*10+n],n,j,ret,matrix,(check|(1<<n))));
				}else{
					continue;
				}
			}
		}
		return ret;
	}



