    static class InputReader {

        private InputStream in;
        private byte[] buffer = new byte[1024];
        private int curbuf;
        private int lenbuf;

        public InputReader(InputStream in) {
            this.in = in;
            this.curbuf = this.lenbuf = 0;
        }

        public boolean hasNextByte() {
            if (this.curbuf >= this.lenbuf) {
                this.curbuf = 0;
                try {
                    this.lenbuf = this.in.read(this.buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (this.lenbuf <= 0) {
                    return false;
                }
            }
            return true;
        }

        private int readByte() {
            if (this.hasNextByte()) {
                return this.buffer[this.curbuf++];
            } else {
                return -1;
            }
        }

        private boolean isSpaceChar(int c) {
            return !(c >= 33 && c <= 126);
        }

        private void skip() {
            while (this.hasNextByte() && this.isSpaceChar(this.buffer[this.curbuf])) {
                this.curbuf++;
            }
        }

        public boolean hasNext() {
            this.skip();
            return this.hasNextByte();
        }

        public String next() {
            if (!this.hasNext()) {
                throw new NoSuchElementException();
            }
            StringBuilder sb = new StringBuilder();
            int b = this.readByte();
            while (!this.isSpaceChar(b)) {
                sb.appendCodePoint(b);
                b = this.readByte();
            }
            return sb.toString();
        }

        public int nextInt() {
            if (!this.hasNext()) {
                throw new NoSuchElementException();
            }
            int c = this.readByte();
            while (this.isSpaceChar(c)) {
                c = this.readByte();
            }
            boolean minus = false;
            if (c == '-') {
                minus = true;
                c = this.readByte();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res = res * 10 + c - '0';
                c = this.readByte();
            } while (!this.isSpaceChar(c));
            return minus ? -res : res;
        }

        public long nextLong() {
            if (!this.hasNext()) {
                throw new NoSuchElementException();
            }
            int c = this.readByte();
            while (this.isSpaceChar(c)) {
                c = this.readByte();
            }
            boolean minus = false;
            if (c == '-') {
                minus = true;
                c = this.readByte();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res = res * 10 + c - '0';
                c = this.readByte();
            } while (!this.isSpaceChar(c));
            return minus ? -res : res;
        }

        public double nextDouble() {
            return Double.parseDouble(this.next());
        }

        public int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = this.nextInt();
            }
            return a;
        }

        public long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++) {
                a[i] = this.nextLong();
            }
            return a;
        }

        public char[][] nextCharMap(int n, int m) {
            char[][] map = new char[n][m];
            for (int i = 0; i < n; i++) {
                map[i] = this.next().toCharArray();
            }
            return map;
        }
    }
}

import java.util.*;
import java.io.*;
import java.nio.charset.StandardCharsets;

public class Main {
	static class Tuple implements Comparable<Tuple> {
		int src, dst, cost;

		Tuple(int src, int dst, int cost) {
			this.src = src;
			this.dst = dst;
			this.cost = cost;
		}

		@Override
		public int compareTo(Tuple o) {
			return Integer.compare(this.cost, o.cost);
		}
	}

	public static void main(String[] args) throws IOException {
		InputStreamReader reader = new InputStreamReader(System.in, StandardCharsets.UTF_8);
		BufferedReader in = new BufferedReader(reader);
		String[] tokens = in.readLine().split(" ");
		int H = Integer.parseInt(tokens[0]);
		int W = Integer.parseInt(tokens[1]);
		Tuple[][] cost = new Tuple[10][10];
		for (int i = 0; i < 10; ++i) {
			tokens = in.readLine().split(" ");
			for (int j = 0; j < 10; ++j) {
				cost[i][j] = new Tuple(i, j, Integer.parseInt(tokens[j]));
			}
		}
		int[][] distMatrix = new int[10][10];
		for (int i = 0; i < 10; ++i) {
			Arrays.fill(distMatrix[i], Integer.MAX_VALUE / 2);
			distMatrix[i][i] = 0;
		}

		// 対角成分以外をqueueに入れる
		Queue<Tuple> que = new PriorityQueue<>();
		for (int i = 0; i < 10; ++i) {
			for (int j = 0; j < 10; ++j) {
				if (i == j)
					continue;
				que.add(cost[i][j]);
			}
		}

		// 順に評価する
		while (!que.isEmpty()) {
			Tuple tuple = que.poll();
			// まず直接つなぐ部分を評価
			if (distMatrix[tuple.src][tuple.dst] > tuple.cost) {
				distMatrix[tuple.src][tuple.dst] = tuple.cost;
			}
			// 次に経由する部分を評価
			for (int src = 0; src < 10; ++src) {
				if (tuple.src == src || tuple.dst == src) {
					continue;
				}
				if (distMatrix[src][tuple.src] + tuple.cost < distMatrix[src][tuple.dst]) {
					distMatrix[src][tuple.dst] = distMatrix[src][tuple.src] + tuple.cost;
				}
			}
			for (int dst = 0; dst < 10; ++dst) {
				if (tuple.src == dst || tuple.dst == dst) {
					continue;
				}
				if (tuple.cost + distMatrix[tuple.dst][dst] < distMatrix[tuple.src][dst]) {
					distMatrix[tuple.src][dst] = tuple.cost + distMatrix[tuple.dst][dst];
				}
			}
		}

		// これをもとに置き換える
		int[][] A = new int[H][W];
		for (int i = 0; i < H; ++i) {
			tokens = in.readLine().split(" ");
			for (int j = 0; j < W; ++j) {
				A[i][j] = Integer.parseInt(tokens[j]);
			}
		}
		int result = 0;
		for (int i = 0; i < H; ++i) {
			for (int j = 0; j < W; ++j) {
				if (A[i][j] <= 1) {
					continue;
				}
				result += distMatrix[A[i][j]][1];
			}
		}
		System.out.println(result);
	}

}

