class Solver {
    Scanner sc = new Scanner();

    public void Solve() {
        int H = sc.nextInt();
        int W = sc.nextInt();
        c = new int[10, 10];
        var A = new int[H, W];
        for (int i = 0; i < 10; i++) {
            for (int j = 0; j < 10; j++) {
                c[i, j] = sc.nextInt();
            }
        }
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                A[i, j] = sc.nextInt();
            }
        }

        var cost = new int[10];
        for (int i = 0; i < 10; i++) {
            if (i == 1) {
                cost[i] = 0;
                continue;
            }

            minCost = int.MaxValue;
            var dist = new bool[10];
            Sub(i, 0, dist);
            cost[i] = minCost;
        }

        long ans = 0;
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                if (A[i, j] == -1) continue;
                ans += cost[A[i, j]];
            }
        }
        WriteLine(ans);
    }

    int[,] c;
    int minCost;

    void Sub(int i, int cost, bool[] distBase) {
        var dist = new bool[10];
        Array.Copy(distBase, dist, 10);
        dist[i] = true;

        for (int j = 0; j < 10; j++) {
            if (j == i || dist[j]) continue;

            if (j == 1) {
                minCost = Math.Min(cost + c[i, 1], minCost);
            } else {
                Sub(j, cost + c[i, j], dist);
            }
        }
    }

}



