        {
            s = Console.ReadLine().Split(' ');
            for (int j = 0; j < W; j++)
            {
                wall[i, j] = int.Parse(s[j]);
            }
        }

        int power = 0;
        int p_box = 0;
        int p_pos = 0;
        int rim = 0;

        int[] box = new int[10];
        for (int i = 0; i < 10; i++) box[i] = 0;
        int b = 0;
        int min = 0;

        for (int i = 0; i < N; i++)
        {
            for (int j = 0; j < W; j++)
            {
                if (wall[i, j] == 1 || wall[i, j] == -1) continue;
                if (box[wall[i, j]] != 0)
                {
                    //Console.WriteLine(wall[i, j] + "を呼び出し");
                    power += box[wall[i, j]];
                    continue;
                }
                else
                {
                    //Console.WriteLine(wall[i, j] + "を記録");
                    b = wall[i, j];
                    p_box = 0;
                    rim = c[wall[i, j], 1];
                    while (true)
                    {
                        min = 10;
                        for (int k = 0; k < 10; k++)
                        {
                            if (min > c[wall[i, j], k] && wall[i, j] != k) { min = c[wall[i, j], k]; p_pos = k; }
                        }
                        p_box += c[wall[i, j], p_pos];
                        wall[i, j] = p_pos;
                        if (rim < p_box) { p_box = rim + 1; break; }
                        if (wall[i, j] == 1) break;
                    }
                    if (rim > p_box) { power += p_box; box[b] = p_box; }
                    else { power += rim; box[b] = rim; }
                }
            }
        }
        Console.WriteLine(power);
