    {
        static void Solve(Input input)
        {
            var h = input.NextInt();
            var w = input.NextInt();
            var wf = new WarshallFloyd(10);

            for (int i = 0; i <= 9; i++)
            {
                for (int j = 0; j <= 9; j++)
                {
                    // iからjへのコスト
                    wf.AddPath(i, j, input.NextInt());
                }
            }

            var sp = wf.ShortestPath();
            var cost = 0;
            for (int i = 0; i < h; i++)
            {
                for (int j = 0; j < w; j++)
                {
                    var from = input.NextInt();
                    if (from < 0) continue;

                    cost += sp[from, 1];
                }
            }

            Console.WriteLine(cost);
        }

        /// <summary>
        /// 重み付き・有向グラフの全ノード間最短経路
        /// </summary>
        class WarshallFloyd
        {
            static readonly int INF = int.MaxValue / 5;

            // 接続情報
            int[,] es;
            // ノード数
            int V;

            /// <summary>
            /// 
            /// </summary>
            /// <param name="v">ノード数</param>
            public WarshallFloyd(int v)
            {
                es = new int[v, v];
                for (int i = 0; i < v; i++)
                {
                    for (int j = 0; j < v; j++)
                    {
                        es[i, j] = (i == j) ? 0 : INF;
                    }
                }

                V = v;
            }

            /// <summary>
            /// 経路追加
            /// </summary>
            /// <param name="from"></param>
            /// <param name="to"></param>
            /// <param name="cost"></param>
            public void AddPath(int from, int to, int cost)
                => es[from, to] = cost;

            /// <summary>
            /// 各ノードへの最短経路
            /// </summary>
            /// <param name="s"></param>
            /// <returns>nullなら負経路がある</returns>
            public int[,] ShortestPath()
            {
                var d = new int[V, V];
                Array.Copy(es, d, d.Length);

                for (int i = 0; i < V; i++)
                {
                    for (int j = 0; j < V; j++)
                    {
                        for (int k = 0; k < V; k++)
                        {
                            d[j, k] = Math.Min(d[j, k], d[j, i] + d[i, k]);
                        }
                    }
                }

                return d;
            }
        }

        #region Competitive Template
        static readonly int MOD = (int)1e9 + 7;

        public static void Main(string[] args)
        {
            // 出力が少ないときはこれをセットする方が時間かかるけれど
            // その場合は出力がボトルネックになっていないので、まあ良しとする
