    {
        var H = sc.ReadInt();
        var W = sc.ReadInt();
        var wf = new WarshallFloyd(10);
        for (int i = 0; i < 10; i++)
        {
            for (int j = 0; j < 10; j++)
            {
                var c = sc.ReadInt();
                wf.SetCost(i, j, c);
            }
        }
        wf.CalcMinCost();
        var ans = 0L;
        for (int i = 0; i < H; i++)
        {
            for (int j = 0; j < W; j++)
            {
                var a = sc.ReadInt();
                if (a == -1) continue;
                ans += wf.GetMinCost(a, 1);
            }
        }
        Console.WriteLine(ans);
    }

    class WarshallFloyd
    {
        public int V { get; set; }
        public long[,] DP { get; set; }
        public long INF = long.MaxValue;
        public bool[] Negative;
        public WarshallFloyd(int v)
        {
            this.V = v;
            this.DP = new long[V, V];
            for (int i = 0; i < V; i++)
            {
                for (int j = 0; j < V; j++)
                {
                    this.DP[i, j] = INF;
                }
                this.DP[i, i] = 0;
            }
        }
        public void SetCost(int a, int b, int c = 1)
        {
            this.DP[a, b] = c;
        }
        public void CalcMinCost()
        {
            this.Negative = new bool[V];
            for (int k = 0; k < V; k++)
            {
                for (int i = 0; i < V; i++)
                {
                    for (int j = 0; j < V; j++)
                    {
                        if (DP[i, k] == INF || DP[k, j] == INF) continue;
                        DP[i, j] = Math.Min(DP[i, j], DP[i, k] + DP[k, j]);
                    }
                }
            }
            for (int k = 0; k < V; k++)
            {
                for (int i = 0; i < V; i++)
                {
                    for (int j = 0; j < V; j++)
                    {
                        if (DP[i, k] == INF || DP[k, j] == INF) continue;
                        if (DP[i, j] > DP[i, k] + DP[k, j])
                        {
                            this.Negative[i] = true;
                            this.Negative[j] = true;
                            this.Negative[k] = true;
                        }
                    }
                }
            }
        }
        public long GetMinCost(int a, int b)
        {
            return DP[a, b];
        }
        public bool IsINF(int a, int b)
        {
            return DP[a, b] >= INF;
        }
        public bool IsNegative(params int[] vs)
        {
            if (vs.Length == 0) vs = Enumerable.Range(0, V).ToArray();
            foreach (var v in vs)
            {
                if (Negative[v]) return true;
            }
            return false;
        }
    }
    static Scanner sc = new Scanner();
}

