      public static bool IsPrime(long x)
      {
        var fact = Factorize(x);
        return fact.Count == 1 && fact.Values.ElementAt(0) == 1;
      }
      public static Dictionary<long, int> Factorize(long x)
      {
        var dict = new Dictionary<long, int>();
        long minp = 2;
        while (x > 1)
        {
          bool ok = false;
          for (long p = minp; p * p <= x; ++p)
          {
            if (x % p == 0)
            {
              if (!dict.ContainsKey(p))
              {
                dict.Add(p, 0);
              }
              dict[p]++;
              minp = p;
              x /= p;
              ok = true;
              break;
            }
          }
          if (!ok)
          {
            if (!dict.ContainsKey(x)) { dict.Add(x, 0); }
            dict[x]++;
            break;
          }
        }
        return dict;
      }
      public static HashSet<int> GenPrimes(int max)
      {
        var primes = new HashSet<int>(Enumerable.Range(2, max - 1));
        for(int i = 2; i <= max; ++i)
        {
          if (primes.Contains(i))
          {
            for(int j=2; ; ++j)
            {
              if (i * j > max) { break; }
              primes.Remove(i * j);
            }
          }
        }
        return primes;
      }
      public static T[,] Transpose<T>(T[,] matrix)
      {
        var r = matrix.GetLength(0);
        var c = matrix.GetLength(1);
        var matrixOut = new T[c, r];
        for (int i = 0; i < r; ++i)
        {
          for (int j = 0; j < c; ++j)
          {
            matrixOut[j, i] = matrix[i, j];
          }
        }
        return matrixOut;
      }

      public class PriorityQueue<T> where T : IComparable
      {
        private IComparer<T> _comparer = null; private bool _isAsc = true; private T[] _heap; private int _sz = 0;
        public PriorityQueue(int maxSize, IComparer<T> comparer) { _heap = new T[maxSize]; _comparer = comparer; }
        public PriorityQueue(int maxSize, bool isAsc = true) { _heap = new T[maxSize]; _isAsc = isAsc; }
        private int Compare(T x, T y) { if (_comparer != null) { return _comparer.Compare(x, y); } return _isAsc ? x.CompareTo(y) : y.CompareTo(x); }
        public void Push(T x) { var i = _sz++; while (i > 0) { var p = (i - 1) / 2; if (Compare(_heap[p], x) <= 0) { break; } _heap[i] = _heap[p]; i = p; } _heap[i] = x; }
        public T Pop() { T ret = _heap[0]; T x = _heap[--_sz]; int i = 0; while (i * 2 + 1 < _sz) { int a = i * 2 + 1; int b = i * 2 + 2; if (b < _sz && Compare(_heap[b], _heap[a]) < 0) { a = b; } if (Compare(_heap[a], x) >= 0) { break; } _heap[i] = _heap[a]; i = a; } _heap[i] = x; return ret; }
        public int Count() { return _sz; }
        public T Peek() { return _heap[0]; }
        public bool Contains(T x) { for (int i = 0; i < _sz; i++) if (x.Equals(_heap[i])) return true; return false; }
      }
      public class MyTuple<T1, T2> : IComparable where T1 : IComparable<T1>
      {
        public readonly T1 Item1; public readonly T2 Item2;
        public MyTuple(T1 item1, T2 item2) { Item1 = item1; Item2 = item2; }
        public int CompareTo(object obj) { return Item1.CompareTo(((MyTuple<T1, T2>)obj).Item1); }
      }
      public static long[] DijkstraDense(long[,] adj, int N, int start)
      {
        long INF = (long)1e18;
        var dist = Enumerable.Range(0, N + 1).Select(i => INF).ToArray();
        var queue = new PriorityQueue<MyTuple<long, int>>(N + N * N + 100);
        dist[start] = 0;
        queue.Push(new MyTuple<long, int>(0, start));
        while (queue.Count() > 0)
        {
          var kvp = queue.Pop();
          var d = kvp.Item1; var v = kvp.Item2;
          if (dist[v] < d) { continue; }
          for (int i = 0; i < N; ++i)
          {
            if (i == v) { continue; }
            var newV = i;
            var newD = dist[v] + adj[v, i];
            if (newD < dist[newV])
            {
              dist[newV] = newD;
              queue.Push(new MyTuple<long, int>(newD, newV));
            }
          }
        }
        return dist;
      }
    }

