    /// <summary>
    /// ワーシャルフロイド、負の辺に対応、O(V^3)、全頂点間距離
    /// </summary>
    static class WarshallFloyd
    {
        static int INF = int.MaxValue;

        static int _v;
        static int _e;
        static int[,] dp;

        static public void Init(int V, int E, int[,] Edge)
        {
            _v = V; _e = E;

            dp = new int[V, V];
            for (int i = 0; i < V; i++)
            {
                for (int j = 0; j < V; j++)
                {
                    if (i != j) dp[i, j] = INF;
                    if (Edge[i, j] != 0) dp[i, j] = Edge[i, j];
                }
            }
        }

        static public int[,] Start(out bool negativeCycle)
        {
            negativeCycle = false;
            for (int k = 0; k < _v; k++)
            {
                for (int i = 0; i < _v; i++)
                {
                    for (int j = 0; j < _v; j++)
                    {
                        if (dp[i, k] == int.MaxValue || dp[k, j] == int.MaxValue) continue;
                        dp[i, j] = Math.Min(dp[i, j], dp[i, k] + dp[k, j]);
                    }

                    if (dp[i, i] < 0) negativeCycle = true;
                }
            }

            return dp;
        }
    }
