public class Atcoder
{
    public static void Swap<T>(ref T a, ref T b)
    {
        var t = a;
        a = b;
        b = t;
    }
    public static long LCM(long a, long b)
    {
        long c = a * b;
        if (a < b) Swap(ref a, ref b);
        long d = a % b;
        while (d != 0)
        {
            a = b;
            b = d;
            d = a % b;
        }
        return c / b;
    }
    public static long GCD(long a, long b)
    {
        if (a < b) Swap(ref a, ref b);
        long d = a % b;
        while (d != 0)
        {
            a = b;
            b = d;
            d = a % b;
        }
        return b;
    }
    public static string StrReverce(string s)
    {
        return new string(s.Reverse().ToArray());
    }
    public static bool IsPrime(int n)
    {
        if (n < 2) return false;
        if (n == 2) return true;
        if (n % 2 == 0) return false;

        //double sqrtNum = Math.Sqrt(n);
        for (int i = 3; i < n; i += 2)
        {
            if (n % i == 0) return false;
        }
        return true;
    }
    public static string[] SpRead(char c)
    {
        return Console.ReadLine().Split(c);
    }
    public static string ToConvertBit(int N, int e)
    {
        string ret = "";
        int r = 0;
        while (N != 0)
        {
            r = N % e;
            ret += r.ToString();
            N -= r;
            N /= e;
        }
        ret = StrReverce(ret);
        return ret;
    }
    public static int IntRead()
    {
        return int.Parse(Console.ReadLine());
    }
    public static long LongRead()
    {
        return long.Parse(Console.ReadLine());
    }
    public static long[] LongLine()
    {
        return Console.ReadLine().Split(' ').Select(long.Parse).ToArray();
    }
    public static int[] IntLine()
    {
        return Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace AtCoder2 {
	class Program {
		static void Main(string[] args) {
			var inputArray = retreiveLongArray();
			var inputCount = 2;

			// 不正な入力は処理しない
			if (inputArray.Length != inputCount) {
				Console.WriteLine("invalid input");
				return;
			}
			long H = inputArray[0];
			long W = inputArray[1];

			_maryokuInfo = new List<long[]>();

			for (int i = 0; i <= 9; i++) {
				var inparr = retreiveLongArray();
				_maryokuInfo.Add(inparr);
			}
			//各数字を変えるのに必要な魔力を求める

			var changeMaryoku = new Dictionary<long, long>();

			for (int i = 0; i <= 9; i++) {

				if (i == 1) {
					continue;
				}
				var usedNum = new Dictionary<long, bool>();
				for (int j = 0; j <= 9; j++) {
					usedNum.Add(j, false);
				}
				usedNum[i] = true;
				usedNum[1] = true;

				_minMaryoku = int.MaxValue;
				DFS(i,0, usedNum);

				changeMaryoku.Add(i, _minMaryoku);
			}

			var wallCount = new Dictionary<int, long>();
			for (int j = 0; j <= 9; j++) {

				if (j == 1) {
					continue;
				}
				wallCount.Add(j, 0);
			}

			//登場回数を数える
			for (int i = 0; i < H; i++) {
				var line = retreiveLongArray();

				for (int j = 0; j < W; j++) {
					//-1と1意外の数を数える
					int num = (int)line[j];
					if (num != -1 && num != 1) {
						wallCount[num]++;
					}
				}
			}

			//最小魔力の計算
			long needMaryoku = 0;
			for (int i = 0; i <= 9; i++) {

				if (i == 1) {
					continue;
				}
				needMaryoku += wallCount[i] * changeMaryoku[i];
			}

			Console.WriteLine(needMaryoku);

		}

		/// <summary>
		/// DFSでiから1にするための魔力を求める
		/// </summary>
		/// <param name="currentNum"></param>
		/// <param name="maryokuTotal"></param>
		/// <param name="usedNum"></param>
		private static void DFS(int currentNum, long maryokuTotal, Dictionary<long, bool> usedNum) {
			//1にするために必要な魔力
			var maryokuFor1 = _maryokuInfo[currentNum][1];

			if(_minMaryoku > (maryokuTotal + maryokuFor1)) {
				_minMaryoku = maryokuTotal + maryokuFor1;
			}

			usedNum[currentNum] = true;
			for (int i = 0; i <= 9; i++) {
				if (!usedNum[i]) {
					var maryoku = _maryokuInfo[currentNum][i];
					//次の数値にするための魔力が、1にするための魔力を上回っている場合、可能性なし
					if(maryoku >= maryokuFor1) {
						continue;
					}
					DFS(i, maryokuTotal + maryoku, usedNum);
				}
			}
			usedNum[currentNum] = false;
			return;
		}


		//その数字を1にするのに必要な最小魔力
		private static long _minMaryoku;

		//数字を変えるために必要な魔力の情報
		private static List<long[]> _maryokuInfo;

		/// <summary>
		/// スペースで区切られた文字列配列の入力を受け取る
		/// </summary>
		/// <returns></returns>
		private static string[] retreiveStringArray() {
			var inputArray = Console.ReadLine().Split(' ');
			return inputArray;
		}

		/// <summary>
		/// スペースで区切られた整数配列の入力を受け取る
		/// </summary>
		/// <returns></returns>
		private static long[] retreiveLongArray() {
			var inputArray = Console.ReadLine().Split(' ');
			var longArray = inputArray.Select(s => long.Parse(s));
			return longArray.ToArray();
		}
	}
}

