using System;
namespace kozaiyApp
{
    public class DWall
    {
        static void Main()
        {
            string[] input = Console.ReadLine().Split(' ');
            int H = int.Parse(input[0]);
            int W = int.Parse(input[1]);
            int V = 10; // 頂点の数

            int[,] c = new int[V, V]; // 魔力テーブル これが隣接行列
            for (int i = 0; i < V; i++)
            {
                string[] inputC = Console.ReadLine().Split(' ');
                for (int j = 0; j < V; j++)
                {
                    c[i, j] = int.Parse(inputC[j]);
                }
            }

            // ワーシャルフロイド法
            for (int k = 0; k < V; k++)
            {
                for (int i = 0; i < V; i++)
                {
                    for (int j = 0; j < V; j++)
                    {
                        c[i, j] = Math.Min(c[i, j], c[i, k] + c[k, j]);
                    }
                }
            }

            int ans = 0;
            for (int i = 0; i < H; i++)
            {
                string[] inputA = Console.ReadLine().Split(' ');
                for (int j = 0; j < W; j++)
                {
                    int A = int.Parse(inputA[j]);
                    if (A == -1 || A == 1) continue;
                    ans += c[A, 1]; // A -> 1　の最短経路コストはc[A, 1]
                }
            }
            Console.WriteLine(ans);
        }
    }
}

