        public static void Main(string[] _) { using (new SetConsole()) { Solve(); } }
        public static void Solve()
        {
            var hw = GetArray<int>();
            var h = hw[0];
            var w = hw[1];
            var cs = new int[10][];
            for (int i = 0; i < 10; i++)
            {
                cs[i] = GetArray<int>();
            }

            var minCosts = new int[10];
            for (int i = 0; i < 10; i++)
            {
                if (i == 1)
                {
                    minCosts[i] = 0;
                }
                else
                {
                    minCosts[i] = Bfs(i, cs);
                }
            }

            var sum = 0;
            for (int i = 0; i < h; i++)
            {
                sum += GetArray<int>().Where(x => x != -1).Sum(x => minCosts[x]);
            }
            Write(sum);
        }

        private static int Bfs(int start, int[][] cs)
        {
            var dist = cs.Clone() as int[][];
            for (int k = 0; k < 10; k++)
            {
                for (int i = 0; i < 10; i++)
                {
                    for (int j = 0; j < 10; j++)
                    {
                        dist[i][j] = Math.Min(dist[i][j], dist[i][k] + dist[k][j]);
                    }
                }
            }
            return dist[start][1];
        }
    }
