        {
            int ret = 0;
            int[] weight = new int[10];

            for (int i = 0; i < 10; i++)
            {
                weight[i] = funcGetNextWeight(arg2[i][1], 0, i, arg2);
            }

            foreach(int i in arg3){
                if (i == -1) continue;
                ret += weight[i];
            }

            return ret.ToString();
        }

        static private int funcGetNextWeight(int tarWeight,int curWeight, int _i, List<int[]> clist)
        {
            int retWeight = curWeight + clist[_i][1];
