            {
                if (j == 1) continue;
                if (_i == j) continue;
                if (curWeight + clist[_i][j] < tarWeight) {
                    var tmp = funcGetNextWeight(tarWeight, curWeight + clist[_i][j],j , clist);
                    if (tmp < retWeight) {
                        retWeight = tmp;
                    }
                }
            }

            return retWeight;
        }

