                }
            }
        }
        Console.WriteLine(ans);
    }
    class WarshallFloyd
    {
        public int N { get; set; }
        public int[,] DP { get; set; }
        public int INF = (int)1e9 + 1;
        public WarshallFloyd(int n)
        {
            this.N = n;
            this.DP = new int[N, N];
            for (int i = 0; i < N; i++)
            {
                for (int j = 0; j < N; j++)
                {
                    this.DP[i, j] = INF;
                }
            }
        }
        public void SetCost(int a, int b, int c = 1)
        {
            this.DP[a, b] = c;
        }
        public void CalcMinCost()
        {
            for (int i = 0; i < N; i++)
            {
                for (int j = 0; j < N; j++)
                {
                    for (int k = 0; k < N; k++)
                    {
                        DP[i, j] = Math.Min(DP[i, j], DP[i, k] + DP[k, j]);
                    }
                }
            }
        }
        public int GetMinCost(int a, int b)
        {
            return DP[a, b];
        }
    }
    static Scanner sc = new Scanner();
}

