            {
                A[i, j] = sc.ReadInt();
            }
        }

        Memo = new int[10];
        for (int i = 0; i < 10; i++)
        {
            Memo[i] = -1;
        }
        long ans = 0;
        var used = new bool[10];
        for (int i = 0; i < H; i++)
        {
            for (int j = 0; j < W; j++)
            {
                ans += Rec(A[i, j], used);
            }
        }
        Console.WriteLine(ans);
    }

    static int[] Memo;
    static int[,] A;
    static int[,] C;
    static int H;
    static int W;
    static int Rec(int n, bool[] used)
    {
        if (n == -1) return 0;
        if (Memo[n] != -1) return Memo[n];
        var res = C[n, 1];
        used[n] = true;
        for (int i = 0; i < 10; i++)
        {
            if (C[n, i] < res && !used[i])
            {
                res = Math.Min(res, C[n, i] + Rec(i, used));
            }
        }
        Memo[n] = res;
        used[n] = false;
        return Memo[n];
    }
