using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

public class Program
{
    public static void Main()
    {
        string[] s = Console.ReadLine().Split(' ');
        int N = int.Parse(s[0]);
        int W = int.Parse(s[1]);
        int[,] wall = new int[N, W];

        int[,] c = new int[10, 10];
        for (int i = 0; i < 10; i++)
        {
            s = Console.ReadLine().Split(' ');
            for (int j = 0; j < 10; j++) c[i, j] = int.Parse(s[j]);
        }

        for (int i = 0; i < N; i++)
        {
            s = Console.ReadLine().Split(' ');
            for (int j = 0; j < W; j++)
            {
                wall[i, j] = int.Parse(s[j]);
            }
        }

        int power = 0;
        int p_box = 0;
        int p_pos = 0;
        int rim = 0;

        int[] box = new int[10];
        for (int i = 0; i < 10; i++) box[i] = 0;
        int b = 0;

        for (int i = 0; i < N; i++)
        {
            for (int j = 0; j < W; j++)
            {
                if (wall[i, j] == 1 || wall[i, j] == -1) continue;
                if (box[wall[i, j]] != 0)
                {
                    power += box[wall[i, j]];
                    continue;
                }
                b = wall[i, j];
                p_box = 0;
                rim = c[wall[i, j], 1];
                while (true)
                {
                    int min = 10;
                    for (int k = 0; k < 10; k++)
                    {
                        if (min > c[wall[i, j], k] && wall[i, j] != k) { min = c[wall[i, j], k]; p_pos = k; }
                    }
                    p_box += c[wall[i, j], p_pos];
                    wall[i, j] = p_pos;
                    if (wall[i, j] == 1) break;
                    if (rim < p_box) { p_box = rim + 1; break; }
                }
                if (rim > p_box) { power += p_box; box[b] = p_box; }
                else { power += rim; box[b] = rim; }
            }
        }
        Console.WriteLine(power);
    }
}

