    public sealed class Program : BaseProgram
    {
        public static void Main(string[] _) { using (new SetConsole()) { Solve(); } }
        public static void Solve()
        {
            var hw = GetArray<int>();
            var h = hw[0];
            var w = hw[1];
            var cs = new int[10][];
            for (int i = 0; i < 10; i++)
            {
                cs[i] = GetArray<int>();
            }

            var minCosts = new int[10];
            for (int i = 0; i < 10; i++)
            {
                if (i == 1)
                {
                    minCosts[i] = 0;
                }
                else
                {
                    minCosts[i] = Bfs(i, cs);
                }
            }

            var sum = 0;
            for (int i = 0; i < h; i++)
            {
                var array = GetArray<int>();
                for (int j = 0; j < w; j++)
                {
                    if (array[j] == -1) { continue; }

                    sum += minCosts[array[j]];
                }
            }
            Write(sum);
        }

        private static int Bfs(int start, int[][] cs)
        {
            var costs = new int[10][];
            for (int i = 0; i < 10; i++)
            {
                costs[i] = Enumerable.Repeat(int.MaxValue, 10).ToArray();
            }
            var que = new Queue<Tuple<int, int>>();
            que.Enqueue(Tuple.Create(0, start));

            while (que.Any())
            {
                var current = que.Dequeue();
                for (int i = 0; i < 10; i++)
                {
                    if (current.Item2 == i) { continue; }

                    if (current.Item1 + cs[current.Item2][i] < costs[current.Item2][i])
                    {
                        costs[current.Item2][i] = current.Item1 + cs[current.Item2][i];
                        if (i != 1)
                        {
                            que.Enqueue(Tuple.Create(costs[current.Item2][i], i));
                        }
                    }
                }
            }

            return costs.Select(x => x[1]).Min();
        }
    }
