public sealed partial class Program
{
    int h, w;
    int[][] cost;
    int[][] board;

    private long Solve()
    {
        var n = 10;

        // 点集合が [0, n] で、点 u から v へのコスト cost[v][u] の辺があるグラフを考える。
        // dist[u]: 1 から u への距離
        var dist = n.MakeArray(u => cost[u][1]);

        // Dijkstra
        var q = BinaryHeap.Create<Vertex>();
        for (var v = 0; v < n; v++)
        {
            q.Enqueue(new Vertex(v, dist[v]));
        }

        while (q.Count > 0)
        {
            var vertex = q.Dequeue();
            var u = vertex.V;

            for (var v = 0; v < n; v++)
            {
                var d = dist[u] + cost[v][u];
                if (dist[v] > d)
                {
                    dist[v] = d;
                    q.Enqueue(new Vertex(v, d));
                }
            }
        }

        return
            (
                from y in h.Range()
                from x in w.Range()
                let d = board[y][x]
                where d != -1
                select dist[d]
            ).Sum();
    }

    private void Read()
    {
        var a = _scanner;
        h = a.N();
        w = a.N();
        cost = 10.MakeArray(y => 10.MakeArray(x => a.N()));
        board = h.MakeArray(y => w.MakeArray(x => a.N()));
    }

    public void EntryPoint()
    {
        Read();
        WriteLine(Solve());
    }
}

