    public class Program
    {
        public object Calc()
        {
            int[] costs = Enumerable.Repeat(-1, 10).ToArray();
            costs[1] = 0;
            var H = consoleReader.Int;
            var W = consoleReader.Int;
            var c = consoleReader.Repeat(10).Select(cr => cr.Split.Int).ToArray();
            {
                var remaining = new HashSet<int>(new[] { 0, 2, 3, 4, 5, 6, 7, 8, 9 });
                var sumi = new HashSet<int>();
                while (remaining.Count > 0)
                {
                    var minIndex = -1;
                    var min = int.MaxValue;
                    foreach (var i in remaining)
                    {
                        if (min > c[i][1])
                        {
                            minIndex = i;
                            min = c[i][1];
                        }
                        foreach (var s in sumi)
                        {
                            var v = costs[s] + c[i][s];
                            if (min > v)
                            {
                                minIndex = i;
                                min = v;
                            }
                        }
                    }
                    remaining.Remove(minIndex);
                    sumi.Add(minIndex);
                    costs[minIndex] = min;
                }
                var sum = 0;
                for (int i = 0; i < H * W; i++)
                {
                    var a = consoleReader.Int;
                    if (a >= 0)
                        sum += costs[a];
                }
                return sum;
            }
        }


