class Program{

    static void Main(string[] args){
        int[,] AdjMatrix = new int[10,10];
        string[] hw = Console.ReadLine().Split(' ');
        int h = int.Parse(hw[0]);
        int w = int.Parse(hw[1]);
        for(var i = 0; i < 10; ++i){
            string[] line = Console.ReadLine().Split(' ');
            for(var j = 0; j < 10; ++j){
                AdjMatrix[i, j] = int.Parse(line[j]);
            }
        }
        var cost = Warshall_Floyd(AdjMatrix);
        long ans = 0;
        for(var i = 0; i < h; ++i){
            string[] line = Console.ReadLine().Split(' ');
            for(var j = 0; j < w; ++j){
                var cur = int.Parse(line[j]);
                if(cur != 1 && cur != -1){
                    ans += cost[cur];
                }
            }
        }
        Console.WriteLine(ans);
    }

    static int[] Warshall_Floyd(int[,] mat){
        int[,] dist = new int[10,10];
        for(var i = 0; i < 10; ++i){
            for(var j = 0; j < 10; ++j){
                dist[i,j] = (mat[i,j] == 0) ? 99999 : mat[i,j];
            }
        }

        for(var i = 0; i < 10; ++i){
            for(var j = 0; j < 10; ++j){
                for(var k = 0; k < 10; ++k){
                    if(dist[j,k] > dist[j,i] + dist[i,k]){
                        dist[j,k] = dist[j,i] + dist[i,k];
                    }
                }
            }
        }

        int[] ans = new int[10];
        for(var i = 0; i < 10; ++i){
            ans[i] = dist[i, 1];
        }
        return ans;
    }
}

