            moveMatrix[i,j] = moveMatrix[i,k] + moveMatrix[k,j];//距離の更新
        }
      }
    }

    for(int i = 0; i < 10; i++)
    {
    answer += moveMatrix[i,1] * walls[i];
    }

	Console.WriteLine(answer);//WriteLineをWriteとすると、改行なしで出力。
	}
}

