        static void Main()
        {
            var HW = Console.ReadLine().Split().Select(int.Parse).ToArray();
            int H = HW[0], W = HW[1];
            var c = new int[10, 10];
            for (int i = 0; i < 10; i++)
            {
                var r = Console.ReadLine().Split().Select(int.Parse).ToArray();
                for (int j = 0; j < 10; j++)
                {
                    c[i, j] = r[j];
                }
            }
            var nums = new int[10];
            for(int i = 0;i < 10; i++)
            {
                if (i == 1) continue;
                var frags = Enumerable.Repeat(int.MaxValue, 10).ToArray();
                frags[i] = 0;
                var que = new Queue<Tuple<int,int>>();
                que.Enqueue(Tuple.Create(i,0));
                while (que.Count > 0)
                {
                    var t = que.Dequeue();
                    if (t.Item1 == 1) continue;
                    for (int j = 0; j < 10; j++)
                    {
                        if (frags[j] <= t.Item2 + c[t.Item1, j]) continue;
                        frags[j] = t.Item2 + c[t.Item1, j];
                        que.Enqueue(Tuple.Create(j, t.Item2 + c[t.Item1, j]));

                    }
                }
                nums[i] = frags[1];
            }

            var A = new int[H, W];
