int dij(int u)
{
	memset(vis,0,sizeof(vis));
	for(int i =1 ;i <= 9 ;i++)
	{
		dis[i] = c[u][i];
	}
	vis[u] = 1;
	for(int i =1 ;i < 9;i++)//必须是小于9，不能等于，debug了好久。。。
	{
		int minn = inf ,v = -1;
		for(int j =1 ;j <= 9 ;j++)
		{
			if(!vis[j]&&dis[j]<minn)
			{
				v = j;
				minn = dis[j];
			}
		}
		vis[v] = 1;
		for(int j = 1; j <= 9 ;j++)
		{
			dis[j] = min(dis[j],dis[v]+c[v][j]);
		}
	}
	return dis[1];
}

void solve()
{
	while(cin >> h >> w)
	{
		for(int i = 0; i < 10 ;i++)
		{
			for(int j = 0 ;j < 10 ;j++)
			{
				cin >> c[i][j];
			}
		}
		memset(jishu,0,sizeof(jishu));
		for(int i = 1 ; i <= w ;i++)
		{
			for(int j = 1; j<= h ;j++)
			{
				cin >> maze[i][j];
				if(maze[i][j] > 1)
				{
					jishu[maze[i][j]]++;
				}
			}
		}
		int ans = 0;
