		Node.parent.children[Node.dir()] = nil
	}
}

func (Node *RBNode) hasDir() RBNodeDir {
	dir := RBNodeLeft
	if Node.children[dir] == nil {
		dir = RBNodeRight
		if Node.children[dir] == nil {
			dir = RBNodeHere
		}
	}
	return dir
}

//Delete is
func (cur *RBTree) Delete(Index int) (ret bool) {
	wcur, dir := cur.Find(Index)
	if dir != RBNodeHere {
		return
	}
	delNode := wcur.Node
	ret = true

	dir = delNode.hasDir()

	if delNode.children[RBNodeLeft] != nil &&
		delNode.children[RBNodeRight] != nil {
		var wrk *RBCursor
		if dir != RBNodeHere {
			wrk = wcur.Cursor().Move(dir)
			delNode.Index = wrk.Node.Index
			delNode = wrk.Node
			dir = delNode.hasDir()
		}
	}

	if dir == RBNodeHere {
		if delNode.isRed {
			delNode.cut()
			cur.Node = delNode.parent
			return
		}
	} else {
		wrk := delNode.children[dir]
		delNode.Index = wrk.Index
		wrk.cut()
		return
	}

	Node := delNode
	for {
		parent := Node.parent
		if parent == nil {
			break
		}

		dir := Node.dir()
		dirOther := dir ^ 1
		sibling := parent.children[dirOther]

		if sibling.isRed {
			//sibling is Red
			parent.flip(dirOther)
			sibling.isRed = false
			parent.isRed = true
			sibling = parent.children[dirOther]
		}
		//sibling is Black

		nephew := sibling.children[dirOther]
		if nephew == nil || !nephew.isRed {
			//far nephew is Black
			nephew = sibling.children[dir]
			if nephew == nil || !nephew.isRed {
				//near nephew is Black
				sibling.isRed = true
				if parent.isRed {
					parent.isRed = false
					break
				} else {
					Node = parent
					continue
				}
			}
			//near nephew is Red and far nephew is Black
			sibling.flip(dir)
			sibling, nephew = nephew, sibling
			sibling.isRed = false
			nephew.isRed = true
		}
		//sibling is Black && far nephew is Red

		parent.flip(dirOther)
		sibling.isRed = parent.isRed
		parent.isRed = false
		nephew.isRed = false
		break
	}
	delNode.cut()
	cur.Node = delNode.parent
	return
}

type line struct {
	to, from int
	cost     int
	added    bool
}

type lineSort []line

func (a lineSort) Len() int           { return len(a) }
func (a lineSort) Swap(i, j int)      { a[i], a[j] = a[j], a[i] }
func (a lineSort) Less(i, j int) bool { return a[i].cost < a[j].cost }

func solve(stdin io.Reader, stdout io.Writer) {

	r := NewScannerEx(stdin)
	r.Scan(true)
	h, _ := r.nextInt(), r.nextInt()

	c := make([][]line, 10)
	for i := range c {
		c[i] = make([]line, 0, 10)
	}
	for i := range c {
		r.Scan(true)

		for j, v := range r.nextStringArray().toInts() {
			if i != j {
				c[j] = append(c[j], line{from: i, to: j, cost: v})
			}
		}
	}

	list := make([]*line, 0, 10*10)

	tree := NewTree(func(i, j int) bool {
		left, right := list[i], list[j]
		switch {
		case left.cost != right.cost:
			return left.cost < right.cost
		case left.from != right.from:
			return left.from < right.from
		default:
			return left.to < right.to
		}
	})

	treeAdd := func(lp *line) {
		i := len(list)
		list = append(list, lp)
		tree.Add(i)
	}

	treeAdd(&line{from: 1, to: 1, cost: 0})
	gall := make([]int, 10)
	for i := range gall {
		gall[i] = -1
	}
	gallcnt := 10

	for {
		l := tree.End(RBNodeLeft)
		lt := list[l.Node.Index]
		tree.Delete(l.Node.Index)
		if gall[lt.from] >= 0 {
			continue
		}
		gall[lt.from] = lt.cost
		gallcnt--
		if gallcnt <= 0 {
			break
		}

		for i := range c[lt.from] {
			next := &c[lt.from][i]
			if next.added {
				continue
			}
			next.cost += lt.cost
			next.added = true
			treeAdd(next)
		}
	}

	ans := 0
	for i := 0; i < h; i++ {
		r.Scan(true)
		w := r.nextStringArray().toInts()
		for _, v := range w {
			if v > 0 {
				ans += gall[v]
			}
		}
	}

	fmt.Fprintln(stdout, ans)
}

