import "fmt"

func main() {
	var h, w int
	var c [10][10]int
	fmt.Scan(&h)
	fmt.Scan(&w)

	for i := 0; i <= 9; i++ {
		for j := 0; j <= 9; j++ {
			fmt.Scan(&c[i][j])
		}
	}

	for i := 0; i <= 9; i++ {
		for j := 0; j <= 9; j++ {
			for k := 0; k <= 9; k++ {
				if c[j][i]+c[i][k] < c[j][k] {
					c[j][k] = c[j][i] + c[i][k]
				}
			}
		}
	}

	answer := 0
	for i := 0; i < h*w; i++ {
		var a int
		fmt.Scan(&a)

		if a >= 0 {
			answer += c[a][1]
		}
	}
	fmt.Println(answer)
}

