		for i := range vs {
			v := &vs[i]
			if a > *v {
				a = *v
			}
		}
		return a
	}
	for k := 0; k < 10; k++ {
		for i := 0; i < 10; i++ {
			for j := 0; j < 10; j++ {
				cs[i][j] = minInt(cs[i][j], cs[i][k]+cs[k][j])
			}
		}
	}

	result := 0
	for i := 0; i < h; i++ {
		for j := 0; j < w; j++ {
			if as[i][j] != -1 {
				result += cs[as[i][j]][1]
			}
		}
	}

	fmt.Fprintln(stdout, result)
}

