				min = costs[i][1]
				index = i
			}
		}
		if index == NotFound {
			break
		}
		updated[index] = 1
		for i := 0; i < 10; i++ {
			cost := costs[i][index] + costs[index][1]
			if costs[i][1] > cost {
				costs[i][1] = cost
			}
		}
	}

	ans := 0
