// ---------- buffered scanner -----------------------------------------
func iferr(err error) {
	if err != nil {
		panic(err)
	}
}

type scanner struct {
	r   *bufio.Reader
	buf []byte
	p   int
}

func newScanner() *scanner {
	rdr := bufio.NewReaderSize(os.Stdin, 10000)
	return &scanner{r: rdr}
}
func (s *scanner) next() string {
	s.pre()
	start := s.p
	for ; s.p < len(s.buf); s.p++ {
		if s.buf[s.p] == ' ' {
			break
		}
	}
	result := string(s.buf[start:s.p])
	s.p++
	return result
}
func (s *scanner) Line() string {
	s.pre()
	start := s.p
	s.p = len(s.buf)
	return string(s.buf[start:])
}
func (s *scanner) String() string {
	return s.next()
}
func (s *scanner) Int() int {
	v, e := strconv.Atoi(s.next())
	iferr(e)
	return v
}
func (s *scanner) Ints(n int) []int {
	r := make([]int, n)
	for i := 0; i < n; i++ {
		r[i] = s.Int()
	}
	return r
}
func (s *scanner) Int64() int64 {
	v, e := strconv.ParseInt(s.next(), 10, 64)
	iferr(e)
	return v
}
func (s *scanner) Uint64() uint64 {
	v, e := strconv.ParseUint(s.next(), 10, 64)
	iferr(e)
	return v
}
func (s *scanner) Float64() float64 {
	v, e := strconv.ParseFloat(s.next(), 64)
	iferr(e)
	return v
}
func (s *scanner) pre() {
	if s.p >= len(s.buf) {
		s.readLine()
		s.p = 0
	}
}
func (s *scanner) readLine() {
	s.buf = make([]byte, 0)
	for {
		l, p, e := s.r.ReadLine()
		iferr(e)
		s.buf = append(s.buf, l...)
		if !p {
			break
		}
	}
}

