func dijkstra(adj [][]int, cost []int) {
	visited := make([]bool, 10)
	visited[1] = true
	s := 1
	for {
		for i := 0; i <= 9; i++ {
			cost[i] = minInt(cost[i], cost[s]+adj[i][s])
		}
		next := -1
		minCost := INF
		for i := 0; i <= 9; i++ {
			switch {
			case visited[i]:
				continue
			case cost[i] < minCost:
				next = i
				minCost = cost[i]
			}
		}
		if next == -1 {
			break
		}
		visited[next] = true
		s = next
	}
}

