			fmt.Scan(&c[i][j])
		}
	}

	minCosts := make([]int, 10)
	for i := 0; i < 10; i++ {
		minCosts[i] = solve(c, i)
	}

	ans := 0
	for i := 0; i < H; i++ {
		for j := 0; j < W; j++ {
			A := 0
			fmt.Scan(&A)
			if A == -1 || A == 1 {
				continue
			}
