/** Return minimum cost from start to 1 */
func solve(c [][]int, start int) int {
	if start == 1 {
		return 0
	}
	const Big = 999999

	unfixed := make([]int, 10)
	fixed := make([]int, 10)
	for i := 0; i < 10; i++ {
		fixed[i] = Big
		unfixed[i] = Big
	}
	cur := start
	fixed[cur] = 0
	unfixed[cur] = 0

	// iterate 9 times
	for i := 0; i < 9; i++ {
		// calc unfixed costs.
		for j := 0; j < 10; j++ {
			// cur -> j
			if fixed[j] != Big {
				continue
			}
			x := fixed[cur] + c[cur][j]
			if unfixed[j] > x {
				unfixed[j] = x
			}
		}
		// find minimum unfixed costs.
		muc := Big
		for j := 0; j < 10; j++ {
			if fixed[j] == Big && unfixed[j] < muc {
				muc = unfixed[j]
				cur = j
			}
		}
		fixed[cur] = unfixed[cur]
	}
	return fixed[1]
}

