var dpss [][]int64
var css [][]int64
var ass [][]int64

func subSolve(from int64, filter int64) int64 {
	if from == 1 {
		return 0
	}
	if dpss[from][filter] != 0 {
		return dpss[from][filter]
	}
	ret := css[from][1]
	for via := int64(0); via < 10; via ++ {
		if via == 1 {
			continue
		}
		viaFilter := int64(1) << via
		if (viaFilter & filter) == 0 {
			continue
		}
		candidate := css[from][via]
		if candidate >= ret {
			continue
		}
		candidate += subSolve(via, filter ^ viaFilter)
		if candidate < ret {
			ret = candidate
		}
	}
	dpss[from][filter] = ret
	return ret
}

func solve(h int64, w int64) int64 {
	dpss = make([][]int64, 10)
	for i := 0;i < 10; i ++ {
		dpss[i] = make([]int64, 1024)
	}
	ret := int64(0)
	for _, as := range ass {
		for _, a := range as {
			if a < 0 {
				continue
			}
			r := subSolve(a, 1023)
			ret += r
		}
	}
	return ret
}

