	H, W := scanInt(), scanInt()

	C := [10][10]int{}
	for i := 0; i < 10; i++ {
		for j := 0; j < 10; j++ {
			C[i][j] = scanInt()
		}
	}

	Map := [10][100]int{}
	for i := 0; i < 10; i++ {
		Map[i][1] = C[i][1]
	}

