auto parse( Range )( Range input )
if( isInputRange!Range && is( ElementType!Range == string ) )
{
	auto hw = input.front.split.to!( long[] );
	auto css = new long[][]( 10, 10 );
	foreach( ref cs; css )
	{
		input.popFront;
		cs = input.front.split.to!( long[] );
	}
	auto ass = new long[][]( hw[ 0 ], hw[ 1 ] );
	foreach( ref as; ass )
	{
		input.popFront;
		as = input.front.split.to!( long[] );
	}
	return tuple( css, ass );
}

auto solve( long[][] css, long[][] ass )
{
	css = warshallfloyd( css );
	auto ans = 0L;
	foreach( as; ass )
	{
		foreach( a; as )
		{
			if( 0 <= a ) ans += css[ a ][ 1 ];
		}
	}
	return ans;
}

// 正負の重み付きグラフの全二点間最短経路探索（ワーシャルフロイド法）
auto warshallfloyd( ref long[][] dss )
{
	foreach( p; 0L .. dss.length )
	{
		foreach( f; 0L .. dss.length )
		{
			foreach( t; 0L .. dss.length )
			{
				if( dss[ f ][ p ] == long.max || dss[ p ][ t ] == long.max ) continue;
				dss[ f ][ t ] = min( dss[ f ][ t ], dss[ f ][ p ] + dss[ p ][ t ] );
			}
		}
	}
	return dss;
}

