	auto bestCost = new long[](10);
	foreach (i; 0..10)
	{
		auto cost = new long[](10);
		fill(cost, long.max);
		cost[i] = 0;
		long[] open = [i];
		while (!open.empty)
		{
			auto node = open.front;
			open.popFront;
			cost[1] = min(cost[1], cost[node] + c[node][1]);
			foreach (j; 0..10)
			{
				if (i == j || j == 1) continue;

				if (cost[node] + c[node][j] < cost[1] && cost[node] + c[node][j] < cost[j])
				{
					cost[j] = cost[node] + c[node][j];
					open ~= j;
				}
			}
		}
		bestCost[i] = cost[1];
	}

	long ans;
	foreach (i; 0..H)
	{
		foreach (j; 0..W)
		{
			if (abs(A[i][j]) == 1) continue;
			ans += bestCost[A[i][j]];
		}
	}

