auto solve( long[][] css, long[][] ass )
{
	auto ds = dijkstraEx( css, 1 );
	auto ans = 0L;
	foreach( as; ass )
	{
		foreach( a; as )
		{
			if( 0 <= a ) ans += ds[ a ];
		}
	}
	return ans;
}

// 正の重み付きグラフの始点指定最短経路探索（ダイクストラ法）
auto dijkstraEx( bool undirected = false )( long[][] css, long s )
{
	import std.container.binaryheap;

	auto ds = new long[ 10 ];
	ds[] = long.max;
	ds[ s ] = 0;

	auto queue = heapify!( ( a, b ) => b[ 1 ] < a[ 1 ] )( new Tuple!( long, long )[ 100 ], 0 );
	queue.insert( tuple( s, 0L ) );
	while( !queue.empty )
	{
		auto fi = queue.front[ 0 ];
		auto fd = queue.front[ 1 ];
		queue.popFront();
		if( ds[ fi ] < fd ) continue;

		for( auto ti = 0L; ti < css.length; ti++ )
		{
			if( ti == fi ) continue;

			auto td = fd + css[ ti ][ fi ];
			if( ds[ ti ] < td ) continue;

			ds[ ti ] = td;
			queue.insert( tuple( ti, td ) );
		}
	}
	return ds;
}

