struct node
{
    int mp;
    int n;
    vector<int> path;
    node(int tmp, int tn, vector<int>tp)
    {
        n = tn;
        mp = tmp;
        path = tp;
        path.push_back(tn);
    }
    friend bool operator < (node A, node B)
    {
        return A.mp > B.mp;
    }
};

