int bfs(int ori)
{
    int j;
    bool chkre[10];
    priority_queue<node> que, q_empty;

    memset(chkre, 0, sizeof(chkre));
    que.push(node(0, ori, vec_empty));
    while(que.size())
    {
        node start = que.top();
        que.pop();
        if(start.n == 1)
        {
            res += start.mp;
            //printf("\nres = %d add = %d\n\n", res, start.mp);
            //printf("ori=%d the path:\n", ori);
            //vector<int>::iterator si;
            //for(si = start.path.begin();si != start.path.end();si++) printf("%d\n", *si);
            return 0;
