        if(chkre[start.n] == 1) continue;

        for(j = 0;j <= 9;j++)
        {
            if(chkre[j] == 1) continue;
            if(start.n == j) continue;

            //printf("convert %d to %d mp=%d\n", start.n, j, start.mp + spend[start.n][j]);

            que.push(node(start.mp + spend[start.n][j], j, start.path));
