using namespace std;
const int MaxN = 4e4;

int pre[2 * MaxN + 5], last[MaxN + 5], other[2 * MaxN + 5], cost[2 * MaxN + 5];
int dis[MaxN + 5], q[MaxN * 10 + 5], a[205][205];
int all, h, w, n;
bool vis[MaxN + 5];

void init(){
	all = -1; memset(last, -1, sizeof(last));
	for(int i = 1; i <= n; i++) dis[i] = 1 << 30;
}

void build(int u, int v, int c){
	pre[++all] = last[u];
	last[u] = all;
	other[all] = v;
	cost[all] = c;
}

void spfa(int p){
	dis[p] = 0;
	int head = 1, tail = 0;
	q[++tail] = p; vis[p] = true;
	while(head <= tail){
		int u = q[head], ed = last[u], dr;
		while(ed != -1){
			dr = other[ed];
			if(dis[u] + cost[ed] < dis[dr]){
				dis[dr] = dis[u] + cost[ed];
				if(!vis[dr]){
					q[++tail] = dr;
					vis[dr] = true;
				}
			}
			ed = pre[ed];
		}
		vis[u] = false;
		head++;
	}
}

