    var list = newSeq[ref seq[T]](0)
    var st = 0
    var last = v.len-1
    for i in 0..last:
        if i == last or v[i] != v[i+1]:
            var sec = new(seq[T])
            sec[] = v[st..i]
            list.add(sec)
            st = i + 1
    return list
proc has[T](v:seq[T], elemList:varargs[T]):bool=
    var vCopied:seq[T] = v
    for elem in elemList:
        let itr = vCopied.find(elem)
        if itr == -1:
            return false
        else:
            vCopied.del(itr)
    return true

