import sequtils, complex, lists, strutils
import algorithm


type
  Edge*[T: SomeNumber] = ref object
    src, dst: int
    weight: T


  Graph*[T: SomeNumber] = ref object
    N: int
    M: int
    edges: seq[DoublyLinkedList[Edge[T]]]


proc newEdge*[T: SomeNumber](src, dst: int, weight: T): Edge[T] =
  new(result)
  result.src = src
  result.dst = dst
  result.weight = weight


func src*[T: SomeNumber](self: Edge[T]): int {.inline.} = self.src


func dst*[T: SomeNumber](self: Edge[T]): int {.inline.} = self.dst


func weight*[T: SomeNumber](self: Edge[T]): T {.inline.} = self.weight


func nNodes*[T: SomeNumber](self: Graph[T]): int {.inline.} = self.N


func nEdges*[T: SomeNumber](self: Graph[T]): int {.inline.} = self.M


proc newGraph*[T: SomeNumber=int](N: int): Graph[T] =
  new(result)
  result.N = N
  result.M = 0
  result.edges = newSeqWith(N, initDoublyLinkedList[Edge[T]]())


iterator edges*[T](self: Graph[T], i: int): Edge[T] =
  for edge in self.edges[i]:
    yield edge


proc addEdge*[T](self: Graph[T], i, j: int, weight: T) =
  if min(i, j) < 0:
    raise newException(ValueError, "min(i, j) < 0.")
  if max(i, j) >= self.N:
    raise newException(ValueError, "max(i, j) >= self.nNodes.")

  for edge in mitems(self.edges[i]):
    if edge.dst == j:
      edge.weight += weight
      return

  # if the graph does not have the edge i->j
  self.edges[i].append(newEdge[T](src=i, dst=j, weight=weight)) 
  inc(self.M)


type
  Result[T] = tuple[dist: seq[seq[T]], prev: seq[seq[int]], 
                    negativeCycle: bool]


proc floydWarshall*[T: SomeNumber](graph: Graph[T], dist: var seq[seq[T]],
                                   prev: var seq[seq[int]]): bool =
  ## Computes the minimum distances among all nodes.
  if len(dist) < graph.nNodes:
    dist.setLen(graph.nNodes)
  for i in 0..<graph.nNodes:
    if len(dist[i]) < graph.nNodes:
      dist[i].setLen(graph.nNodes)
    dist[i].fill(high(T))

  if len(prev) < graph.nNodes:
    prev.setLen(graph.nNodes)
  for i in 0..<graph.nNodes:
    if len(prev[i]) < graph.nNodes:
      prev[i].setLen(graph.nNodes)
    prev[i].fill(-1)

  result = true
  # Initialize distances
  for i in 0..<graph.nNodes:
    prev[i][i] = -2
    for edge in graph.edges[i]:
      dist[i][edge.dst] = edge.weight
      prev[i][edge.dst] = i

  # Compute the minimum distances
  for k in 0..<graph.nNodes:
    for i in 0..<graph.nNodes:
      for j in 0..<graph.nNodes:
        if dist[i][k] != high(T) and dist[k][j] != high(T):
          if (dist[i][k] + dist[k][j] < dist[i][j]):
            dist[i][j] = dist[i][k] + dist[k][j]
            prev[i][j] = k
  # Is there a negative cycle?
  for i in 0..<graph.nNodes:
    if dist[i][i] < 0:
      result = false


