import sys
import heapq
import copy
import itertools

inf = float('inf')

class Graph_dijkstra(object):
    def __init__(self, V: "List[int]", E: "Set[Tuple[int, int]]", L: "Dict[Tuple[int, int], int]"):
        self.V = V
        self.E = E
        self.L = L
        self.adjacent = self.init_adjacent() # type: Dict[int: List[int]]
        self.shortest_path = self.init_shortest_path() # type: Dict[FrozenSet[int, int], int]

    def init_adjacent(self):
        ret = {v: [] for v in self.V}
        for e in self.E:
            ret[e[0]].append(e[1])
        return ret

    def init_shortest_path(self):
        ret = {(s, g): inf for s, g in itertools.permutations(self.V, 2)}
        for v in self.V:
            ret[(v, v)] = 0
        return ret

    def dijkstra(self, s: int):
        D = {v: inf for v in self.V}
        D[s] = 0
        prev = {v: None for v in self.V}
        Q = [(0, s)]

        while len(Q) > 0:
            du, u = heapq.heappop(Q)
            for v in self.adjacent[u]:
                e = (u, v)
                alt = du + self.L[e]
                if alt < D[v]:
                    D[v] = alt
                    prev[v] = u
                    heapq.heappush(Q, (D[v], v))

        for v in self.V:
            self.shortest_path[(s, v)] = D[v]

    def find_shortest_path(self, s: int, g:int):
        d = self.shortest_path[(s, g)]
        if d < inf:
            return d
        self.dijkstra(s)
        return self.shortest_path[(s, g)]


def solve(H: int, W: int, c: "List[List[int]]", A: "List[List[int]]"):
    V = list(range(10))
    E = set()
    L = dict()

    for i in range(10):
        for j in range(10):
            e = (i, j)
            E.add(e)
            L[e] = c[i][j]

    G = Graph_dijkstra(V, E, L)

    count = [0 for _ in range(10)]
    for h in range(H):
        for w in range(W):
            if A[h][w] == -1:
                continue
            count[A[h][w]] += 1

    total = 0
    for i in range(10):
        total += G.find_shortest_path(i, 1) * count[i]

    print(total)

    return


