def dijkstra(start_node, num_nodes, cost_dict):
    import heapq

    initial_nodes = cost_dict[start_node]
    min_costs = {start_node : 0}
    available_nodes = initial_nodes
    done_nodes = set([start_node])
    heapq.heapify(available_nodes)

    # Loop until all nodes are searhced
    while len(available_nodes) > 0:
        (min_cost, dest_node) = heapq.heappop(available_nodes)
        if(dest_node in done_nodes):
            continue
        min_costs[dest_node] = min_cost
        done_nodes.add(dest_node)
        # New available nodes
        for new_node in cost_dict[dest_node]:
            new_node_cost = new_node[0] + min_cost
            new_node_dest = new_node[1]
            if(new_node_dest in done_nodes):
                continue
            heapq.heappush(available_nodes, (new_node_cost, new_node_dest))
    return min_costs

