    c = list(map(int, input().split()))
    adj_matrix.append(c)

Adj_list = defaultdict(set)

for i in range(n):
    for j in range(n):
        Adj_list[i].add((j, adj_matrix[i][j]))


def dijkstra(x, vertex):
    d = [INF] * x
    d[vertex] = 0
    hq = [(0, vertex)]

    while hq:
        u = heapq.heappop(hq)[1]
        for (v, c) in Adj_list[u]:
            if d[v] > d[u] + c:
                d[v] = d[u] + c
                heapq.heappush(hq, (d[u]+c, v))

    return d

