    #始点sから各頂点への最短距離
    d = [float("inf")] * n
    used = [True] * n #True:未確定
    d[s] = 0
    used[s] = False
    edgelist = []
    for e in edge[s]:
        heapq.heappush(edgelist,e)
    while len(edgelist):
        minedge = heapq.heappop(edgelist)
        #まだ使われてない頂点の中から最小の距離のものを探す
        if not used[minedge[1]]:
            continue
        v = minedge[1]
        d[v] = minedge[0]
        used[v] = False
        for e in edge[v]:
            if used[e[1]]:
                heapq.heappush(edgelist,[e[0]+d[v],e[1]])
    return d


def main():
    H, W = map(int, input().split())

    edge = [[] for i in range(10)]
    for i in range(10):
        C = list(map(int, input().split()))
        for j in range(10):
            if i==j:
                continue
            edge[i].append([C[j],j])

    MP = [0]*10
    for i in range(10):
        if i==1:
            continue
        D = dijkstra_heap(i, 10, edge)
        MP[i] = D[1]

    ans = 0
    for i in range(H):
        A = list(map(int, input().split()))
        for a in A:
            if a==-1:
                continue
            ans += MP[a]

    print(ans)

