import sys

def WarshallFloyd(V: int, cost: "List[List[int]]"):
    """
    全ての頂点対の間の最短距離を求めます。
    ==============
    V: 頂点数
    cost: 隣接行列(辺が存在しない部分はINF)
    --------------
    cost: 最短距離の行列
    """
    INF = 1e18
    for k in range(V):
        for i in range(V):
            for j in range(V):
                if cost[i][k] != INF and cost[k][j] != INF:
                    cost[i][j] = min(cost[i][j], cost[i][k] + cost[k][j])
    return cost

def solve(H: int, W: int, c: "List[List[int]]", A: "List[List[int]]"):
    cost = WarshallFloyd(len(c), c)
    C = [0] * 10
    for a in A:
        for aa in a:
            if aa != -1:
                C[aa] += 1
    c = 0
    for i in range(10):
        c += cost[i][1] * C[i]
    print(c)
    return


