def search_min_cost(nums, prev_num, min_cost, cost, c):
    _last_min_cost = min_cost
    if len(nums) != 0:
        _min_cost = cost + c[prev_num][1]
        if min_cost < _min_cost:
            _min_cost = min_cost
        for i in nums:
            _nums = nums[:]
            _nums.remove(i)
            next_cost = cost + c[prev_num][i]
            if _min_cost <= next_cost:
                if _min_cost < _last_min_cost:
                    _last_min_cost = _min_cost
            else:
                m = search_min_cost(
                    _nums, i, _min_cost, next_cost, c)
                if m < _last_min_cost:
                    _last_min_cost = m
    return _last_min_cost


