def z(changeable: [], cc: [], ans_set):
    for nums, limit_c in changeable:
        # 最新のもの
        num = nums[-1]
        next_ls = []
        target = cc[num]
        limit = limit_c

        if target[1] < limit:
            limit = target[1]
            sub = target[1]
            for i in range(len(nums)-1):
                sub += cc[nums[i]][nums[i+1]]
            ans_set.add(sub)

        for i in range(10):
            if i in nums:
                continue
            x = target[i]
            if x < limit:
                nums_cp = nums[:]
                nums_cp.append(i)
                next_ls.append((nums_cp, limit - x))
        z(next_ls, cc, ans_set)


