def dijkstra(s,N,cost):
    d = [float("inf")] * N
    used = [False] * N
    d[s] = 0

    while True:
        v = -1
        for u in range(N):
            if not used[u] and (v == -1 or d[u] < d[v]):
                v = u
        if v == -1:
            break
        used[v] = True

        for u in range(N):
            d[u] = min(d[u], d[v] + cost[v][u])

    return d

