def min_cost_of(s, d, t, nlist, cost):
    if s == d or s == t:
        return cost
    else:
        minimum = c[s][d]
        for i in nlist:
            rlist = list(nlist)
            rlist.remove(i)
            result = min_cost_of(s, d, i, rlist, cost + c[i][t])
            if result < minimum:
                minimum = result
        return minimum

