                nums[temp[j]]+=1

    def get_target_min_index(min_index,distance,unsearch):
        start=0
        while True:
            index=distance.index(min_index,start)
            found=index in unsearch
            if found:
                return index
            else:
                start = index+1

    while len(unsearch)!=0:
        posible_min_distance=INF
        for node_index in unsearch:
            if posible_min_distance > cos[node_index]:
                posible_min_distance=cos[node_index]
        target_min_index=get_target_min_index(posible_min_distance,cos,unsearch)
        unsearch.remove(target_min_index)
        target_edge=cs[target_min_index] #あるVからの距離の一覧

        for index,route_dis in enumerate(target_edge):
             #Vからの総てのノードに対して計算
             if route_dis !=0:
                 if cos[index] > cos[target_min_index] + route_dis:
                     cos[index]=cos[target_min_index] + route_dis


    result=0
    for i in range(10):
        result+=(nums[i]*cos[i])
    print (result)




