INF=10**12

def dijkstra(G, start = 0, INF=INF):

    d = [INF for i in range(len(G))]
    d[start] = 0

    que = []
    heappush(que, (0, start))

    while len(que) != 0:
        p = heappop(que)
        v = p[1]

        if d[v] < p[0]:
            continue

        for u in G[v].keys():
            if d[u] > d[v] + G[v][u]:
                d[u] = d[v] + G[v][u]
                heappush(que, (d[u], u))

    return d

