def main():
    h,w = LI()
    t = [LI() for _ in range(10)]
    a = [LI() for _ in range(h)]
    e = collections.defaultdict(list)
    for i in range(10):
        for j in range(10):
            e[i].append((j,t[j][i]))

    def search(s):
        d = collections.defaultdict(lambda: inf)
        d[s] = 0
        q = []
        heapq.heappush(q, (0, s))
        v = collections.defaultdict(bool)
        while len(q):
            k, u = heapq.heappop(q)
            if v[u]:
                continue
            v[u] = True

            for uv, ud in e[u]:
                if v[uv]:
                    continue
                vd = k + ud
                if d[uv] > vd:
                    d[uv] = vd
                    heapq.heappush(q, (vd, uv))

        return d

    d = search(1)
    r = 0
    for b in a:
        for c in b:
            if c*c == 1:
                continue
            r += d[c]

    return r



