def dijkstra(start,node,cost):
    d = [float('inf') for i in range(node)]
    used = [False for i in range(node)]
    d[start] = 0
    while True:
        flag = True
        for i in range(node):
            if (not used[i]) and flag:
                v = i
                flag = False
            elif (not used[i]) and d[i] < d[v]:
                v = i

        if flag:
            break
        used[v] = True
        for j in range(node):
            d[j] = min(d[j],d[v]+cost[v][j])
    return d

