def dijkstra(d, s, t):
    INF = 10**10
    dist = [INF] * 10
    dist[s] = 0
    checked = []

    while True:
        # 未チェックの中から，sからのコストが現状最も小さいものを見つける
        nodes = [node for node in range(10) if node not in checked]
        shortest_node, cost = nodes[0], dist[nodes[0]]

        for node in nodes:
            if dist[node] < cost:
                shortest_node, cost = node, dist[node]

        if shortest_node == t:
            return dist[t]

        checked.append(shortest_node)

        nodes = [node for node in range(10) if node not in checked]
        for node in nodes:
            dist[node] = min(
                dist[shortest_node] + d[shortest_node][node], dist[node])


