fn main() {
    let hw: Vec<i64> = read_vec();
    let mut maryoku: Vec<Vec<u64>> = vec![];
    for _ in 0..10 {
        maryoku.push(read_vec());
    }

    let mut map: Vec<Vec<i8>> = vec![];
    for _ in 0..hw[0] {
        map.push(read_vec());
    }

    for i in 0..10 {
        for j in 0..10 {
            if i == j {
                continue;
            }
            let t = maryoku[i][j];

            let mut start = i;
            let mut count = 0;
            //println!("-----{} {}-----", start, end);
            loop {
                //println!("start: {} {}", start, count);
                let mut min = 0;
                for (k, v) in maryoku[start].iter().enumerate() {
                    if *v == 0 {
                        continue;
                    }
                    if min > *v || min == 0 {
                        min = *v;
                        start = k;
                    }
                }
                count = count + min;
                //println!("next start: {} {}", start, count);
                if count >= t {
                    count = 0;
                    break;
                }

                if start == j {
                    break;
                }
            }

            if count != 0 {
                maryoku[i][j] = count;
            }
        }
    }

    let mut count = 0;
    for i in 0..hw[0] {
        for j in 0..hw[1] {
            let tt = map[i as usize][j as usize];
            if tt != -1 && tt != 1 {
