        A: [[i64; W]; H],
    }
    let mut dist = c;
    warchall_floyd(&mut dist);
    let mut ans = 0;
    for i in 0..H {
        for j in 0..W {
            if A[i][j] == -1 || A[i][j] == 1 {
                continue;
            }
