    ($iter:expr, $t:ty) => {
        $iter.next().unwrap().parse::<$t>().expect("Parse error")
    };
}
// =========
fn warshall_floyd(adjm: &mut Vec<Vec<Option<usize>>>) {
    let n = adjm.len();
    // kを経て短くなる辺を全部短くする
    for k in 0..n {
        for i in 0..n {
            for j in 0..n {
                if let (Some(dik), Some(djk)) = (adjm[i][k], adjm[k][j]) {
                    if adjm[i][j].is_none() || adjm[i][j].unwrap() > dik + djk {
                        adjm[i][j] = Some(dik + djk);
                    }
                }
            }
        }
    }
}
fn main() {
    input! {
        h: usize,
        w: usize,
        costs: [[usize;10];10],
        wall: [[i64;w];h]
    }
    let mut adjm: Vec<Vec<Option<usize>>> = vec![vec![None; 10]; 10];
    for i in 0..10 {
        for j in 0..10 {
            adjm[i][j] = Some(costs[i][j]);
        }
    }
    warshall_floyd(&mut adjm);
    // iを家として、最長の時間が最も短いもの
    let mut ans = 0;
    for i in 0..h {
        for j in 0..w {
            if wall[i][j] != -1 {
                ans += adjm[wall[i][j] as usize][1].unwrap();
            }
        }
    }
    println!("{:?}", ans);
}

