use proconio::input;
use std::collections::HashMap;
use std::collections::VecDeque;
use std::cmp::max;
use std::cmp::min;


fn main() {
    input! {
        H: usize,
        W: usize,
    }

    let mut Cs: Vec<Vec<i64>> = Vec::new();

    for _i in 0..10 {
        input! {
            tmp: [i64; 10],
        }

        let mut arr: Vec<i64> = Vec::new();
        arr.extend_from_slice(&tmp);
        Cs.push(arr);
    }

    let mut As: Vec<Vec<i64>> = Vec::new();

    for _h in 0..H {
        input! {
           tmp: [i64; W],
        }

        let mut arr: Vec<i64> = Vec::new();
        arr.extend_from_slice(&tmp);
        As.push(arr);
    }

    // まずi => jの最小コストを求めておく
    // Cost[i][j][n] : i から j へ n回以下のステップで行った時の最小コスト
    let mut Cost: Vec<Vec<Vec<i64>>> = Vec::new();
    for _ in 0..10 {
        let mut arr2: Vec<Vec<i64>> = Vec::new();

        for _ in 0..10 {
            // コストの最大値は10^3を10回積み重ねた10^4
            // なので、それを上回る10^6としておこう
            let arr1 = vec![1000_000i64; 10];
            arr2.push(arr1);
        }

        Cost.push(arr2);
    }

    // まずn == 1 の場合
    for i in 0..10 {
        for j in 0..10 {
            Cost[i][j][1] = Cs[i][j];
        }
    }

    for n in 2..10 {
        for i in 0..10 {
            for j in 0..10 {
                // 直接行くか、kを経由して行くか

                let mut cand: i64 = Cs[i][j];

                for k in 0..10 {
                    cand = min(cand, Cs[i][k] + Cost[k][j][n - 1]);
                }

                Cost[i][j][n] = cand;
            }
        }
    }

    let mut ans = 0;

    for h in 0..H {
        for w in 0..W {
            if As[h][w] == 1 || As[h][w] == -1 {
                continue;
            }

            let a = &As[h][w];
            ans += Cost[*a as usize][1][9];
        }
    }

    println!("{}", ans);
}

