fn solve(h: usize, w: usize, mut c: Vec<Vec<i32>>, a: &[Vec<i32>]) -> i32 {
    for k in 0..10 {
        for i in 0..10 {
            for j in 0..10 {
                c[i][j] = min(c[i][j], c[i][k] + c[k][j]);
            }
        }
    }
    (0..h)
        .map(|row| {
            (0..w)
                .map(|col| {
                    if a[row][col] >= 0 {
                        c[a[row][col] as usize][1]
                    } else {
                        0
                    }
                })
                .sum::<i32>()
            })
        .sum::<i32>()
}

