fn warchall_floyd(vertex: usize, cost: &mut Vec<Vec<usize>>) {
    for k in 0..vertex {
        for j in 0..vertex {
            for i in 0..vertex {
                let ij = cost[i][j];
                let ik = cost[i][k];
                let kj = cost[k][j];
                cost[i][j] = min(ij, ik + kj);
            }
        }
    }
}

