        if a >= 0 {
            cnt[a as usize] += 1;
        }
    }
    format!(
        "{}\n",
        cnt.iter()
            .zip(cst.iter())
            .map(|(&cnt, &cst)| cnt * cst)
            .sum::<usize>()
    )
}
fn shortest_paths_from(start: usize, neighbor: &[Vec<(usize, usize)>]) -> Vec<usize> {
    use std::cmp::Reverse;
    use std::collections::BinaryHeap;
    use std::iter::FromIterator;
    let n = neighbor.len();
    let mut dist = vec![usize::max_value() / 2; n];
    dist[start] = 0;
    let mut que: BinaryHeap<_> =
        FromIterator::from_iter(dist.iter().map(|&d| Reverse(d)).zip(0..n));
    while let Some((Reverse(d), u)) = que.pop() {
        for &(v, l) in &neighbor[u] {
            let alt = d + l;
            if dist[v] > alt {
                dist[v] = alt;
                que.push((Reverse(alt), v));
            }
        }
    }
    dist
}
