fn warshall_floyd(adj: &[Vec<i64>]) -> Vec<Vec<i64>> {
    let mut dists = vec![vec![std::i64::MAX; adj.len()]; adj.len()];
    for i in 0..adj.len() {
        for j in 0..adj.len() {
            dists[i][j] = adj[i][j];
        }
    }
    for i in 0..adj.len() {
        for j in 0..adj.len() {
            for k in 0..adj.len() {
                dists[j][k] = min(dists[j][i] + dists[i][k], dists[j][k]);
            }
        }
    }
    dists
}

