    }

    let mut distance = [0; 11];
    for start in 0..10 {
        let mut q: HashSet<usize> = HashSet::from_iter(0..10);
        let mut d = [std::usize::MAX; 10];
        d[start] = 0;
        while let Some(&prev) = q.iter().min_by_key(|&&v| d[v]) {
            if prev == 1 { break; }
