            for &v in q.iter() {
                d[v] = min!(d[v], d[prev] + c[prev][v]);
            }
        }
        distance[start+1] = d[1];
    }

    let ans: usize = A.into_iter().flatten().fold(0, |sum, v| sum + distance[(v+1) as usize]);
    println!("{}", ans);
}

