fn warshall_floyd(
    graph::MatrixGraph(mut vec): graph::MatrixGraph,
) -> Vec<Vec<Option<graph::Cost>>> {
    for k in 0..vec.len() {
        for i in 0..vec.len() {
            for j in 0..vec.len() {
                let now = vec[i][j];
                let new = match (vec[i][k], vec[k][j]) {
                    (Some(a), Some(b)) => Some(a + b),
                    _ => None,
                };
                vec[i][j] = match (now, new) {
                    (Some(a), Some(b)) => Some(min(a, b)),
                    (None, Some(x)) => Some(x),
                    (Some(x), None) => Some(x),
                    (None, None) => None,
                };
            }
        }
    }

    vec
}

