use std::collections::BinaryHeap;
use std::cmp::Ordering;

#[derive(Debug, PartialEq, Eq)]
struct State(usize, usize);

impl Ord for State {
    fn cmp(&self, other: &Self) -> Ordering {
        other.1.cmp(&self.1)
    }
}

impl PartialOrd for State {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

fn dijkstra(s: usize, t: usize, adj: &Vec<Vec<usize>>) -> Option<usize> {
    let n = adj.len();
    let mut pq = BinaryHeap::new();
    pq.push(State(s, 0));
    let mut dist = vec![usize::max_value(); n];
    dist[s] = 0;
    while let Some(st) = pq.pop() {
        if st.0 == t {
            return Some(st.1);
        }
        for i in 0..n {
            let d = st.1 + adj[st.0][i];
            if d < dist[i] {
                dist[i] = d;
                pq.push(State(i, d));
            }
        }
    }
    None
}

