pub fn warshall_floyd(matrix: &mut Vec<Vec<i64>>, inf: i64) {
    let n = matrix.len();
    assert_eq!(n, matrix[0].len());
    for k in 0..n {
        for i in 0..n {
            for j in 0..n {
                if matrix[i][k] == inf || matrix[k][j] == inf {
                    continue;
                }
                matrix[i][j] = std::cmp::min(matrix[i][j], matrix[i][k] + matrix[k][j]);
            }
        }
    }
}

