fn solve(c: Vec<Vec<u32>>, a: Vec<Vec<isize>>) -> u32 {
    let c = reduce(c);
    let mut r = 0;
    for l in a.into_iter() {
        for x in l.into_iter() {
            if x > 0 {
                r += c[x as usize][1];
            }
        }
    }
    r
}


fn reduce(mut c: Vec<Vec<u32>>) -> Vec<Vec<u32>> {
    for i in 2..10 {
        let mut nexts = [None; 10];
        for j in 0..10 {
            if j != 1 && j != i {
                nexts[j] = Some(c[i][j]);
            }
        }
        loop {
            if nexts.iter().all(Option::is_none) {
                break;
            }
            let mut nexts2 = [None; 10];
            for (j, l) in nexts.iter().cloned().enumerate() {
                if let Some(l) = l {
                    for k in 0..10 {
                        if l + c[j][k] < c[i][k] {
                            c[i][k] = l + c[j][k];
                            if k != 1 {
                                nexts2[k] = Some(c[i][k]);
                            }
                        }
                    }
                }
            }
            nexts = nexts2;
        }
    }
    c
}


